/* 自动生成，请勿手工修改。来源：DSH physics/phy-electric；重新生成：node scripts/build-learn-content.mjs */
module.exports = [{"id":"phy-electric-1","title":"电荷、电流与电路的三种状态","subtitle":"人教版九年级 · 第 15 章 电流和电路 · 9a","grade":"9a","tags":["人教版九年级 · 第 15 章 电流和电路"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 15 章 电流和电路 · 9a"},{"type":"note","title":"问题切入","text":"为什么摩擦过的塑料尺能吸起小纸屑，而两根同样摩擦过的橡胶棒却互相推开？电路里的电流究竟朝哪个方向流？为什么有的电路一接通就发烫，甚至烧坏电线？"},{"type":"note","title":"一句话抓住关键","text":"电荷的定向移动形成电流；在电源外部，电流由电源正极经用电器流向负极；电路只有处于通路才能工作，短路时电阻极小、电流极大，是必须避免的状态。"},{"type":"h","text":"先看现象：摩擦过的物体能吸引轻小物体"},{"type":"p","text":"用毛皮摩擦过的橡胶棒靠近纸屑，纸屑会被吸起来；用丝绸摩擦过的玻璃棒也能吸引纸屑。但把两根都用毛皮摩擦过的橡胶棒相互靠近时，它们却互相推开。这说明摩擦使物体带了电（电荷），而且电荷之间的相互作用只有两种：同种电荷相互排斥，异种电荷相互吸引。带电体还有一个本领：能吸引轻小的物体。"},{"type":"figure","figure":{"id":"fig-elec-charge-1","title":"两种电荷之间的相互作用","caption":"上排两个带负电的橡胶棒互相排斥，下排一正一负互相吸引","view":"wide","alt":"上排两个带负电的小球分别受到向外的力而互相排斥，下排一个带正电和一个带负电的小球受到向内的力而互相吸引","prims":[{"t":"circle","cx":30,"cy":20,"r":7,"label":"−","labelDx":0,"labelDy":0,"tone":"main"},{"t":"circle","cx":70,"cy":20,"r":7,"label":"−","labelDx":0,"labelDy":0,"tone":"main"},{"t":"arrow","x1":22,"y1":20,"x2":10,"y2":20,"tone":"accent","label":"F","labelDy":-4},{"t":"arrow","x1":78,"y1":20,"x2":90,"y2":20,"tone":"accent","label":"F","labelDy":-4},{"t":"text","x":50,"y":33,"text":"同种电荷相互排斥","size":3.8,"tone":"muted"},{"t":"circle","cx":30,"cy":48,"r":7,"label":"+","labelDx":0,"labelDy":0,"tone":"main"},{"t":"circle","cx":70,"cy":48,"r":7,"label":"−","labelDx":0,"labelDy":0,"tone":"main"},{"t":"arrow","x1":24,"y1":48,"x2":36,"y2":48,"tone":"accent","label":"F","labelDy":-4},{"t":"arrow","x1":76,"y1":48,"x2":64,"y2":48,"tone":"accent","label":"F","labelDy":-4},{"t":"text","x":50,"y":60,"text":"异种电荷相互吸引","size":3.8,"tone":"muted"}]}},{"type":"note","title":"","text":"规定：用丝绸摩擦过的玻璃棒所带的电荷叫正电荷，用毛皮摩擦过的橡胶棒所带的电荷叫负电荷。判断相互作用的题目，先看清「谁和谁靠近」。"},{"type":"h","text":"抓住哪个量：电流是电荷的定向移动"},{"type":"p","text":"电荷一旦持续地定向移动，就形成了电流。金属导体里能移动的是自由电子（带负电），酸、碱、盐的水溶液里能移动的是正离子和负离子。物理学规定正电荷定向移动的方向为电流的方向，因此在电源外部，电流从电源正极流出，经过用电器回到电源负极；在电源内部，电流由负极流向正极，这样才能构成闭合的电流路径。电流用 I 表示，单位是安培（A），1 A = 1000 mA。"},{"type":"figure","figure":{"id":"fig-elec-current-1","title":"电流的方向：电源外部由正极流向负极","caption":"沿导线绕行一圈，电流表串联在电路中测电流","view":"wide","alt":"电源、开关、电流表、灯泡依次串联成闭合回路，箭头标出电流从电源正极流出，经左侧导线、电流表、灯泡、右侧导线回到负极","prims":[{"t":"line","x1":18,"y1":16,"x2":30,"y2":16},{"t":"line","x1":41,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":25.4,"y2":48},{"t":"line","x1":42.6,"y1":48,"x2":59.4,"y2":48},{"t":"line","x1":76.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":34,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"meter","x":34,"y":48,"kind":"A","label":"电流表"},{"t":"bulb","x":68,"y":48,"label":"L"},{"t":"arrow","x1":29,"y1":16,"x2":20,"y2":16,"tone":"accent","label":"I"},{"t":"arrow","x1":18,"y1":22,"x2":18,"y2":34,"tone":"accent"},{"t":"arrow","x1":60,"y1":48,"x2":74,"y2":48,"tone":"accent","label":"I"},{"t":"arrow","x1":82,"y1":42,"x2":82,"y2":30,"tone":"accent"}]}},{"type":"note","title":"","text":"注意两点：一是电流方向的规定针对「正电荷」，二是金属导体中自由电子的定向移动方向与电流方向相反。"},{"type":"h","text":"电路要工作，必须绕行一圈：通路与断路"},{"type":"p","text":"把电源、用电器、开关用导线连接起来的电流路径叫电路。开关闭合、电流能沿导线绕行一圈的状态叫通路，这时用电器工作；开关断开，或导线某处接触不良、灯丝烧断，电流的路径不闭合，叫断路（开路），电路中各处的电流都为零，用电器停止工作。判断状态的方法很固定：沿着导线走一圈，能回到电源的另一极且经过用电器，就是通路。"},{"type":"figure","figure":{"id":"fig-elec-open-1","title":"断路：开关断开，电流走不通","caption":"开关断开时路径不闭合，灯泡中没有电流，所以不发光","view":"wide","alt":"由电源、开关、灯泡组成的串联电路，开关处于断开状态，电路中没有任何电流","prims":[{"t":"line","x1":18,"y1":16,"x2":30,"y2":16},{"t":"line","x1":41,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":41.4,"y2":48},{"t":"line","x1":58.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":34,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":false,"label":"S"},{"t":"bulb","x":50,"y":48,"label":"L"},{"t":"text","x":50,"y":34,"text":"断开了，电流为零","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"断路不等于「用电器坏了」：导线松脱、开关断开同样是断路。断路时用电器两端也没有电压。"},{"type":"h","text":"短路为什么危险"},{"type":"p","text":"如果不经过用电器，用一根导线把电源的两极直接连接起来，电源和这段导线就构成了短路。导线的电阻极小，由 I = U/R 可知电流会非常大，电源会迅速发热、损坏，导线也可能烧起来。所以连接电路时开关必须先断开，接好检查无误后再闭合；任何时候都不允许把电源两极用导线直接连起来。"},{"type":"figure","figure":{"id":"fig-elec-short-1","title":"电源短路：导线直接把电源两极连起来","caption":"电流绕开了所有用电器，电阻极小、电流极大","view":"wide","alt":"一根导线从电源正极出发向下绕一圈直接接回电源负极，形成电源短路，导线中的电流很大","prims":[{"t":"battery","x":50,"y":14,"label":"电源"},{"t":"line","x1":46,"y1":14,"x2":30,"y2":14,"tone":"danger"},{"t":"line","x1":30,"y1":14,"x2":30,"y2":34,"tone":"danger"},{"t":"line","x1":30,"y1":34,"x2":70,"y2":34,"tone":"danger"},{"t":"line","x1":70,"y1":34,"x2":70,"y2":14,"tone":"danger"},{"t":"line","x1":70,"y1":14,"x2":57,"y2":14,"tone":"danger"},{"t":"arrow","x1":36,"y1":34,"x2":62,"y2":34,"tone":"danger","label":"I 很大"},{"t":"text","x":50,"y":45,"text":"导线直接连接电源两极","size":3.8,"tone":"danger"},{"t":"text","x":50,"y":53,"text":"电流过大，会烧坏电源与导线","size":3.8,"tone":"danger"}]}},{"type":"note","title":"","text":"还要区分「用电器被短路」：某个用电器被导线并联后它不工作，但电路整体仍有电流——这与断路「哪里都没有电流」完全不同。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["电流的定义式","I = (Q)/(t)","I：电流，单位安培（A）；Q：电荷量，单位库仑（C）；t：时间，单位秒（s） · 已知电荷量与时间求电流，或求某段时间内通过的电荷量时使用；变形为 Q = It 可求电荷量、t = Q/t 变形式可求时间。这是电流的定义式，与导体的电阻、电压无关，不能用来由电压和电阻求电流——那种情况要用欧姆定律 I = U/R。使用时时间必须换成秒，电流与电荷量要对应同一段导体、同一段时间（同时性）。"],["电流方向的规定","正电荷定向移动的方向规定为电流的方向","只用于判断方向：在电源外部，电流由电源正极流出、经用电器回到负极；在电源内部由负极流向正极。金属导体中自由电子带负电，它的定向移动方向与电流方向相反，不能把两者混为一谈。"],["电荷量单位换算","1 A = 1000 mA；1 mA = 1000 μA","只在单位换算与估测中使用：家用白炽灯正常工作电流约 0.2 A，电饭锅约 3～4 A，电子手表约几微安。比较电流大小、填写单位前，先把所有量换成同一单位。"]]},{"type":"h","text":"应用 · 用电流的定义式求电流"},{"type":"note","title":"情境","text":"一段金属导体在 5 s 内通过了 10 C 的电荷量，求导体中的电流。"},{"type":"note","title":"模型与思路","text":"电流表示单位时间内通过导体横截面的电荷量，已知电荷量与时间，用定义式 I=(Q)/(t) 求解；Q 用库仑（C）、t 用秒（s），得到的 I 单位就是安培（A），不需要换算。"},{"type":"list","title":"解答步骤","items":["写出定义式 I = Q/t。","代入数据：I = 10 C ÷ 5 s。","计算并写单位：I = 2 A。","作答：这段导体中的电流为 2 A。"]},{"type":"figure","figure":{"id":"fig-elec-current-2","title":"电流表串联测导体中的电流","caption":"电流表与被测导体串联，读数就是通过导体的电流","view":"wide","alt":"电源、开关、电流表与一段电阻丝串联成闭合回路，电流表串联在干路中测量通过电阻丝的电流","prims":[{"t":"line","x1":18,"y1":16,"x2":26,"y2":16},{"t":"line","x1":37,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":21.4,"y2":48},{"t":"line","x1":38.6,"y1":48,"x2":44,"y2":48},{"t":"line","x1":66,"y1":48,"x2":82,"y2":48},{"t":"battery","x":30,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"meter","x":30,"y":48,"kind":"A","label":"电流表"},{"t":"resistor","x":55,"y":48,"label":"导体"}]}},{"type":"note","title":"结论","text":"I = 2 A，相当于 2000 mA。"},{"type":"h","text":"应用 · 手电筒的电路：为什么按下按钮就亮"},{"type":"note","title":"情境","text":"手电筒里有电池、小灯泡、按钮开关和金属外壳。按下按钮灯就亮，松开就灭。"},{"type":"note","title":"模型与思路","text":"把金属外壳看成导线，按下按钮相当于开关闭合，电流从电池正极经金属外壳、灯丝回到负极，电路是通路；松开按钮相当于开关断开，电路变成断路。"},{"type":"list","title":"解答步骤","items":["找出电源：两节干电池串联，长线一端是正极。","沿着金属外壳走一圈，判断路径是否闭合。","按下按钮时路径闭合、经过灯丝，是通路，灯发光。","松开按钮时路径断开，是断路，灯不发光。"]},{"type":"figure","figure":{"id":"fig-elec-current-3","title":"手电筒的电路图","caption":"电池组、按钮开关与灯泡串联，开关控制整个电路","view":"wide","alt":"两节干电池串联组成电池组，与按钮开关和灯泡串联成回路，开关闭合时灯泡发光","prims":[{"t":"line","x1":18,"y1":16,"x2":26,"y2":16},{"t":"line","x1":40,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":41.4,"y2":48},{"t":"line","x1":58.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":30,"y":16,"cells":2,"label":"电池组"},{"t":"switch","x":68,"y":16,"closed":true,"label":"按钮开关"},{"t":"bulb","x":50,"y":48,"label":"小灯泡"}]}},{"type":"note","title":"结论","text":"开关的作用是控制电路的通断，它必须与用电器串联。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["摩擦起电创造了电荷，所以物体带上了电","摩擦起电只是电荷的转移，电荷的总量并没有增加","摩擦时电子从一个物体转移到另一个物体，得到电子的物体带负电、失去电子的物体带正电，两个物体带的是等量的异种电荷，电荷总量守恒。"],["金属导体中自由电子定向移动的方向就是电流的方向","金属导体中电流的方向与自由电子定向移动的方向相反","规定正电荷定向移动的方向为电流方向，自由电子带负电，它向左移动与正电荷向右移动产生的效果相同，所以两者方向相反。"],["某个用电器被短路了，就是断路，电路中不再有电流","被短路的用电器不工作，但电路整体仍然有电流，而且电流比原来更大","短路是与用电器并联了一条电阻几乎为零的导线，电流从导线通过，用电器两端电压几乎为零；因为电路总电阻变小，干路电流反而增大。"],["只要电路中有电源，用电器就能工作","电路必须是通路、且有电流通过用电器，用电器才能工作","有电源只是有了电压，若开关断开、导线断路，或者用电器被短路，用电器中都没有电流，都不会工作。"]]},{"type":"table","title":"通路与断路（同一电路在两种状态下的表现）","head":["比较项","通路","断路"],"rows":[["开关状态","闭合","断开（或导线某处断开）"],["电流路径","沿导线能绕行一圈回到电源另一极","路径不闭合，中途断开"],["电流大小","各处都有电流","电路中各处电流都为零"],["用电器","正常工作","停止工作"]]},{"type":"table","title":"电流方向在不同位置的规定（判断方向时先分清「在电源外部」还是「在电源内部」）","head":["比较项","电源外部","电源内部"],"rows":[["电流方向","由正极流出，经用电器回到负极","由负极流向正极"],["金属中的自由电子","移动方向与电流方向相反","不适用（电源内部靠化学作用搬运电荷）"],["常见考法","在电路图上标电流方向","判断闭合回路的电流方向是否自成循环"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["电荷间相互作用的判断","给出几个悬挂的轻质小球相互靠近时吸引或排斥的现象，判断带电情况。关键口径：排斥一定是同种电荷；吸引有两种可能——异种电荷，或带电体吸引不带电的轻小物体，因此「吸引」不能确定对方带电。"],["电路三种状态的辨识","给实物图或电路图，判断是通路、断路还是短路，并说明用电器能否工作、哪部分被短路。常与「连接电路时开关应断开」的操作要求合并考查。"],["电流方向与自由电子移动方向","以金属导体、电解液导电为情境，判断电流方向、自由电子移动方向以及电源内部电流的方向，属于容易失分的概念题。"],["静电现象的应用与防护","以加油站防静电、油罐车拖铁链、静电除尘、静电复印为情境，考摩擦起电、电荷转移与放电，并要求用「电流路径」解释接地的作用。"]]},{"type":"quote","text":"【材料一】冬天用塑料梳子梳头发，头发会随着梳子飘起来；脱毛衣时常听到「噼啪」声，在暗处还能看见小火花。这是因为摩擦使物体带了电：摩擦时电子从一个物体转移到另一个物体，两个物体因此带上等量的异种电荷。同种电荷相互排斥，异种电荷相互吸引，带电体还能吸引轻小的物体。\n【材料二】加油站规定：加油前必须用手触摸金属接地装置；油罐车行驶时车尾要拖一条铁链。运输、加注汽油时，油与罐壁、管道摩擦会使电荷不断积累，积累到一定程度就会放电产生火花，而汽油蒸气遇火花即可燃烧。铁链或接地装置的作用，就是给这些电荷提供一条通向大地的路径。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】梳头发时头发随着梳子飘起来。梳子与头发所带的是同种电荷还是异种电荷？请说明理由。（3 分）","【设问】油罐车的铁链为什么要拖在地上而不能悬空？请从「电荷的转移需要通路」的角度解释。（3 分）","【设问】一次摩擦过程中，某物体失去了 $2\\times10^{10}$ 个电子。已知每个电子所带的电荷量为 $1.6\\times10^{-19}$ C，求该物体所带电荷量的大小，并判断它带哪种电荷。（4 分）"]}],"questions":[{"id":"phy-electric-1-q1","type":"choice","stem":"如图是某同学连接的电路。关于该电路此时的状态，下列说法正确的是","answer":"A","explain":"开关断开时电流路径不闭合，属于断路，灯泡中没有电流，所以不发光，A 正确。B 错：断路时电路中各处电流都为零，不存在「电流流到灯泡」。C 错：短路是用导线把电源两极或用电器两端直接连通，此时只是开关断开，导线上并没有短接电源两极，构不成短路。D 错：图中导线并未跨接在灯泡两端，灯泡不是被短路，而是没有电流通过。","options":["开关断开，电路处于断路状态，灯泡不发光","开关断开，电流仍能从电源正极流到灯泡","此时电路处于短路状态，会烧坏电源","灯泡不发光，是因为灯泡两端被导线直接连起来了"],"difficulty":1,"tags":["电路三种状态"],"figure":{"id":"fig-elec-state-1","title":"待判断的电路","caption":"看开关与导线，判断这是什么状态","view":"wide","alt":"电源、开关、灯泡组成的电路，开关处于断开状态，导线没有跨接在灯泡两端","prims":[{"t":"line","x1":18,"y1":16,"x2":30,"y2":16},{"t":"line","x1":41,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":41.4,"y2":48},{"t":"line","x1":58.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":34,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":false,"label":"S"},{"t":"bulb","x":50,"y":48,"label":"L"}]}},{"id":"phy-electric-1-q2","type":"choice","stem":"关于电流的方向，下列说法正确的是","answer":"B","explain":"B 正确，这是电流方向的规范表述。A 错：金属导体中自由电子带负电，它定向移动的方向与规定的电流方向相反。C 错：在电源内部电流由负极流向正极，只有这样电流路径才能闭合，若内部也由正极流向负极，就无法形成持续电流。D 错：负电荷的定向移动同样能形成电流，规定「正电荷定向移动的方向」只是为了统一方向，并不是说只有正电荷能形成电流。","options":["金属导体中自由电子定向移动的方向就是电流的方向","在电源外部，电流由电源正极流出，经用电器回到电源负极","在电源内部，电流也是由正极流向负极","只有正电荷的定向移动才能形成电流"],"difficulty":2,"tags":["电流方向"]},{"id":"phy-electric-1-q3","type":"choice","stem":"用毛皮摩擦过的橡胶棒带负电。把它依次靠近悬挂的轻质小球甲和乙，发现甲被吸引，乙被排斥。下列判断正确的是","answer":"C","explain":"乙被排斥，说明乙与橡胶棒带同种电荷，一定带负电，这一点是确定的。甲被吸引有两种可能：甲带正电（异种电荷相互吸引），或者甲不带电（带电体能吸引轻小的不带电物体），因此不能确定甲一定带电，A、B、D 都犯了「把吸引当成一定带电」的错误。","options":["甲一定带正电，乙一定带负电","甲一定带正电，乙可能不带电","乙一定带负电，甲可能带正电，也可能不带电","甲、乙都一定带电"],"difficulty":2,"tags":["电荷相互作用"]},{"id":"phy-electric-1-q4","type":"choice","stem":"关于电路的三种状态，下列说法正确的是","answer":"D","explain":"D 正确：用电器被短路后电流从导线流过，被短路的用电器不工作，而电路总电阻变小，干路电流比原来更大。A 错：电源两极被导线直接连接是电源短路，电流极大，会烧坏电源和导线。B 错：短路时电路中有很大的电流，断路时电流为零，两者完全不同。C 错：有电源还要电路是通路，用电器中才有电流。","options":["把导线直接接在电源两极上没有什么危害，只是灯不亮","短路就是断路，两种情况下电路中的电流都为零","只要电路中有电源，用电器就一定能工作","用电器被短路时该用电器不工作，此时电路中的电流比原来更大"],"difficulty":1,"tags":["短路","断路"]},{"id":"phy-electric-1-q5","type":"fill","stem":"某导体中通过 6 C 的电荷量用时 3 s，则导体中的电流是 ______ A。","answer":"2|2 A|2A","explain":"由电流的定义式 I = Q/t 得 I = 6 C ÷ 3 s = 2 A。填空要写数值与单位，时间若不是秒要先换算；本题也可以用 I = Q/t 的变形 Q = It 验算：2 A × 3 s = 6 C，与题目一致。","difficulty":1,"tags":["电流定义式","计算"]},{"id":"phy-electric-1-q6","type":"short","stem":"手电筒正常工作时，通过灯丝的电流是 0.3 A。求：（1）通电 1 min 通过灯丝横截面的电荷量；（2）若把电流调到 0.2 A，通电 10 s 通过灯丝横截面的电荷量又是多少？","answer":"（1）1 min = 60 s，Q = It = 0.3 A × 60 s = 18 C；（2）Q′ = I′t′ = 0.2 A × 10 s = 2 C。","explain":"为什么这么做：电流是表示电流强弱的物理量，它等于 1 s 内通过导体横截面的电荷量，所以电荷量等于电流与通电时间的乘积，用 Q = It。两个关键点：一是时间必须换成秒；二是电流、电荷量、时间必须对应同一段导体、同一段时间（同时性），所以第（2）问要用 0.2 A 与 10 s 配对，不能把第（1）问的电流和时间拿来混用。","difficulty":2,"tags":["电流定义式","计算"],"rubric":["写出公式 Q = It（1 分）","把 1 min 正确换算成 60 s（1 分）","第（1）问结果 18 C，单位正确（1 分）","第（2）问用 0.2 A 与 10 s 配对，结果 2 C（1 分）"],"steps":["（1）单位换算：t = 1 min = 60 s。","由 I = Q/t 变形得 Q = It。","代入：Q = 0.3 A × 60 s = 18 C。","（2）Q′ = I′t′ = 0.2 A × 10 s = 2 C。","答：通电 1 min 通过灯丝横截面的电荷量是 18 C；调小电流后 10 s 内通过 2 C。"]},{"id":"phy-electric-1-q7","type":"short","stem":"实验室里有毛皮、橡胶棒、丝绸、玻璃棒和一个验电器。请你设计实验：(1) 检验一个物体是否带电；(2) 判断这个物体带的是正电荷还是负电荷。写出器材、操作步骤、现象与结论。","answer":"(1) 用待测物体接触验电器的金属球，若金属箔张开，说明物体带电；若金属箔不张开，说明物体不带电。(2) 先用毛皮摩擦过的橡胶棒接触验电器的金属球，使验电器带上负电（金属箔张开一定角度），再用待测物体去接触金属球：若金属箔的张角变大，说明待测物体带的也是负电荷；若张角变小甚至闭合后重新张开，说明待测物体带正电荷。","explain":"设计的关键是「同种电荷相互排斥」：验电器的金属箔能张开，就是因为两片箔带上了同种电荷而互相排斥。判断电荷种类时，必须先让验电器带上一份已知电荷（用毛皮摩擦过的橡胶棒使它带负电），再用待测物体去接触，靠张角变大还是变小来判断同种还是异种。容易忽略的细节：手不能直接接触金属球，否则人体会把电荷导走；实验前要保持金属球和金属箔干燥。","difficulty":3,"tags":["实验探究","验电器"],"rubric":["器材与对象明确：验电器、毛皮、橡胶棒（1 分）","检验是否带电：用物体接触金属球，看金属箔是否张开（1 分）","判断电荷种类：先使验电器带已知的负电荷，再比较金属箔张角的变化（1 分）","说明原理：同种电荷相互排斥，张角变大是同种、变小是异种（1 分）"]},{"id":"phy-electric-1-q8","type":"short","stem":"请画出符合下列要求的电路图：两节干电池串联组成电池组，开关 S 与灯泡 L 串联，开关 S 能控制整个电路。","answer":"见参考答案图：电池组、开关、灯泡依次串联成一条闭合回路，开关接在电池组与灯泡之间。","explain":"画电路图的规范：导线用直线、拐角画成直角；元件符号画在导线中间并留出引线；开关要串联在电路中才能控制整个电路。若把开关与灯泡并联，闭合开关会把灯泡短路（灯泡不亮），这就达不到「控制」的要求，是常见的错误画法。","difficulty":2,"tags":["电路作图"],"rubric":["电源、开关、灯泡依次相连，画成一条闭合的串联回路（1 分）","开关与灯泡串联，能控制整个电路，没有把开关并联在灯泡两端（1 分）","符号与画法规范：电池组长线正极、灯泡圆圈带叉，导线画直、拐角为直角、导线不悬空（1 分）"],"answerFigure":{"id":"fig-elec-draw-1-ans","title":"参考答案：电池组、开关与灯泡串联","caption":"开关串联在干路中，能控制整个电路","view":"wide","alt":"两节干电池串联的电池组与开关、灯泡依次串联成闭合回路，开关位于电池组与灯泡之间","prims":[{"t":"line","x1":18,"y1":16,"x2":26,"y2":16},{"t":"line","x1":40,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":41.4,"y2":48},{"t":"line","x1":58.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":30,"y":16,"cells":2,"label":"电池组"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"bulb","x":50,"y":48,"label":"L"}]}},{"id":"phy-electric-1-m1-q1","type":"short","stem":"梳头发时头发随着梳子飘起来。梳子与头发所带的是同种电荷还是异种电荷？请说明理由。（3 分）","answer":"异种电荷。梳子与头发摩擦时发生了电子的转移，两者带的是等量的异种电荷；异种电荷相互吸引，所以头发被梳子吸引而飘起来。","explain":"","tags":["两种电荷","摩擦起电"],"rubric":["答出「异种电荷」（1 分）","说明摩擦使电子发生转移、两物体带等量异种电荷（1 分）","用「异种电荷相互吸引」解释飘起的现象（1 分）"]},{"id":"phy-electric-1-m1-q2","type":"short","stem":"油罐车的铁链为什么要拖在地上而不能悬空？请从「电荷的转移需要通路」的角度解释。（3 分）","answer":"铁链拖在地上才能与大地接触，使油罐车、铁链、大地构成一条通路，摩擦产生的电荷可以沿铁链不断转移到大地，不会积累；如果铁链悬空，电荷无处转移就会越积越多，电压升高到一定程度会放电产生火花，可能点燃汽油蒸气。","explain":"","tags":["静电防护"],"rubric":["答出铁链必须与大地接触才能把电荷导走（1 分）","说明悬空时电荷无法转移、会不断积累（1 分）","指出积累到一定程度会放电产生火花，有引燃危险（1 分）"]},{"id":"phy-electric-1-m1-q3","type":"short","stem":"一次摩擦过程中，某物体失去了 2×10¹⁰ 个电子。已知每个电子所带的电荷量为 1.6×10^(-19) C，求该物体所带电荷量的大小，并判断它带哪种电荷。（4 分）","answer":"失去电子，物体带正电；电荷量 Q = 2×10^10 × 1.6×10^-19 C = 3.2×10^-9 C。","explain":"","tags":["电荷量","计算"],"rubric":["判断出失去电子带正电（1 分）","写出 Q = ne 的关系（1 分）","代入计算得 3.2×10^-9 C（1 分）","结果带单位并写出电荷种类（1 分）"]}]},{"id":"phy-electric-2","title":"串联与并联：识别、作图与电流路径分析","subtitle":"人教版九年级 · 第 15 章 电流和电路 · 9a","grade":"9a","tags":["人教版九年级 · 第 15 章 电流和电路"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 15 章 电流和电路 · 9a"},{"type":"note","title":"问题切入","text":"两个灯泡接在同一个电源上，怎么一眼看出它们是串联还是并联？从实物图到电路图，怎么画才不出错、不把两灯画成互相影响的样子？"},{"type":"note","title":"一句话抓住关键","text":"看电流路径：从电源一极出发到另一极，如果只有一条路径、中途不分支，就是串联；如果路径在某处分开、又在另一处会合，有两条或更多条路径，就是并联。用电器能不能互相影响，是判断的连接法，而拉出电流路径就是判断的手段。"},{"type":"h","text":"先看现象：两种接法，灯泡的表现不一样"},{"type":"p","text":"把两只灯泡 L1、L2 和一个开关串联起来接在电源上：闭合开关时两灯都亮，断开时都灭；把其中一只灯泡取下来，另一只也不亮了。这说明串联电路里只有一个电流的通道，任何一处断开，整条路径都断了。"},{"type":"figure","figure":{"id":"fig-elec-series-1","title":"串联电路：只有一条电流路径","caption":"两灯首尾依次相接，开关控制整个电路","view":"wide","alt":"电源、开关、灯泡 L1 与 L2 依次首尾相接成一条回路的串联电路","prims":[{"t":"line","x1":18,"y1":16,"x2":22,"y2":16},{"t":"line","x1":33,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":26.4,"y2":48},{"t":"line","x1":43.6,"y1":48,"x2":56.4,"y2":48},{"t":"line","x1":73.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":26,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"bulb","x":35,"y":48,"label":"L1"},{"t":"bulb","x":65,"y":48,"label":"L2"}]}},{"type":"note","title":"","text":"串联电路的特点：电流只有一条路径，电流处处相等，各元件互相影响，开关在哪个位置都能控制整个电路。"},{"type":"h","text":"再看另一种接法：首首相连、尾尾相连就是并联"},{"type":"p","text":"把两只灯泡的两端分别接到一起，再一起接到电源的两极上，电流从电源一极出来后分成两条路，分别经过两只灯泡，最后又汇合回到电源另一极——这就是并联。并联电路中，从电源出来一直到分支点的那段导线叫干路，分支以后的每一段叫支路。取下任意一只灯泡，另一只仍然发光，说明支路上的用电器互不影响。"},{"type":"figure","figure":{"id":"fig-elec-parallel-1","title":"并联电路：两条支路在结点处分与合","caption":"导线相接处画结点，L1 与 L2 各占一条支路","view":"wide","alt":"电源在干路上，电流经左侧导线分成两条支路，分别经过灯泡 L1 和 L2 后在右侧重新汇合，结点用实心点标出","prims":[{"t":"line","x1":20,"y1":14,"x2":47,"y2":14},{"t":"line","x1":58,"y1":14,"x2":82,"y2":14},{"t":"line","x1":20,"y1":14,"x2":20,"y2":45},{"t":"line","x1":82,"y1":14,"x2":82,"y2":45},{"t":"line","x1":20,"y1":27,"x2":42.4,"y2":27},{"t":"line","x1":59.6,"y1":27,"x2":82,"y2":27},{"t":"line","x1":20,"y1":45,"x2":42.4,"y2":45},{"t":"line","x1":59.6,"y1":45,"x2":82,"y2":45},{"t":"battery","x":51,"y":14,"label":"电源"},{"t":"bulb","x":51,"y":27,"label":"L1"},{"t":"bulb","x":51,"y":45,"label":"L2"},{"t":"junction","x":20,"y":27},{"t":"junction","x":82,"y":27}]}},{"type":"note","title":"","text":"并联电路的特点：电流有多条路径，干路电流等于各支路电流之和，各支路互不影响，干路开关控制整个电路，支路开关只控制本支路。"},{"type":"h","text":"电流路径分析法：一支铅笔沿着导线走一圈"},{"type":"p","text":"识别电路最稳的办法是「走路径」：从电源正极出发，用一支笔沿着导线描，遇到分岔就分开描。如果描到某处又回到了已经走过的路径，而不经过用电器，那一段就是短路。串联电路的描线一笔走完全程、中途不分支；并联电路一定会分成两条或更多条，再汇合。这个方法对实物图和电路图都适用。"},{"type":"figure","figure":{"id":"fig-elec-path-1","title":"用电流路径判断并联","caption":"干路电流 I 在结点处分成 I₁ 与 I₂，汇合后仍是 I","view":"wide","alt":"并联电路中箭头标出干路电流 I 在左侧结点分成支路电流 I1 和 I2，经过两灯后在右侧结点汇合成 I 回到电源","prims":[{"t":"line","x1":20,"y1":14,"x2":47,"y2":14},{"t":"line","x1":58,"y1":14,"x2":82,"y2":14},{"t":"line","x1":20,"y1":14,"x2":20,"y2":45},{"t":"line","x1":82,"y1":14,"x2":82,"y2":45},{"t":"line","x1":20,"y1":27,"x2":42.4,"y2":27},{"t":"line","x1":59.6,"y1":27,"x2":82,"y2":27},{"t":"line","x1":20,"y1":45,"x2":42.4,"y2":45},{"t":"line","x1":59.6,"y1":45,"x2":82,"y2":45},{"t":"battery","x":51,"y":14,"label":"电源"},{"t":"bulb","x":51,"y":27,"label":"L1"},{"t":"bulb","x":51,"y":45,"label":"L2"},{"t":"junction","x":20,"y":27},{"t":"junction","x":82,"y":27},{"t":"arrow","x1":46,"y1":14,"x2":26,"y2":14,"tone":"accent","label":"I 干路"},{"t":"arrow","x1":20,"y1":18,"x2":20,"y2":24,"tone":"accent","label":"I","labelDx":5,"labelDy":0},{"t":"arrow","x1":24,"y1":27,"x2":40,"y2":27,"tone":"accent","label":"I₁"},{"t":"arrow","x1":20,"y1":30,"x2":20,"y2":43,"tone":"accent","label":"I","labelDx":5,"labelDy":0},{"t":"arrow","x1":24,"y1":45,"x2":40,"y2":45,"tone":"accent","label":"I₂"},{"t":"arrow","x1":82,"y1":42,"x2":82,"y2":30,"tone":"accent","label":"I","labelDx":5,"labelDy":0},{"t":"arrow","x1":81,"y1":14,"x2":60,"y2":14,"tone":"accent","label":"I 干路"}]}},{"type":"note","title":"","text":"口径：看两只灯泡是不是「各自有一条路」，而不是看它们同时亮还是同时灭——并联电路若开关在干路，也会同时亮、同时灭。"},{"type":"h","text":"换个情境再想一遍：实物图怎么变成电路图"},{"type":"p","text":"从实物图整理电路图，按三步走：一是标出电源的正负极和开关；二是沿着导线找分支点，把元件按电流路径归类到干路或支路；三是按「导线画直、拐角画直角、元件符号居中」的规范画成电路图。整理时不要把实物摆放的位置关系照搬到图纸上，图纸上只保留连接关系。"},{"type":"figure","figure":{"id":"fig-elec-parallel-2","title":"整理后的电路图：两灯并联、开关在干路","caption":"元件按路径归类后重新排布，位置与实物摆放无关","view":"wide","alt":"电源与开关串联在干路上，两只灯泡分别接在两条并联支路上的电路图","prims":[{"t":"line","x1":20,"y1":14,"x2":26,"y2":14},{"t":"line","x1":37,"y1":14,"x2":62,"y2":14},{"t":"line","x1":74,"y1":14,"x2":82,"y2":14},{"t":"line","x1":20,"y1":14,"x2":20,"y2":45},{"t":"line","x1":82,"y1":14,"x2":82,"y2":45},{"t":"line","x1":20,"y1":27,"x2":42.4,"y2":27},{"t":"line","x1":59.6,"y1":27,"x2":82,"y2":27},{"t":"line","x1":20,"y1":45,"x2":42.4,"y2":45},{"t":"line","x1":59.6,"y1":45,"x2":82,"y2":45},{"t":"battery","x":30,"y":14,"label":"电源"},{"t":"switch","x":68,"y":14,"closed":true,"label":"S"},{"t":"bulb","x":51,"y":27,"label":"L1"},{"t":"bulb","x":51,"y":45,"label":"L2"},{"t":"junction","x":20,"y":27},{"t":"junction","x":82,"y":27}]}},{"type":"note","title":"","text":"作图常见错误：把并联的两灯画成首尾相接（变成串联）；把结点画成导线交叉（交叉不画点是表示不相连）；开关画在支路上却要求控制两灯。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["串联电路的电流规律","I = I₁ = I₂","I、I₁、I₂：电流，单位安培（A） · 只适用于串联电路：串联电路中各处电流都相等，与元件的种类、位置、大小无关。解题时若题目给出「串联」，可直接把电流当作已知量在整条电路中通用；反过来，若测得两处电流不相等，就一定不是串联（而是并联）。"],["并联电路的电流规律","I = I₁ + I₂","I：干路电流；I₁、I₂：各支路电流，单位都为安培（A） · 只适用于并联电路。式中 I 必须是干路电流（在分支点之前或汇合点之后测量），I₁、I₂ 必须是各支路的电流，不能把干路电流当成某条支路的电流相加。变形 I₁ = I − I₂ 可用来求某条支路的电流。"],["串联总电阻的定性判断","R = R₁ + R₂","R、R₁、R₂：电阻，单位欧姆（Ω） · 用于串联电路的等效替换与定性分析：串联相当于导体变长，总电阻一定大于其中任何一个电阻。判断动态变化时常用它的推论——串联的用电器越多，总电阻越大，电流越小。并联（相当于导体变粗）时总电阻比任何一个支路电阻都小，具体计算见第 17 章。"]]},{"type":"h","text":"应用 · 并联电路中的电流计算"},{"type":"note","title":"情境","text":"某电路中灯泡 L1 与 L2 并联，通过 L1 的电流是 0.3 A，通过 L2 的电流是 0.2 A。求干路中的电流，以及通电 1 min 干路中通过的电荷量。"},{"type":"note","title":"模型与思路","text":"并联电路的干路电流等于各支路电流之和，即 I = I₁ + I₂；再用电荷量的定义式 Q = It 求通过的电荷量，时间用秒。"},{"type":"list","title":"解答步骤","items":["判断电路结构：L1、L2 并联，干路电流是两条支路电流之和。","I = I₁ + I₂ = 0.3 A + 0.2 A = 0.5 A。","时间换算：t = 1 min = 60 s。","Q = It = 0.5 A × 60 s = 30 C。","答：干路电流为 0.5 A，1 min 内通过干路的电荷量为 30 C。"]},{"type":"figure","figure":{"id":"fig-elec-parallel-3","title":"电流表测干路电流的位置","caption":"电流表串联在干路上时，测得的是两条支路电流之和","view":"wide","alt":"两只灯泡并联，电流表串联在电池组与分支点之间的干路上，测的是干路电流","prims":[{"t":"line","x1":20,"y1":14,"x2":21.4,"y2":14},{"t":"line","x1":38.6,"y1":14,"x2":47,"y2":14},{"t":"line","x1":58,"y1":14,"x2":82,"y2":14},{"t":"line","x1":20,"y1":14,"x2":20,"y2":45},{"t":"line","x1":82,"y1":14,"x2":82,"y2":45},{"t":"line","x1":20,"y1":27,"x2":42.4,"y2":27},{"t":"line","x1":59.6,"y1":27,"x2":82,"y2":27},{"t":"line","x1":20,"y1":45,"x2":42.4,"y2":45},{"t":"line","x1":59.6,"y1":45,"x2":82,"y2":45},{"t":"battery","x":51,"y":14,"label":"电源"},{"t":"meter","x":30,"y":14,"kind":"A","label":"电流表（干路）"},{"t":"bulb","x":51,"y":27,"label":"L1"},{"t":"bulb","x":51,"y":45,"label":"L2"},{"t":"junction","x":20,"y":27},{"t":"junction","x":82,"y":27}]}},{"type":"note","title":"结论","text":"干路电流 0.5 A；1 min 通过干路的电荷量 30 C。"},{"type":"h","text":"应用 · 为什么家里的用电器是并联的"},{"type":"note","title":"情境","text":"家庭电路中，电灯、电视机、电冰箱都接在 220 V 的火线与零线之间，可以各自开关、互不影响。"},{"type":"note","title":"模型与思路","text":"从识别电路的角度看：每个用电器各有自己的电流路径，属于并联。并联时各用电器两端电压都等于电源电压，所以额定电压相同的电器才能都正常工作；又因为互不影响，关掉一台电器不会影响其它电器。"},{"type":"list","title":"解答步骤","items":["画出电流路径：从火线经某个用电器再回到零线，每个电器各一条。","因为路径各自独立、只在干路处汇合，所以判断为并联。","并联的用电器两端电压都是 220 V，与各自额定电压相同，能正常工作。","若把它们串联，各电器分得的电压都小于 220 V，都不能正常工作，所以家用电器不能串联使用。"]},{"type":"note","title":"结论","text":"家庭电路中的各用电器是并联的，这样才能各自工作、互不影响。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["两个灯泡总是同时亮、同时灭，它们一定是串联的","同时亮灭只能说明开关在干路上，判定串并联要看电流路径有几条","并联电路如果把开关接在干路上，闭合时两灯也同时亮、断开时同时灭；此时取下其中一只灯泡，另一只仍会发光，这正是并联与串联的区别所在。"],["并联电路中，离电源近的支路电流一定更大","并联各支路的电流由各自的电阻决定，与它离电源远近无关","并联各支路两端的电压相同，由 I = U/R 可知电阻小的支路电流大；位置远近不影响电阻，不能凭感觉判断电流大小。"],["把两只灯泡首尾依次相接就是并联","首尾依次相接是串联；首首相连、尾尾相连才是并联","串联的接线特征是「一个接一个」，电流只有一条路径；并联的接线特征是两端分别接到一起，电流有多条路径。记混接线特征，画图时就会把并联画成串联。"]]},{"type":"table","title":"串联与并联（从电流路径、相互影响到电压关系）","head":["比较项","串联","并联"],"rows":[["电流路径条数","只有一条","两条或更多条"],["元件连接方式","首尾依次相接","首端接在一起、末端也接在一起"],["电流关系","各处电流相等：I = I₁ = I₂","干路电流等于各支路电流之和：I = I₁ + I₂"],["电压关系","总电压等于各部分电压之和：U = U₁ + U₂","各支路两端电压相等：U = U₁ = U₂"],["用电器相互影响","一只断开，其余都不能工作","一条支路断开，其余支路仍能工作"],["开关作用","任意位置的开关都控制整个电路","干路开关控制整个电路，支路开关只控制本支路"]]},{"type":"table","title":"导线交叉与导线相接（画电路图时用图形区分「相连」与「不相连」）","head":["比较项","交叉（不相连）","相接（相连）"],"rows":[["画法","两条导线十字交叉，交叉处不画点","两条以上导线相接处画实心结点"],["电路含义","两条路径彼此独立，电流不会由此处转入另一条","此处电流可以分流或汇合，是干路与支路的连接点"],["常见错误","把交叉画成相接，凭空多出支路","漏画结点，把并联画成了不完整的两条线"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["由现象判断连接方式","以「取下一只灯泡，另一只是否还亮」「各用电器能否独立工作」为条件，判断串联还是并联，并说明开关的位置（干路还是支路）。判断时必须用「路径是否独立」这一口径。"],["电路作图与实物图连线","根据要求画出电路图，或按电路图用笔画线把实物连起来。评分看三点：连接方式对不对、开关位置对不对、有没有把导线画到元件两端以外（短路）。"],["电流路径与短路判断","给出实物图，问哪个元件被短路、闭合开关后哪只灯亮。关键是沿着导线找「不经过用电器就能回到电源」的那一段。"],["家庭电路中的并联识别","以家用电器、教室里的电灯为情境，说明它们并联的原因（额定电压相同、互不影响），并用电压关系解释串联时为什么不能正常工作。"]]},{"type":"quote","text":"【材料】小明用一个电源、两只小灯泡 L1 和 L2、两个开关 S1 和 S2、若干导线连接了一个电路。他做了三次观察：① 只闭合 S1 时，L1 亮而 L2 不亮；再闭合 S2，L1 仍然亮，L2 也亮起来。② 闭合 S1、S2 后，把 L1 从灯座上取下，L2 继续发光。③ 他用手摸电池和导线，发现都只是微微发热。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】根据观察①和②，判断 L1 与 L2 的连接方式，并说明理由。（3 分）","【设问】如果 L1、L2 是串联的，观察②的现象会变成什么样？请写出你判断的依据。（2 分）","【设问】小明想再增加一只灯泡 L3，要求 S1 控制 L1 和 L3、S2 仍只控制 L2。请画出电路图（用规定的元件符号）。（4 分）"]}],"questions":[{"id":"phy-electric-2-q1","type":"choice","stem":"如图所示的电路中，闭合开关后两灯都发光。关于这个电路，下列说法正确的是","answer":"C","explain":"图中电流从电源出来后分成两条路径，分别经过 L1 和 L2，再汇合回到电源，属于并联，干路电流等于各支路电流之和，C 正确。A 错：这是并联不是串联，「各处电流相等」是串联的规律，不能用在并联的支路上。B 错：并联各支路两端电压相等，不是 L1 的电压更大。D 错：同时发光只说明开关在干路上，不能作为判断串联的依据。","options":["两灯串联，通过 L1 的电流等于通过 L2 的电流","两灯并联，L1 两端的电压大于 L2 两端的电压","两灯并联，干路电流等于通过两灯的电流之和","两灯并联，它们同时发光说明它们一定是串联的"],"difficulty":2,"tags":["串并联判断"],"figure":{"id":"fig-elec-parallel-4","title":"待判断的电路","caption":"沿着导线走一圈，看电流有没有分支","view":"wide","alt":"电源接在干路上，电流分成两条支路分别经过两只灯泡后又汇合，是一个并联电路","prims":[{"t":"line","x1":20,"y1":14,"x2":47,"y2":14},{"t":"line","x1":58,"y1":14,"x2":82,"y2":14},{"t":"line","x1":20,"y1":14,"x2":20,"y2":45},{"t":"line","x1":82,"y1":14,"x2":82,"y2":45},{"t":"line","x1":20,"y1":27,"x2":42.4,"y2":27},{"t":"line","x1":59.6,"y1":27,"x2":82,"y2":27},{"t":"line","x1":20,"y1":45,"x2":42.4,"y2":45},{"t":"line","x1":59.6,"y1":45,"x2":82,"y2":45},{"t":"battery","x":51,"y":14,"label":"电源"},{"t":"bulb","x":51,"y":27,"label":"L1"},{"t":"bulb","x":51,"y":45,"label":"L2"},{"t":"junction","x":20,"y":27},{"t":"junction","x":82,"y":27}]}},{"id":"phy-electric-2-q2","type":"choice","stem":"关于串联电路和并联电路，下列说法正确的是","answer":"D","explain":"D 正确：干路是所有支路电流的必经之地，开关在干路就能控制整个电路；支路开关只在自己那条路径上。A 错：并联的两个用电器若把开关接在干路，也会同时工作、同时停止。B 错：串联电路只有一条路径，取下任一个用电器电路就断路，其余都不能工作。C 错：并联各支路电流由各自电阻决定，只是电压相同，电流不一定相等。","options":["两个用电器同时工作、同时停止，它们一定是串联的","串联电路中，取下其中一个用电器，其余用电器仍能正常工作","并联电路中，各支路的电流一定相等","并联电路中，干路开关能控制整个电路，支路开关只能控制它所在的那条支路"],"difficulty":1,"tags":["串并联特点"]},{"id":"phy-electric-2-q3","type":"choice","stem":"某电路中接有两只灯泡 L1、L2 和一个开关 S。闭合 S 时两灯都亮，断开 S 时两灯都灭；把 L1 从灯座上取下后，L2 仍然发光。由此可以判断","answer":"B","explain":"取下 L1 后 L2 仍能发光，说明两条路径互不影响，是并联；断开 S 时两灯都灭，说明 S 在干路上。C 错：如果 S 只接在 L1 的支路上，断开 S 时 L2 应当继续发光，与题目「两灯都灭」矛盾。A 错：串联时取下一只灯另一只灯必然不亮。D 错：两条现象已经足够确定连接方式与开关位置。","options":["L1 与 L2 串联，开关 S 在干路上","L1 与 L2 并联，开关 S 在干路上","L1 与 L2 并联，开关 S 接在 L1 的支路上","条件不足，无法判断"],"difficulty":2,"tags":["串并联判断"]},{"id":"phy-electric-2-q4","type":"choice","stem":"关于家庭中同时使用的电灯、电视机和电冰箱，下列说法正确的是","answer":"A","explain":"家用电器并联接入火线与零线之间，各用电器两端电压都等于 220 V，与各自的额定电压相同，并且可以独立开关、互不影响，A 正确。B 错：并联同样可以同时工作，而且家用电器若串联，各用电器分得的电压都小于 220 V，都无法正常工作。C 错：并联各支路电压相同、电流由各自电阻决定，电流一般不同。D 错：并联干路电流等于各支路电流之和，一定大于任何一条支路的电流，不是取最大值。","options":["它们是并联的，各用电器两端电压都是 220 V，且能各自单独工作","它们一定是串联的，否则不可能同时工作","它们是并联的，所以通过它们的电流一定相等","它们是并联的，所以干路电流等于各用电器电流中的最大值"],"difficulty":2,"tags":["家庭电路","并联"]},{"id":"phy-electric-2-q5","type":"fill","stem":"某电路中灯泡 L1 与 L2 并联，通过 L1 的电流为 0.3 A，通过 L2 的电流为 0.2 A，则干路中的电流是 ______ A。","answer":"0.5|0.5 A|0.50","explain":"并联电路的干路电流等于各支路电流之和：I = I₁ + I₂ = 0.3 A + 0.2 A = 0.5 A。这里容易犯的错是误用串联规律写成「处处相等」，把答案写成 0.3 A；判断规律适用前提是本题型的关键，先确认是并联再相加。","difficulty":1,"tags":["并联电流规律","计算"]},{"id":"phy-electric-2-q6","type":"short","stem":"在如图所示的并联电路中（L1、L2 并联，电源在干路上），干路电流为 0.8 A，通过 L1 的电流为 0.3 A。求：（1）通过 L2 的电流；（2）通电 2 min 通过 L2 的电荷量。","answer":"（1）I₂ = I − I₁ = 0.8 A − 0.3 A = 0.5 A；（2）Q = I₂t = 0.5 A × 120 s = 60 C。","explain":"为什么这么做：并联电路干路电流等于各支路电流之和，所以 I₂ = I − I₁；求电荷量要用「通过哪条支路就用哪条支路的电流」的对应关系，第（2）问必须用 I₂ 而不是干路电流 0.8 A，时间 2 min 要先换成 120 s。常见错误有两处：把干路电流与支路电流混用（同时性、同段性），以及忘记把分钟换成秒。","difficulty":2,"tags":["并联电流规律","计算"],"rubric":["写出并联电流规律 I = I₁ + I₂ 并变形（1 分）","第（1）问结果 0.5 A（1 分）","第（2）问正确选用 L2 的电流 0.5 A（1 分）","时间换算与电荷量结果 60 C，单位正确（1 分）"],"steps":["（1）由并联电路电流规律 I = I₁ + I₂ 得 I₂ = I − I₁。","代入：I₂ = 0.8 A − 0.3 A = 0.5 A。","（2）时间换算：t = 2 min = 120 s。","由 I = Q/t 得 Q = I₂t = 0.5 A × 120 s = 60 C。","答：通过 L2 的电流为 0.5 A；通电 2 min 通过 L2 的电荷量为 60 C。"],"figure":{"id":"fig-elec-parallel-main","title":"并联电路：干路电流等于各支路电流之和","caption":"电源与开关在干路上，电流表测的是干路电流；L1、L2 各占一条支路，两条支路两端的电压相同","view":"wide","alt":"电源、开关与电流表依次接在干路上，干路分成两条并联的支路，一条支路上是灯泡 L1、另一条是灯泡 L2，两条支路重新汇合回到电源","prims":[{"t":"line","x1":18,"y1":14,"x2":22,"y2":14},{"t":"line","x1":33,"y1":14,"x2":44,"y2":14},{"t":"line","x1":56,"y1":14,"x2":61.4,"y2":14},{"t":"line","x1":78.6,"y1":14,"x2":82,"y2":14},{"t":"line","x1":82,"y1":14,"x2":82,"y2":32},{"t":"line","x1":82,"y1":32,"x2":82,"y2":50},{"t":"line","x1":18,"y1":14,"x2":18,"y2":32},{"t":"line","x1":18,"y1":32,"x2":18,"y2":50},{"t":"line","x1":18,"y1":32,"x2":41.4,"y2":32},{"t":"line","x1":58.6,"y1":32,"x2":82,"y2":32},{"t":"line","x1":18,"y1":50,"x2":41.4,"y2":50},{"t":"line","x1":58.6,"y1":50,"x2":82,"y2":50},{"t":"battery","x":26,"y":14,"label":"电源"},{"t":"switch","x":50,"y":14,"closed":true,"label":"S"},{"t":"meter","x":70,"y":14,"kind":"A","label":"A（干路）"},{"t":"bulb","x":50,"y":32,"label":"L1"},{"t":"bulb","x":50,"y":50,"label":"L2"},{"t":"junction","x":18,"y":32},{"t":"junction","x":18,"y":50},{"t":"junction","x":82,"y":32},{"t":"junction","x":82,"y":50},{"t":"text","x":50,"y":60,"text":"干路电流 0.8 A，L1 所在支路 0.3 A","size":3.6,"tone":"accent"}]}},{"id":"phy-electric-2-q7","type":"short","stem":"请设计实验，用一只电流表判断两只小灯泡是串联还是并联，并测出并联时各支路与干路的电流。写出器材、主要步骤、需要记录的数据与判断方法。","answer":"器材：电源、两只小灯泡 L1 和 L2、开关、电流表、导线若干。步骤：(1) 按串联方式连接电路，把电流表串联在电路中，闭合开关读出电流，断开开关；(2) 改接成并联，把电流表依次串联在 L1 支路、L2 支路和干路上（每次读数前先断开开关再改接），分别记录 I₁、I₂、I；(3) 比较数据：若三处电流都相等，是串联；若 I = I₁ + I₂，是并联。判断连接方式还可以配合观察：取下 L1，若 L2 仍发光则为并联。","explain":"实验的关键是电流表必须串联接入被测的那一段电路，并且每次改接都要先断开开关。并联时测干路电流要把电流表接在分支点之前（或汇合点之后），测支路电流要接在该支路内。数据上除了记录三处电流，还应算出 I₁ + I₂ 与 I 比较，用数据说话，而不是凭「灯同时亮」来判断。若电流表指针反偏，说明「+」「−」接线柱接反了；若指针偏转太小，要换用较小量程重新测量。","difficulty":3,"tags":["实验探究","电流表使用"],"rubric":["器材完整：电源、两只灯泡、开关、电流表、导线（1 分）","电流表串联接入被测支路或干路，改接前断开开关（1 分）","分别测 L1 支路、L2 支路与干路三处电流并记录数据（1 分）","结论口径正确：串联三处相等、并联 I = I₁ + I₂（1 分）"]},{"id":"phy-electric-2-q8","type":"short","stem":"请按要求画出电路图：两只小灯泡 L1、L2 并联，开关 S 接在干路上，能同时控制两只灯泡。","answer":"见参考答案图：L1 与 L2 各占一条支路，两端分别接到一起，开关与电源串联在干路上。","explain":"作图要点：先把两个分支点定下来，两条支路分别画在这两个分支点之间，支路里各放一只灯泡；干路上串联电源和开关。容易出错的画法有三种：两只灯泡首尾相接（画成串联）；开关画在其中一条支路里（只能控制一只灯）；把灯泡两端直接用导线连起来（把灯泡短路）。","difficulty":2,"tags":["电路作图"],"rubric":["两只灯泡各占一条支路，两端分别接到同一对分支点（1 分）","电源与开关串联在干路上，开关能同时控制两只灯泡（1 分）","分支点处画出结点，导线交叉处不画点、元件符号与导线画法规范（1 分）"],"answerFigure":{"id":"fig-elec-draw-2-ans","title":"参考答案：两灯并联、开关在干路","caption":"分支点画结点，干路上的开关控制两灯","view":"wide","alt":"电源与开关串联在干路上，两只灯泡分别接在两条并联支路上，两端接到同一对分支点","prims":[{"t":"line","x1":20,"y1":14,"x2":26,"y2":14},{"t":"line","x1":37,"y1":14,"x2":62,"y2":14},{"t":"line","x1":74,"y1":14,"x2":82,"y2":14},{"t":"line","x1":20,"y1":14,"x2":20,"y2":45},{"t":"line","x1":82,"y1":14,"x2":82,"y2":45},{"t":"line","x1":20,"y1":27,"x2":42.4,"y2":27},{"t":"line","x1":59.6,"y1":27,"x2":82,"y2":27},{"t":"line","x1":20,"y1":45,"x2":42.4,"y2":45},{"t":"line","x1":59.6,"y1":45,"x2":82,"y2":45},{"t":"battery","x":30,"y":14,"label":"电源"},{"t":"switch","x":68,"y":14,"closed":true,"label":"S"},{"t":"bulb","x":51,"y":27,"label":"L1"},{"t":"bulb","x":51,"y":45,"label":"L2"},{"t":"junction","x":20,"y":27},{"t":"junction","x":82,"y":27}]}},{"id":"phy-electric-2-m1-q1","type":"short","stem":"根据观察①和②，判断 L1 与 L2 的连接方式，并说明理由。（3 分）","answer":"L1 与 L2 是并联的。理由：取下 L1 后 L2 继续发光，说明两灯的电流路径各自独立、互不影响；而且 S1 只控制 L1、S2 只控制 L2，说明两个开关分别接在两条支路上。","explain":"","tags":["串并联判断"],"rubric":["判断为并联（1 分）","用「取下一灯另一灯仍亮」说明路径各自独立（1 分）","指出两个开关分别接在各自支路上（1 分）"]},{"id":"phy-electric-2-m1-q2","type":"short","stem":"如果 L1、L2 是串联的，观察②的现象会变成什么样？请写出你判断的依据。（2 分）","answer":"如果两灯串联，电流只有一条路径，取下 L1 后电路就成了断路，L2 也不会发光。所以「取下 L1 而 L2 仍发光」本身就否定了串联。","explain":"","tags":["串联特点"],"rubric":["说明串联只有一条电流路径（1 分）","指出取下 L1 会造成断路、L2 不亮（1 分）"]},{"id":"phy-electric-2-m1-q3","type":"short","stem":"小明想再增加一只灯泡 L3，要求 S1 控制 L1 和 L3、S2 仍只控制 L2。请画出电路图（用规定的元件符号）。（4 分）","answer":"L1 与 L3 串联在同一支路上，S1 接在这条支路上；L2 单独一条支路，S2 接在 L2 的支路上；两条支路并联后接到电源两极，电源在干路上。","explain":"","tags":["电路作图"],"rubric":["L1 与 L3 串联在同一条支路上（1 分）","S1 接在该支路上，S2 接在 L2 所在支路上（1 分）","两条支路并联，电源画在干路（1 分）","电路图规范：导线画出直角、元件符号正确、不出现短路（1 分）"],"answerFigure":{"id":"fig-elec-draw-l3","title":"参考答案：S1 控制 L1 与 L3，S2 只控制 L2","caption":"L1 与 L3 并联后与 S1 串在同一条支路上（S1 一通，两只灯同时工作）；L2 单占一条支路，由 S2 单独控制","view":"square","alt":"电路中有两条并联支路：第一条支路上是开关 S1，其后并联着灯泡 L1 与灯泡 L3；第二条支路上是开关 S2 与灯泡 L2；两条支路并联后接在电源两端","prims":[{"t":"line","x1":16,"y1":16,"x2":44.5,"y2":16},{"t":"line","x1":55.5,"y1":16,"x2":84,"y2":16},{"t":"line","x1":16,"y1":16,"x2":16,"y2":34},{"t":"line","x1":16,"y1":34,"x2":16,"y2":72},{"t":"line","x1":84,"y1":16,"x2":84,"y2":34},{"t":"line","x1":84,"y1":34,"x2":84,"y2":72},{"t":"line","x1":16,"y1":34,"x2":22,"y2":34},{"t":"line","x1":34,"y1":34,"x2":42,"y2":34},{"t":"line","x1":42,"y1":34,"x2":53.4,"y2":34},{"t":"line","x1":70.6,"y1":34,"x2":78,"y2":34},{"t":"line","x1":78,"y1":34,"x2":84,"y2":34},{"t":"line","x1":42,"y1":34,"x2":42,"y2":54},{"t":"line","x1":42,"y1":54,"x2":53.4,"y2":54},{"t":"line","x1":70.6,"y1":54,"x2":78,"y2":54},{"t":"line","x1":78,"y1":54,"x2":78,"y2":34},{"t":"line","x1":16,"y1":72,"x2":22,"y2":72},{"t":"line","x1":34,"y1":72,"x2":53.4,"y2":72},{"t":"line","x1":70.6,"y1":72,"x2":84,"y2":72},{"t":"battery","x":50,"y":16,"label":"电源"},{"t":"switch","x":28,"y":34,"closed":true,"label":"S1"},{"t":"bulb","x":62,"y":34,"label":"L1"},{"t":"bulb","x":62,"y":54,"label":"L3"},{"t":"switch","x":28,"y":72,"closed":true,"label":"S2"},{"t":"bulb","x":62,"y":72,"label":"L2"},{"t":"junction","x":42,"y":34},{"t":"junction","x":78,"y":34},{"t":"junction","x":16,"y":72},{"t":"junction","x":84,"y":72},{"t":"text","x":50,"y":90,"text":"S1 与「L1、L3 并联」串联，S2 与 L2 串联","size":3.6,"tone":"accent"}]}}]},{"id":"phy-electric-3","title":"电流的测量：电流表的使用、读数与电流规律","subtitle":"人教版九年级 · 第 15 章 电流和电路 · 9a","grade":"9a","tags":["人教版九年级 · 第 15 章 电流和电路"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 15 章 电流和电路 · 9a"},{"type":"note","title":"问题切入","text":"电流看不见、摸不着，凭什么知道它有多大？同一只电流表接在电路的不同位置，读数为什么有的相同、有的不同？接错位置时，电流表为什么会一下子打到满偏？"},{"type":"note","title":"一句话抓住关键","text":"测量就是把被测的量「接进」仪器：电流表必须串联在被测电路中，让被测电流全部通过它，电流从「+」接线柱流入、从「−」接线柱流出。规律上：串联电路电流处处相等，并联电路干路电流等于各支路电流之和。"},{"type":"h","text":"先看现象：把电流表「串」进去"},{"type":"p","text":"电流表要测哪一段电路的电流，就必须把自己变成那段电路的一部分，也就是与被测元件串联，让电流从「+」接线柱流入、从「−」接线柱流出。如果接反，指针会向左反偏、可能损坏表；如果把它并联在某个用电器两端，因为电流表本身的电阻极小，相当于给这个用电器并联了一根导线，用电器被短路、电流几乎全部从电流表通过，指针会打到满偏。"},{"type":"figure","figure":{"id":"fig-elec-ammeter-1","title":"电流表串联在电路中","caption":"电流表与被测元件串联，「+」接线柱靠近电源正极一侧","view":"wide","alt":"电源、开关、电流表与灯泡依次串联成闭合回路，电流表串联在电路中，电流从电流表的正接线柱流入","prims":[{"t":"line","x1":18,"y1":16,"x2":30,"y2":16},{"t":"line","x1":41,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":25.4,"y2":48},{"t":"line","x1":42.6,"y1":48,"x2":59.4,"y2":48},{"t":"line","x1":76.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":34,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"meter","x":34,"y":48,"kind":"A","label":"「＋」进「−」出"},{"t":"bulb","x":68,"y":48,"label":"L"}]}},{"type":"note","title":"","text":"三条禁忌：不得把电流表直接接在电源两极上；不得把电流表并联在用电器两端；不得让电流从「−」接线柱流入。"},{"type":"h","text":"抓住哪个量：量程、分度值与读数"},{"type":"p","text":"电流表有两个量程：0～0.6 A 和 0～3 A。读数的三步是：一看选的哪个量程，二算这个量程下每一小格代表多少（分度值），三看指针一共偏过多少小格。0～0.6 A 量程把满偏分成 30 小格，分度值 0.02 A；0～3 A 量程把满偏分成 30 小格，分度值 0.1 A。同一个指针位置，用大量程读出的数值是用小量程读数的 5 倍。"},{"type":"figure","figure":{"id":"fig-elec-ammeter-2","title":"电流表表盘：0～0.6 A 量程的读数","caption":"0～0.6 A 量程，一大格 0.2 A、一小格 0.02 A，指针指在 0.4 A 处","view":"square","alt":"电流表表盘，量程 0 到 0.6 安，刻度数字为 0、0.2、0.4、0.6，指针从中心指向 0.4 安刻度线","prims":[{"t":"circle","cx":50,"cy":56,"r":32,"dashed":true,"tone":"muted"},{"t":"text","x":50,"y":16,"text":"电流表","size":4.6,"tone":"main"},{"t":"curve","points":[[27.48,43],[28.07,42.03],[28.7,41.09],[29.37,40.17],[30.08,39.29],[30.83,38.43],[31.62,37.62],[32.43,36.83],[33.29,36.08],[34.17,35.37],[35.09,34.7],[36.03,34.07],[37,33.48],[37.99,32.94],[39.01,32.44],[40.05,31.98],[41.11,31.57],[42.18,31.2],[43.27,30.89],[44.37,30.62],[45.49,30.39],[46.61,30.22],[47.73,30.1],[48.87,30.02],[50,30],[51.13,30.02],[52.27,30.1],[53.39,30.22],[54.51,30.39],[55.63,30.62],[56.73,30.89],[57.82,31.2],[58.89,31.57],[59.95,31.98],[60.99,32.44],[62.01,32.94],[63,33.48],[63.97,34.07],[64.91,34.7],[65.83,35.37],[66.71,36.08],[67.57,36.83],[68.38,37.62],[69.17,38.43],[69.92,39.29],[70.63,40.17],[71.3,41.09],[71.93,42.03],[72.52,43]],"tone":"main","width":0.5},{"t":"line","x1":27.48,"y1":43,"x2":30.77,"y2":44.9,"tone":"main","width":0.5},{"t":"text","x":33.89,"y":46.7,"text":"0","size":3.4,"tone":"muted"},{"t":"line","x1":28.45,"y1":41.46,"x2":30.1,"y2":42.58,"tone":"main","width":0.28},{"t":"line","x1":29.51,"y1":39.99,"x2":31.09,"y2":41.22,"tone":"main","width":0.28},{"t":"line","x1":30.68,"y1":38.6,"x2":32.16,"y2":39.94,"tone":"main","width":0.28},{"t":"line","x1":31.94,"y1":37.3,"x2":33.33,"y2":38.74,"tone":"main","width":0.28},{"t":"line","x1":33.29,"y1":36.08,"x2":34.57,"y2":37.61,"tone":"main","width":0.28},{"t":"line","x1":34.72,"y1":34.97,"x2":35.89,"y2":36.58,"tone":"main","width":0.28},{"t":"line","x1":36.22,"y1":33.95,"x2":37.28,"y2":35.65,"tone":"main","width":0.28},{"t":"line","x1":37.79,"y1":33.04,"x2":38.73,"y2":34.81,"tone":"main","width":0.28},{"t":"line","x1":39.42,"y1":32.25,"x2":40.24,"y2":34.07,"tone":"main","width":0.28},{"t":"line","x1":41.11,"y1":31.57,"x2":42.41,"y2":35.14,"tone":"main","width":0.5},{"t":"text","x":43.64,"y":38.52,"text":"0.2","size":3.4,"tone":"muted"},{"t":"line","x1":42.83,"y1":31.01,"x2":43.38,"y2":32.93,"tone":"main","width":0.28},{"t":"line","x1":44.59,"y1":30.57,"x2":45.01,"y2":32.52,"tone":"main","width":0.28},{"t":"line","x1":46.38,"y1":30.25,"x2":46.66,"y2":32.23,"tone":"main","width":0.28},{"t":"line","x1":48.19,"y1":30.06,"x2":48.33,"y2":32.06,"tone":"main","width":0.28},{"t":"line","x1":50,"y1":30,"x2":50,"y2":32,"tone":"main","width":0.28},{"t":"line","x1":51.81,"y1":30.06,"x2":51.67,"y2":32.06,"tone":"main","width":0.28},{"t":"line","x1":53.62,"y1":30.25,"x2":53.34,"y2":32.23,"tone":"main","width":0.28},{"t":"line","x1":55.41,"y1":30.57,"x2":54.99,"y2":32.52,"tone":"main","width":0.28},{"t":"line","x1":57.17,"y1":31.01,"x2":56.62,"y2":32.93,"tone":"main","width":0.28},{"t":"line","x1":58.89,"y1":31.57,"x2":57.59,"y2":35.14,"tone":"main","width":0.5},{"t":"text","x":56.36,"y":38.52,"text":"0.4","size":3.4,"tone":"muted"},{"t":"line","x1":60.58,"y1":32.25,"x2":59.76,"y2":34.07,"tone":"main","width":0.28},{"t":"line","x1":62.21,"y1":33.04,"x2":61.27,"y2":34.81,"tone":"main","width":0.28},{"t":"line","x1":63.78,"y1":33.95,"x2":62.72,"y2":35.65,"tone":"main","width":0.28},{"t":"line","x1":65.28,"y1":34.97,"x2":64.11,"y2":36.58,"tone":"main","width":0.28},{"t":"line","x1":66.71,"y1":36.08,"x2":65.43,"y2":37.61,"tone":"main","width":0.28},{"t":"line","x1":68.06,"y1":37.3,"x2":66.67,"y2":38.74,"tone":"main","width":0.28},{"t":"line","x1":69.32,"y1":38.6,"x2":67.84,"y2":39.94,"tone":"main","width":0.28},{"t":"line","x1":70.49,"y1":39.99,"x2":68.91,"y2":41.22,"tone":"main","width":0.28},{"t":"line","x1":71.55,"y1":41.46,"x2":69.9,"y2":42.58,"tone":"main","width":0.28},{"t":"line","x1":72.52,"y1":43,"x2":69.23,"y2":44.9,"tone":"main","width":0.5},{"t":"text","x":66.11,"y":46.7,"text":"0.6","size":3.4,"tone":"muted"},{"t":"line","x1":48.76,"y1":59.42,"x2":57.8,"y2":34.58,"tone":"danger","width":0.7},{"t":"circle","cx":50,"cy":56,"r":1.5,"fill":true,"tone":"main"},{"t":"text","x":50,"y":92,"text":"量程 0～0.6 A，分度值 0.02 A","size":3.8,"tone":"muted"},{"t":"text","x":50,"y":97,"text":"指针指在 0.4 A 处","size":3.8,"tone":"muted"}]}},{"type":"note","title":"","text":"在不超过量程的前提下要尽量选小量程：分度值越小，读数越准确。估计不出电流大小时，先用大量程试触。"},{"type":"h","text":"建立关系：串联电路电流处处相等"},{"type":"p","text":"在串联电路中，电流只有一条路径。把电流表分别接在灯泡 L1 前、L1 与 L2 之间、L2 之后，三次读数完全相同——电流既不会「用掉」也不会「消失」，所以串联电路中电流处处相等：I = I₁ = I₂。这也可以用「单位时间内通过同一横截面的电荷量相同」来理解。"},{"type":"figure","figure":{"id":"fig-elec-ammeter-3","title":"串联电路：三个位置的电流相同","caption":"电流表接在串联电路的不同位置，读数都相同","view":"wide","alt":"电源、开关与两只灯泡串联，电流表串联在两灯之间，箭头表示电流在整条路径上处处相等","prims":[{"t":"line","x1":18,"y1":16,"x2":30,"y2":16},{"t":"line","x1":41,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":21.4,"y2":48},{"t":"line","x1":38.6,"y1":48,"x2":43.4,"y2":48},{"t":"line","x1":60.6,"y1":48,"x2":63.4,"y2":48},{"t":"line","x1":80.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":34,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"bulb","x":30,"y":48,"label":"L1"},{"t":"bulb","x":72,"y":48,"label":"L2"},{"t":"meter","x":52,"y":48,"kind":"A","label":"电流表"},{"t":"text","x":50,"y":58,"text":"I = I₁ = I₂","size":4.2,"tone":"accent"}]}},{"type":"note","title":"","text":"「串联各处电流相等」与元件的种类、大小、位置无关；反过来，若两处电流不等，就一定不是串联。"},{"type":"h","text":"换个情境：并联电路里的电流「合」起来"},{"type":"p","text":"并联电路中，从电源出来的电流在分支点分成两条（或多条），分别经过各支路后又汇合回到电源。所以在分支点之前测量的干路电流，一定等于各支路电流之和：I = I₁ + I₂。测量时必须把电流表串联在要测的那一段：测干路就接在分支点之前（或汇合点之后），测支路就接在该支路内，否则读数就没有意义。"},{"type":"figure","figure":{"id":"fig-elec-ammeter-4","title":"并联电路：干路电流等于各支路电流之和","caption":"干路电流表 A 与两条支路上的 A1、A2 分别串联，I = I₁ + I₂","view":"wide","alt":"两只灯泡并联，电流表 A 串联在干路上，电流表 A1 与 A2 分别串联在两条支路上，用于比较干路与支路电流","prims":[{"t":"line","x1":20,"y1":14,"x2":21.4,"y2":14},{"t":"line","x1":38.6,"y1":14,"x2":47,"y2":14},{"t":"line","x1":58,"y1":14,"x2":82,"y2":14},{"t":"line","x1":20,"y1":14,"x2":20,"y2":45},{"t":"line","x1":82,"y1":14,"x2":82,"y2":45},{"t":"line","x1":20,"y1":27,"x2":21.4,"y2":27},{"t":"line","x1":38.6,"y1":27,"x2":53.4,"y2":27},{"t":"line","x1":70.6,"y1":27,"x2":82,"y2":27},{"t":"line","x1":20,"y1":45,"x2":21.4,"y2":45},{"t":"line","x1":38.6,"y1":45,"x2":53.4,"y2":45},{"t":"line","x1":70.6,"y1":45,"x2":82,"y2":45},{"t":"battery","x":51,"y":14,"label":"电源"},{"t":"meter","x":30,"y":14,"kind":"A","label":"A（干路）"},{"t":"meter","x":30,"y":27,"kind":"A","label":"A1"},{"t":"meter","x":30,"y":45,"kind":"A","label":"A2"},{"t":"bulb","x":62,"y":27,"label":"L1"},{"t":"bulb","x":62,"y":45,"label":"L2"},{"t":"junction","x":20,"y":27},{"t":"junction","x":82,"y":27}]}},{"type":"note","title":"","text":"两只电流表不能接成「一只测支路、另一只也接在同一条支路上」还当成干路；判断表格里的数据是否合理，就看 I 与 I₁ + I₂ 是否相等。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["电流表的读数","读数 = 指针偏过的小格数 × 分度值；0～0.6 A 量程分度值 0.02 A，0～3 A 量程分度值 0.1 A","只在读电流表（电压表同理）表盘时使用。先看清所接的量程与接线柱，再数清指针偏过多少小格。同一表盘用 0～3 A 量程读数是用 0～0.6 A 量程读数的 5 倍，两个量程不能混读；读数还须估读到分度值的下一位（如 0.24 A、0.26 A）。"],["串联电路的电流规律","I = I₁ = I₂","I、I₁、I₂：电流，单位安培（A） · 只适用于串联电路，与元件的大小、种类、位置无关。可用于由一处电流推知另一处电流，也是判断连接方式的依据：两处电流不相等就不可能是串联。"],["并联电路的电流规律","I = I₁ + I₂","I：干路电流；I₁、I₂：各支路电流，单位都为安培（A） · 只适用于并联电路。式中 I 是干路电流，I₁、I₂ 是同一时刻各支路的电流（同时性），不能把某个支路的电流当作干路电流代入。变形 I₂ = I − I₁ 常用于由干路和一条支路求另一条支路，算完可用 I₁ + I₂ 是否等于 I 来检验。"]]},{"type":"h","text":"应用 · 读出电流表的读数并算电荷量"},{"type":"note","title":"情境","text":"某同学用 0～0.6 A 量程的电流表测得通过小灯泡的电流，指针从零刻度偏过 12 个小格。求读数，以及通电 5 min 通过灯丝的电荷量。"},{"type":"note","title":"模型与思路","text":"0～0.6 A 量程的分度值是 0.02 A，读数 = 小格数 × 分度值；再用电荷量的定义式 Q = It 求电荷量，时间换成秒。"},{"type":"list","title":"解答步骤","items":["确认量程与分度值：0～0.6 A，分度值 0.02 A。","读数：I = 12 × 0.02 A = 0.24 A。","时间换算：t = 5 min = 300 s。","电荷量：Q = It = 0.24 A × 300 s = 72 C。","答：电流为 0.24 A，5 min 内通过灯丝的电荷量为 72 C。"]},{"type":"figure","figure":{"id":"fig-elec-ammeter-5","title":"0～0.6 A 量程下指针偏过 12 小格","caption":"一小格 0.02 A，指针停在 0.24 A 处","view":"square","alt":"电流表表盘，量程 0 到 0.6 安，指针指在 0.2 安之后第二小格，即 0.24 安处","prims":[{"t":"circle","cx":50,"cy":56,"r":32,"dashed":true,"tone":"muted"},{"t":"text","x":50,"y":16,"text":"电流表","size":4.6,"tone":"main"},{"t":"curve","points":[[27.48,43],[28.07,42.03],[28.7,41.09],[29.37,40.17],[30.08,39.29],[30.83,38.43],[31.62,37.62],[32.43,36.83],[33.29,36.08],[34.17,35.37],[35.09,34.7],[36.03,34.07],[37,33.48],[37.99,32.94],[39.01,32.44],[40.05,31.98],[41.11,31.57],[42.18,31.2],[43.27,30.89],[44.37,30.62],[45.49,30.39],[46.61,30.22],[47.73,30.1],[48.87,30.02],[50,30],[51.13,30.02],[52.27,30.1],[53.39,30.22],[54.51,30.39],[55.63,30.62],[56.73,30.89],[57.82,31.2],[58.89,31.57],[59.95,31.98],[60.99,32.44],[62.01,32.94],[63,33.48],[63.97,34.07],[64.91,34.7],[65.83,35.37],[66.71,36.08],[67.57,36.83],[68.38,37.62],[69.17,38.43],[69.92,39.29],[70.63,40.17],[71.3,41.09],[71.93,42.03],[72.52,43]],"tone":"main","width":0.5},{"t":"line","x1":27.48,"y1":43,"x2":30.77,"y2":44.9,"tone":"main","width":0.5},{"t":"text","x":33.89,"y":46.7,"text":"0","size":3.4,"tone":"muted"},{"t":"line","x1":28.45,"y1":41.46,"x2":30.1,"y2":42.58,"tone":"main","width":0.28},{"t":"line","x1":29.51,"y1":39.99,"x2":31.09,"y2":41.22,"tone":"main","width":0.28},{"t":"line","x1":30.68,"y1":38.6,"x2":32.16,"y2":39.94,"tone":"main","width":0.28},{"t":"line","x1":31.94,"y1":37.3,"x2":33.33,"y2":38.74,"tone":"main","width":0.28},{"t":"line","x1":33.29,"y1":36.08,"x2":34.57,"y2":37.61,"tone":"main","width":0.28},{"t":"line","x1":34.72,"y1":34.97,"x2":35.89,"y2":36.58,"tone":"main","width":0.28},{"t":"line","x1":36.22,"y1":33.95,"x2":37.28,"y2":35.65,"tone":"main","width":0.28},{"t":"line","x1":37.79,"y1":33.04,"x2":38.73,"y2":34.81,"tone":"main","width":0.28},{"t":"line","x1":39.42,"y1":32.25,"x2":40.24,"y2":34.07,"tone":"main","width":0.28},{"t":"line","x1":41.11,"y1":31.57,"x2":42.41,"y2":35.14,"tone":"main","width":0.5},{"t":"text","x":43.64,"y":38.52,"text":"0.2","size":3.4,"tone":"muted"},{"t":"line","x1":42.83,"y1":31.01,"x2":43.38,"y2":32.93,"tone":"main","width":0.28},{"t":"line","x1":44.59,"y1":30.57,"x2":45.01,"y2":32.52,"tone":"main","width":0.28},{"t":"line","x1":46.38,"y1":30.25,"x2":46.66,"y2":32.23,"tone":"main","width":0.28},{"t":"line","x1":48.19,"y1":30.06,"x2":48.33,"y2":32.06,"tone":"main","width":0.28},{"t":"line","x1":50,"y1":30,"x2":50,"y2":32,"tone":"main","width":0.28},{"t":"line","x1":51.81,"y1":30.06,"x2":51.67,"y2":32.06,"tone":"main","width":0.28},{"t":"line","x1":53.62,"y1":30.25,"x2":53.34,"y2":32.23,"tone":"main","width":0.28},{"t":"line","x1":55.41,"y1":30.57,"x2":54.99,"y2":32.52,"tone":"main","width":0.28},{"t":"line","x1":57.17,"y1":31.01,"x2":56.62,"y2":32.93,"tone":"main","width":0.28},{"t":"line","x1":58.89,"y1":31.57,"x2":57.59,"y2":35.14,"tone":"main","width":0.5},{"t":"text","x":56.36,"y":38.52,"text":"0.4","size":3.4,"tone":"muted"},{"t":"line","x1":60.58,"y1":32.25,"x2":59.76,"y2":34.07,"tone":"main","width":0.28},{"t":"line","x1":62.21,"y1":33.04,"x2":61.27,"y2":34.81,"tone":"main","width":0.28},{"t":"line","x1":63.78,"y1":33.95,"x2":62.72,"y2":35.65,"tone":"main","width":0.28},{"t":"line","x1":65.28,"y1":34.97,"x2":64.11,"y2":36.58,"tone":"main","width":0.28},{"t":"line","x1":66.71,"y1":36.08,"x2":65.43,"y2":37.61,"tone":"main","width":0.28},{"t":"line","x1":68.06,"y1":37.3,"x2":66.67,"y2":38.74,"tone":"main","width":0.28},{"t":"line","x1":69.32,"y1":38.6,"x2":67.84,"y2":39.94,"tone":"main","width":0.28},{"t":"line","x1":70.49,"y1":39.99,"x2":68.91,"y2":41.22,"tone":"main","width":0.28},{"t":"line","x1":71.55,"y1":41.46,"x2":69.9,"y2":42.58,"tone":"main","width":0.28},{"t":"line","x1":72.52,"y1":43,"x2":69.23,"y2":44.9,"tone":"main","width":0.5},{"t":"text","x":66.11,"y":46.7,"text":"0.6","size":3.4,"tone":"muted"},{"t":"line","x1":50.76,"y1":59.56,"x2":45.26,"y2":33.7,"tone":"danger","width":0.7},{"t":"circle","cx":50,"cy":56,"r":1.5,"fill":true,"tone":"main"},{"t":"text","x":50,"y":92,"text":"读数 = 小格数 × 分度值 = 12 × 0.02 A","size":3.8,"tone":"muted"},{"t":"text","x":50,"y":97,"text":"即 0.24 A","size":3.8,"tone":"muted"}]}},{"type":"note","title":"结论","text":"读数 0.24 A；5 min 内通过 72 C。"},{"type":"h","text":"应用 · 并联电路的电流计算"},{"type":"note","title":"情境","text":"某电路中两只灯泡并联，干路电流表读数为 0.9 A，测 L1 支路的电流表读数为 0.4 A。求通过 L2 的电流。"},{"type":"note","title":"模型与思路","text":"并联电路干路电流等于各支路电流之和：I = I₁ + I₂，变形得 I₂ = I − I₁。这里 I 必须是干路电流 0.9 A，I₁ 是 L1 支路电流 0.4 A，两者是对同一时刻同一电路的测量。"},{"type":"list","title":"解答步骤","items":["明确各电流表的测量对象：0.9 A 是干路电流，0.4 A 是 L1 支路电流。","写出关系式 I = I₁ + I₂ 并变形。","代入：I₂ = 0.9 A − 0.4 A = 0.5 A。","检验：I₁ + I₂ = 0.4 A + 0.5 A = 0.9 A，与干路读数一致。","答：通过 L2 的电流为 0.5 A。"]},{"type":"figure","figure":{"id":"fig-elec-ammeter-6","title":"干路与支路的测量位置","caption":"A 在干路、A1 在 L1 支路，读数相减即得 L2 的电流","view":"wide","alt":"两只灯泡并联，干路上有电流表 A，L1 支路内有电流表 A1，用于分别测量干路和支路电流","prims":[{"t":"line","x1":20,"y1":14,"x2":21.4,"y2":14},{"t":"line","x1":38.6,"y1":14,"x2":47,"y2":14},{"t":"line","x1":58,"y1":14,"x2":82,"y2":14},{"t":"line","x1":20,"y1":14,"x2":20,"y2":45},{"t":"line","x1":82,"y1":14,"x2":82,"y2":45},{"t":"line","x1":20,"y1":27,"x2":21.4,"y2":27},{"t":"line","x1":38.6,"y1":27,"x2":53.4,"y2":27},{"t":"line","x1":70.6,"y1":27,"x2":82,"y2":27},{"t":"line","x1":20,"y1":45,"x2":42.4,"y2":45},{"t":"line","x1":59.6,"y1":45,"x2":82,"y2":45},{"t":"battery","x":51,"y":14,"label":"电源"},{"t":"meter","x":30,"y":14,"kind":"A","label":"A（干路）"},{"t":"meter","x":30,"y":27,"kind":"A","label":"A1（L1 支路）"},{"t":"bulb","x":62,"y":27,"label":"L1"},{"t":"bulb","x":51,"y":45,"label":"L2"},{"t":"junction","x":20,"y":27},{"t":"junction","x":82,"y":27}]}},{"type":"note","title":"结论","text":"I₂ = 0.5 A。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["电流表要并联在被测元件两端，电压表要串联在电路中","电流表串联在被测电路中，电压表并联在被测元件两端","电流表内阻极小，并联在用电器两端相当于把那一段短路，用电器不工作、电流表可能被烧坏；电压表内阻极大，串联进电路会使电流几乎为零，用电器都不能工作。"],["串联电路中，电流从电源正极流到用电器后会变小","串联电路中电流处处相等，电流不会被「用掉」","电流是电荷的定向移动，单位时间内通过任一横截面的电荷量相同；用电器消耗的是电能，不是电流，所以灯泡前后电流一样大。"],["电流表指针反偏是电流表坏了","指针反偏通常是因为「+」「−」接线柱接反了，应先断开开关改接","电流必须从「+」接线柱流入、从「−」接线柱流出，接反时指针会向左偏转；发现反偏要立即断开开关，把两个接线柱的导线对调，而不是直接换表。"],["使用电流表时量程选得越大越好，这样最安全","在不超过量程的前提下应选尽可能小的量程，读数才更准确","大量程的分度值大，指针偏转角度小、读数相对误差大；只有估计不出电流大小时，才先用大量程试触，再换用合适的量程。"]]},{"type":"table","title":"串联与并联电路中的电流（同一个电源、同样两只灯泡，两种接法下的电流关系）","head":["比较项","串联","并联"],"rows":[["电流路径","一条，无分支","两条或多条，在结点处分合"],["电流关系","各处相等：I = I₁ = I₂","干路等于各支路之和：I = I₁ + I₂"],["测量位置","接在电路中任何位置读数都相同","接在干路与接在支路读数不同"],["比较大小","总电流等于每条支路各自的电流","干路电流最大，大于任一条支路的电流"]]},{"type":"table","title":"电流表与电压表的接法（接法接反的后果与故障现象）","head":["比较项","电流表","电压表"],"rows":[["连接方式","串联在被测电路中","并联在被测元件两端"],["内阻特点","电阻极小，相当于一段导线","电阻极大，相当于断开的开关"],["接成另一种的后果","并联在用电器两端：用电器被短路，电流表可能烧坏","串联在电路中：电路中电流几乎为零，用电器不工作"],["指针反偏的处理","断开开关，把「+」「−」接线柱的两根导线对调","断开开关，把「+」「−」接线柱的两根导线对调"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["电流表的读数","给出量程与指针位置（表盘图或文字描述），要求读数并写出分度值。易错点是把 0～0.6 A 与 0～3 A 两个量程的读数混用，或忘记写出单位与估读位。"],["电路故障判断","以「两灯都不亮」「电流表并联在某元件两端后另一灯亮起来」等现象判断断路位置。关键口径：电流表内阻很小，并联在断路的用电器两端相当于用导线把断路处接通。"],["探究并联电路电流规律","非选择题的高频实验：用电流表分别测干路与各支路电流，记录数据并归纳 I = I₁ + I₂。评分点包括电流表串联接入、换用不同规格灯泡多次实验、数据处理与结论表述。"],["电流表的连接与作图","给出「测通过 L2 的电流」这类要求，判断电路图或实物图的连法是否正确；也常与电流表并联在用电器两端的错误接法一起考，要求指出错误并说明危害。"]]},{"type":"quote","text":"【材料】实验室常用的电流表有三个接线柱：「−」「0.6」「3」，对应 0～0.6 A 和 0～3 A 两个量程，表盘上画着两排刻度数字。使用规则是：电流表必须串联在被测电路中；电流要从「+」接线柱流入、从「−」接线柱流出；被测电流不要超过量程；在不能估计电流大小时，先用最大量程「试触」；绝不允许把电流表直接连到电源的两极上。\n小明用 0～0.6 A 量程测量通过小灯泡的电流，指针停在 0.3 A 刻度线之后第 4 个小格处。为了「看得更清楚」，他又把电流表并联在小灯泡的两端，闭合开关后指针迅速偏到满偏。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】小明测得的电流是多少？写出你的读数依据。（3 分）","【设问】为什么不能估计被测电流大小时，要先用大量程试触？（3 分）","【设问】指出小明把电流表并联在小灯泡两端这一做法的错误，并说明指针满偏的原因，写出正确的接法。（4 分）"]}],"questions":[{"id":"phy-electric-3-q1","type":"choice","stem":"如图所示的电路中，闭合开关后两只小灯泡都发光。关于图中电流表的测量对象，下列说法正确的是","answer":"C","explain":"图中电流表串联在分支点之前的那段导线上，是两条支路电流都必须经过的位置，所以测的是干路电流，C 正确。A、B 错：要测某条支路的电流，电流表必须接在该支路内（接在灯泡与分支点之间），图中并不是这样接的。D 错：电流表测的是电流而不是电压，测电压要用电压表并联在电源两端。","options":["测的是通过 L1 的电流","测的是通过 L2 的电流","测的是干路电流，即通过 L1 与 L2 的电流之和","测的是电源两端的电压"],"difficulty":2,"tags":["电流表接法"],"figure":{"id":"fig-elec-ammeter-7","title":"判断电流表测哪一部分的电流","caption":"看电流表接在分支点的哪一侧","view":"wide","alt":"两只灯泡并联，电流表串联在电池组与左侧分支点之间的干路上，测的是干路电流","prims":[{"t":"line","x1":20,"y1":14,"x2":21.4,"y2":14},{"t":"line","x1":38.6,"y1":14,"x2":52,"y2":14},{"t":"line","x1":63,"y1":14,"x2":82,"y2":14},{"t":"line","x1":20,"y1":14,"x2":20,"y2":45},{"t":"line","x1":82,"y1":14,"x2":82,"y2":45},{"t":"line","x1":20,"y1":27,"x2":42.4,"y2":27},{"t":"line","x1":59.6,"y1":27,"x2":82,"y2":27},{"t":"line","x1":20,"y1":45,"x2":42.4,"y2":45},{"t":"line","x1":59.6,"y1":45,"x2":82,"y2":45},{"t":"battery","x":56,"y":14,"label":"电源"},{"t":"meter","x":30,"y":14,"kind":"A"},{"t":"bulb","x":51,"y":27,"label":"L1"},{"t":"bulb","x":51,"y":45,"label":"L2"},{"t":"junction","x":20,"y":27},{"t":"junction","x":82,"y":27}]}},{"id":"phy-electric-3-q2","type":"choice","stem":"关于电流表的使用，下列说法正确的是","answer":"D","explain":"D 是电流表使用的完整规范。A 错：电流表内阻极小，直接接在电源两极上相当于电源短路，电流很大，会烧坏电流表和电源。B 错：并联在被测元件两端会把该元件短路，既测不出它的电流，还可能烧坏电流表。C 错：接线柱接反时指针向左反偏，无法读数，还可能损坏表针。","options":["电流表可以直接接在电源的两极上测量电源提供的电流","电流表要并联在被测电路的两端","电流表的「+」「−」接线柱可以任意连接，指针反偏也不影响读数","电流表要串联在被测电路中，并使电流从「+」接线柱流入、从「−」接线柱流出"],"difficulty":1,"tags":["电流表使用"]},{"id":"phy-electric-3-q3","type":"choice","stem":"某电流表有 0～0.6 A 和 0～3 A 两个量程。某次测量选用 0～0.6 A 量程，指针恰好指在标有 0.4 的刻度线上。下列说法正确的是","answer":"A","explain":"0～0.6 A 量程把满偏分成 30 小格，分度值为 0.6 A ÷ 30 = 0.02 A，指针指在 0.4 A 刻度线上读数就是 0.4 A，A 正确。B 错：0.1 A 是 0～3 A 量程的分度值，两个量程的分度值不同。C 错：换成 0～3 A 量程后，同一指针位置对应的是 2 A，读数随量程改变而改变。D 错：在不超过量程的前提下应尽量用小量程，分度值小、读数更准确；一律用大量程会降低测量精度。","options":["0～0.6 A 量程的分度值是 0.02 A，读数应记为 0.4 A","0～0.6 A 量程的分度值是 0.1 A，读数应记为 0.40 A","把量程换成 0～3 A 后，指针位置不变，读数仍应记为 0.4 A","为了安全，测量时应一律选用 0～3 A 量程"],"difficulty":2,"tags":["电流表读数","量程"]},{"id":"phy-electric-3-q4","type":"choice","stem":"由灯泡 L1、L2 组成的串联电路，闭合开关后两灯都不亮。某同学用一只电流表并联在 L1 两端，发现 L2 亮了起来，电流表也有读数。由此可以判断","answer":"B","explain":"电流表的电阻很小，并联在 L1 两端相当于用一段导线把 L1 的两端连接起来。此时 L2 能发光，说明电源、开关、导线以及 L2 都是完好的，故障只可能出在 L1 上；接上电流表后电路恢复通路，说明原来 L1 处是断开的，即 L1 断路，B 正确，这也是检测断路位置的常用方法。A 错：若 L1 短路，闭合开关时 L2 会亮而 L1 不亮，与「两灯都不亮」矛盾。C、D 错：故障若在 L2 上，并联电流表在 L1 两端不会让 L2 发光。","options":["L1 短路","L1 断路","L2 断路","L2 短路"],"difficulty":3,"tags":["电路故障","电流表接法"]},{"id":"phy-electric-3-q5","type":"fill","stem":"某电流表选用 0～0.6 A 量程测量电流，表盘上每一小格表示的电流值是 ______ A。","answer":"0.02|0.02A|0.02 A","explain":"分度值 = 量程 ÷ 小格数 = 0.6 A ÷ 30 = 0.02 A。若换成 0～3 A 量程，小格数同样是 30 格，分度值就是 3 A ÷ 30 = 0.1 A。填写这类空的关键是先确认量程，而不要凭印象写「0.1 A」。","difficulty":1,"tags":["电流表读数"],"figure":{"id":"fig-elec-dial-a1","title":"0～0.6 A 量程的分度值","caption":"0～0.6 A 量程把满偏分成 30 小格，分度值 0.6 A ÷ 30 = 0.02 A；同一只表盘改用 0～3 A 量程时变成 0.1 A","view":"square","alt":"电流表表盘，量程 0 到 0.6 安，刻度数字依次为 0、0.2、0.4、0.6，每两个数字之间有 10 个小格，指针从中心指向 0.4 安刻度线","prims":[{"t":"circle","cx":50,"cy":56,"r":32,"dashed":true,"tone":"muted"},{"t":"text","x":50,"y":16,"text":"电流表","size":4.6,"tone":"main"},{"t":"curve","points":[[27.48,43],[28.07,42.03],[28.7,41.09],[29.37,40.17],[30.08,39.29],[30.83,38.43],[31.62,37.62],[32.43,36.83],[33.29,36.08],[34.17,35.37],[35.09,34.7],[36.03,34.07],[37,33.48],[37.99,32.94],[39.01,32.44],[40.05,31.98],[41.11,31.57],[42.18,31.2],[43.27,30.89],[44.37,30.62],[45.49,30.39],[46.61,30.22],[47.73,30.1],[48.87,30.02],[50,30],[51.13,30.02],[52.27,30.1],[53.39,30.22],[54.51,30.39],[55.63,30.62],[56.73,30.89],[57.82,31.2],[58.89,31.57],[59.95,31.98],[60.99,32.44],[62.01,32.94],[63,33.48],[63.97,34.07],[64.91,34.7],[65.83,35.37],[66.71,36.08],[67.57,36.83],[68.38,37.62],[69.17,38.43],[69.92,39.29],[70.63,40.17],[71.3,41.09],[71.93,42.03],[72.52,43]],"tone":"main","width":0.5},{"t":"line","x1":27.48,"y1":43,"x2":30.77,"y2":44.9,"tone":"main","width":0.5},{"t":"text","x":33.89,"y":46.7,"text":"0","size":3.4,"tone":"muted"},{"t":"line","x1":28.45,"y1":41.46,"x2":30.1,"y2":42.58,"tone":"main","width":0.28},{"t":"line","x1":29.51,"y1":39.99,"x2":31.09,"y2":41.22,"tone":"main","width":0.28},{"t":"line","x1":30.68,"y1":38.6,"x2":32.16,"y2":39.94,"tone":"main","width":0.28},{"t":"line","x1":31.94,"y1":37.3,"x2":33.33,"y2":38.74,"tone":"main","width":0.28},{"t":"line","x1":33.29,"y1":36.08,"x2":34.57,"y2":37.61,"tone":"main","width":0.28},{"t":"line","x1":34.72,"y1":34.97,"x2":35.89,"y2":36.58,"tone":"main","width":0.28},{"t":"line","x1":36.22,"y1":33.95,"x2":37.28,"y2":35.65,"tone":"main","width":0.28},{"t":"line","x1":37.79,"y1":33.04,"x2":38.73,"y2":34.81,"tone":"main","width":0.28},{"t":"line","x1":39.42,"y1":32.25,"x2":40.24,"y2":34.07,"tone":"main","width":0.28},{"t":"line","x1":41.11,"y1":31.57,"x2":42.41,"y2":35.14,"tone":"main","width":0.5},{"t":"text","x":43.64,"y":38.52,"text":"0.2","size":3.4,"tone":"muted"},{"t":"line","x1":42.83,"y1":31.01,"x2":43.38,"y2":32.93,"tone":"main","width":0.28},{"t":"line","x1":44.59,"y1":30.57,"x2":45.01,"y2":32.52,"tone":"main","width":0.28},{"t":"line","x1":46.38,"y1":30.25,"x2":46.66,"y2":32.23,"tone":"main","width":0.28},{"t":"line","x1":48.19,"y1":30.06,"x2":48.33,"y2":32.06,"tone":"main","width":0.28},{"t":"line","x1":50,"y1":30,"x2":50,"y2":32,"tone":"main","width":0.28},{"t":"line","x1":51.81,"y1":30.06,"x2":51.67,"y2":32.06,"tone":"main","width":0.28},{"t":"line","x1":53.62,"y1":30.25,"x2":53.34,"y2":32.23,"tone":"main","width":0.28},{"t":"line","x1":55.41,"y1":30.57,"x2":54.99,"y2":32.52,"tone":"main","width":0.28},{"t":"line","x1":57.17,"y1":31.01,"x2":56.62,"y2":32.93,"tone":"main","width":0.28},{"t":"line","x1":58.89,"y1":31.57,"x2":57.59,"y2":35.14,"tone":"main","width":0.5},{"t":"text","x":56.36,"y":38.52,"text":"0.4","size":3.4,"tone":"muted"},{"t":"line","x1":60.58,"y1":32.25,"x2":59.76,"y2":34.07,"tone":"main","width":0.28},{"t":"line","x1":62.21,"y1":33.04,"x2":61.27,"y2":34.81,"tone":"main","width":0.28},{"t":"line","x1":63.78,"y1":33.95,"x2":62.72,"y2":35.65,"tone":"main","width":0.28},{"t":"line","x1":65.28,"y1":34.97,"x2":64.11,"y2":36.58,"tone":"main","width":0.28},{"t":"line","x1":66.71,"y1":36.08,"x2":65.43,"y2":37.61,"tone":"main","width":0.28},{"t":"line","x1":68.06,"y1":37.3,"x2":66.67,"y2":38.74,"tone":"main","width":0.28},{"t":"line","x1":69.32,"y1":38.6,"x2":67.84,"y2":39.94,"tone":"main","width":0.28},{"t":"line","x1":70.49,"y1":39.99,"x2":68.91,"y2":41.22,"tone":"main","width":0.28},{"t":"line","x1":71.55,"y1":41.46,"x2":69.9,"y2":42.58,"tone":"main","width":0.28},{"t":"line","x1":72.52,"y1":43,"x2":69.23,"y2":44.9,"tone":"main","width":0.5},{"t":"text","x":66.11,"y":46.7,"text":"0.6","size":3.4,"tone":"muted"},{"t":"line","x1":48.76,"y1":59.42,"x2":57.8,"y2":34.58,"tone":"danger","width":0.7},{"t":"circle","cx":50,"cy":56,"r":1.5,"fill":true,"tone":"main"},{"t":"text","x":50,"y":92,"text":"满偏 30 小格：分度值 = 0.6 A ÷ 30 = 0.02 A","size":3.8,"tone":"muted"}]}},{"id":"phy-electric-3-q6","type":"short","stem":"在由灯泡 L1、L2 组成的串联电路中，电流表的读数为 0.25 A。求：（1）通电 4 min 通过灯 L1 的电荷量；（2）若把这只电流表改接到 L2 的另一侧，读数应该是多少？为什么？","answer":"（1）t = 4 min = 240 s，Q = It = 0.25 A × 240 s = 60 C；（2）读数仍是 0.25 A，因为串联电路中电流处处相等，与电流表接在哪个位置无关。","explain":"为什么这么做：第（1）问用电荷量的定义式 Q = It，先把时间换成秒；第（2）问考的是串联电路的电流规律——串联只有一条电流路径，电流不会被用电器「消耗」，所以把电流表移到电路的任何位置读数都不变。常见错误是把第（2）问答成「变小」，那是把电流当成水流、以为灯泡会「用掉」电流。","difficulty":2,"tags":["串联电流规律","计算"],"rubric":["正确换算时间 240 s（1 分）","写出 Q = It 并算出 60 C（1 分）","第（2）问答出 0.25 A 并说明依据（2 分）"],"steps":["（1）时间换算：t = 4 min = 240 s。","由 I = Q/t 得 Q = It = 0.25 A × 240 s = 60 C。","（2）依据串联电路电流规律 I = I₁ = I₂，各处电流相等。","答：通过 L1 的电荷量为 60 C；改接后读数仍为 0.25 A，因为串联电路中电流处处相等。"],"figure":{"id":"fig-elec-series-a","title":"串联电路：电流表的位置不影响读数","caption":"L1、L2 串联只有一条电流路径，电流表串在电路的哪一处，读数都相同","view":"wide","alt":"电源、电流表、开关与两只灯泡 L1、L2 依次串联成一条回路，电流表接在电源与灯泡之间","prims":[{"t":"line","x1":18,"y1":16,"x2":22,"y2":16},{"t":"line","x1":33,"y1":16,"x2":43.4,"y2":16},{"t":"line","x1":60.6,"y1":16,"x2":68,"y2":16},{"t":"line","x1":80,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":29.4,"y2":48},{"t":"line","x1":46.6,"y1":48,"x2":57.4,"y2":48},{"t":"line","x1":74.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":26,"y":16,"label":"电源"},{"t":"meter","x":52,"y":16,"kind":"A","label":"电流表"},{"t":"switch","x":74,"y":16,"closed":true,"label":"S"},{"t":"bulb","x":38,"y":48,"label":"L1"},{"t":"bulb","x":66,"y":48,"label":"L2"},{"t":"text","x":50,"y":58,"text":"电流表读数为 0.25 A，改接到 L2 的另一侧仍是 0.25 A","size":3.6,"tone":"accent"}]}},{"id":"phy-electric-3-q7","type":"short","stem":"请设计实验探究并联电路中干路电流与各支路电流的关系。写出器材、实验步骤、需要记录的数据表格栏目，以及为得出普遍规律应采取的措施。","answer":"器材：电源、两只规格不同的小灯泡、开关、电流表、导线若干。步骤：(1) 按并联连接 L1、L2，把电流表串联在干路上，闭合开关记录电流 I，然后断开开关；(2) 把电流表改接到 L1 支路，闭合开关记录 I₁，断开开关；(3) 再把电流表改接到 L2 支路，记录 I₂；(4) 比较 I 与 I₁ + I₂。数据表格栏目：测量位置、电流 I/A（干路、L1 支路、L2 支路各一行）。为了得出普遍规律，应换用不同规格的灯泡（或改变电源电压）重复上述实验多次，避免因灯泡规格相同而出现巧合。结论：并联电路中干路电流等于各支路电流之和，即 I = I₁ + I₂。","explain":"实验设计的关键有三点：一是电流表必须串联在要测的那一段（测干路接在分支点之前或汇合点之后，测支路接在支路内部）；二是每次改接前都要断开开关，接好后再闭合；三是只测一组数据说服力不够，要换用不同规格的灯泡多次测量，才能排除偶然性。若发现读数与 I = I₁ + I₂ 明显不符，应先检查电流表是否接错位置、量程与分度值是否读错，而不是直接改数据。","difficulty":3,"tags":["实验探究","并联电流规律"],"rubric":["器材完整：电源、两只规格不同的灯泡、开关、电流表、导线（1 分）","电流表分别串联在干路、L1 支路、L2 支路三处，改接前断开开关（1 分）","设计数据记录表格，栏目含测量位置与电流值（1 分）","换用不同规格灯泡多次测量，说明是为了得出普遍规律（1 分）"]},{"id":"phy-electric-3-q8","type":"short","stem":"请画出符合要求的电路图：灯泡 L1 与 L2 并联，电源和开关 S 接在干路上，另用一只电流表测量通过 L2 的电流。","answer":"见参考答案图：L1、L2 各占一条支路，电流表串联在 L2 所在的那条支路内；电源与开关串联在干路上。","explain":"作图要点：要测谁就把电流表与谁串联，所以电流表必须画在 L2 的支路里（L2 与分支点之间），不能画在干路上，也不能并在 L2 两端。容易出错的画法：把电流表画在干路上（测的就成了干路电流）；把电流表并在 L2 两端（会把 L2 短路）；漏画结点导致支路与干路的连接关系不清。","difficulty":3,"tags":["电路作图","电流表接法"],"rubric":["L1 与 L2 并联，电源与开关接在干路上（1 分）","电流表串联在 L2 所在的那条支路内，既不接在干路，也不并联在 L2 两端（1 分）","电流表符号正确，支路与干路的相接处画出结点（1 分）"],"answerFigure":{"id":"fig-elec-draw-3-ans","title":"参考答案：电流表串联在 L2 支路内","caption":"要测哪条支路的电流，就把电流表串联在那条支路里","view":"wide","alt":"两只灯泡并联，电流表串联在 L2 所在的支路中，电源与开关串联在干路上","prims":[{"t":"line","x1":20,"y1":14,"x2":47,"y2":14},{"t":"line","x1":58,"y1":14,"x2":82,"y2":14},{"t":"line","x1":20,"y1":14,"x2":20,"y2":45},{"t":"line","x1":82,"y1":14,"x2":82,"y2":45},{"t":"line","x1":20,"y1":27,"x2":42.4,"y2":27},{"t":"line","x1":59.6,"y1":27,"x2":82,"y2":27},{"t":"line","x1":20,"y1":45,"x2":21.4,"y2":45},{"t":"line","x1":38.6,"y1":45,"x2":53.4,"y2":45},{"t":"line","x1":70.6,"y1":45,"x2":82,"y2":45},{"t":"battery","x":51,"y":14,"label":"电源"},{"t":"bulb","x":51,"y":27,"label":"L1"},{"t":"meter","x":30,"y":45,"kind":"A","label":"A（测 L2）"},{"t":"bulb","x":62,"y":45,"label":"L2"},{"t":"junction","x":20,"y":27},{"t":"junction","x":82,"y":27}]}},{"id":"phy-electric-3-m1-q1","type":"short","stem":"小明测得的电流是多少？写出你的读数依据。（3 分）","answer":"0.38 A。依据：所选量程是 0～0.6 A，该量程每一小格（分度值）为 0.02 A，指针从 0.3 A 刻度线偏过 4 个小格，所以读数为 0.3 A + 4 × 0.02 A = 0.38 A。","explain":"","tags":["电流表读数"],"rubric":["答出分度值 0.02 A（1 分）","写出读数方法：0.3 A 加 4 小格（1 分）","结果 0.38 A 并写单位（1 分）"]},{"id":"phy-electric-3-m1-q2","type":"short","stem":"为什么不能估计被测电流大小时，要先用大量程试触？（3 分）","answer":"如果直接用小量程，电流一旦超过量程就会把指针打弯甚至烧坏电流表。用大量程试触时，闭合开关（或让开关迅速接触后立即断开），观察指针偏转：若偏转很小，说明电流远小于小量程，再换用小量程测量，这样既安全又能提高读数的准确性。","explain":"","tags":["电流表使用","量程选择"],"rubric":["说明大量程试触是为了保护电流表、防止超过量程（1 分）","说明试触后根据指针偏转情况决定是否换小量程（1 分）","指出换小量程的目的是使读数更准确（分度值更小）（1 分）"]},{"id":"phy-electric-3-m1-q3","type":"short","stem":"指出小明把电流表并联在小灯泡两端这一做法的错误，并说明指针满偏的原因，写出正确的接法。（4 分）","answer":"错误：电流表必须串联在被测电路中，不能并联在用电器两端。原因：电流表的电阻极小，并联在灯泡两端相当于给灯泡并联了一根导线，灯泡被短路，电路中的电流几乎全部从电流表通过，电流远超过量程，所以指针迅速打到满偏，时间长了会烧坏电流表。正确接法：把电流表串联在小灯泡所在的那条支路中，让电流从「+」接线柱流入，并选择适当的量程。","explain":"","tags":["电流表接法","短路"],"rubric":["指出电流表应串联、不能并联在用电器两端（1 分）","说明电流表电阻极小、相当于一根导线（1 分）","说明灯泡被短路、通过电流表的电流过大导致指针满偏（1 分）","给出正确接法：串联在支路中，注意「+」「−」接线柱与量程（1 分）"]}]},{"id":"phy-electric-4","title":"电压与电阻：电压表的使用、电压规律与变阻器","subtitle":"人教版九年级 · 第 16 章 电压 电阻 · 9a","grade":"9a","tags":["人教版九年级 · 第 16 章 电压 电阻"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 16 章 电压 电阻 · 9a"},{"type":"note","title":"问题切入","text":"为什么电路里没有电源，用电器就不工作？电压表为什么必须并联在被测元件两端？同样是导线，为什么又长又细的镍铬合金线电阻大，而短而粗的铜线电阻小？滑动变阻器凭什么能连续地改变电路中的电流？"},{"type":"note","title":"一句话抓住关键","text":"电压是使电路中形成电流的原因，电源的作用就是提供电压；电压表并联在被测元件两端，串联电路总电压等于各部分电压之和，并联电路各支路电压相等且等于电源电压。电阻是导体本身的一种性质，由材料、长度、横截面积（以及温度）决定，与电压、电流无关；滑动变阻器靠改变接入电路的电阻线长度来连续改变电阻。"},{"type":"h","text":"先看现象：有电压才有电流，电压表并联着「量」"},{"type":"p","text":"把灯泡接在电源两端，闭合开关灯就亮；如果两只灯泡串联后再接上，亮度会变暗，但电路里始终有电流。电源的两极之间存在着电压，正是这个电压推动电荷定向移动形成电流，所以电源的作用是提供电压。既然电压是某两点之间的「差值」，测量时就要把电压表并联在这两点之间——电压表的两端接在谁的两端，它测的就是谁的电压。"},{"type":"figure","figure":{"id":"fig-elec-voltmeter-1","title":"电压表并联在灯泡两端","caption":"电压表的两根导线接在灯泡两端，测的就是灯泡两端的电压","view":"wide","alt":"电源、开关、灯泡串联成回路，电压表的两端分别接在灯泡的两侧，与灯泡并联","prims":[{"t":"line","x1":18,"y1":16,"x2":26,"y2":16},{"t":"line","x1":37,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":41.4,"y2":48},{"t":"line","x1":58.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":30,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"bulb","x":50,"y":48,"label":"L"},{"t":"line","x1":41.4,"y1":48,"x2":41.4,"y2":32},{"t":"line","x1":58.6,"y1":48,"x2":58.6,"y2":32},{"t":"meter","x":50,"y":32,"kind":"V","label":"电压表"},{"t":"junction","x":41.4,"y":48},{"t":"junction","x":58.6,"y":48}]}},{"type":"note","title":"","text":"电压表与被测元件并联，不是串联；串联进去后电压表的电阻极大，电路中电流几乎为零，用电器都不能工作。"},{"type":"h","text":"抓住哪个量：电压的单位、量程与读数"},{"type":"p","text":"电压用 U 表示，单位是伏特（V），还有千伏（kV）和毫伏（mV）。需要记住的几个值：一节新干电池的电压是 1.5 V，我国家庭电路的电压是 220 V，对人体安全的电压不高于 36 V。实验室的电压表有 0～3 V 和 0～15 V 两个量程。读数同样是三步：看量程、算分度值、数小格。0～3 V 量程把满偏分成 30 小格，分度值 0.1 V；0～15 V 量程也分成 30 小格，分度值 0.5 V。"},{"type":"figure","figure":{"id":"fig-elec-voltmeter-2","title":"电压表表盘：0～3 V 量程的读数","caption":"0～3 V 量程，一大格 1 V、一小格 0.1 V，指针指在 2.4 V 处","view":"square","alt":"电压表表盘，量程 0 到 3 伏，刻度数字为 0、1、2、3，指针从中心指向 2.4 伏刻度线","prims":[{"t":"circle","cx":50,"cy":56,"r":32,"dashed":true,"tone":"muted"},{"t":"text","x":50,"y":16,"text":"电压表","size":4.6,"tone":"main"},{"t":"curve","points":[[27.48,43],[28.07,42.03],[28.7,41.09],[29.37,40.17],[30.08,39.29],[30.83,38.43],[31.62,37.62],[32.43,36.83],[33.29,36.08],[34.17,35.37],[35.09,34.7],[36.03,34.07],[37,33.48],[37.99,32.94],[39.01,32.44],[40.05,31.98],[41.11,31.57],[42.18,31.2],[43.27,30.89],[44.37,30.62],[45.49,30.39],[46.61,30.22],[47.73,30.1],[48.87,30.02],[50,30],[51.13,30.02],[52.27,30.1],[53.39,30.22],[54.51,30.39],[55.63,30.62],[56.73,30.89],[57.82,31.2],[58.89,31.57],[59.95,31.98],[60.99,32.44],[62.01,32.94],[63,33.48],[63.97,34.07],[64.91,34.7],[65.83,35.37],[66.71,36.08],[67.57,36.83],[68.38,37.62],[69.17,38.43],[69.92,39.29],[70.63,40.17],[71.3,41.09],[71.93,42.03],[72.52,43]],"tone":"main","width":0.5},{"t":"line","x1":27.48,"y1":43,"x2":30.77,"y2":44.9,"tone":"main","width":0.5},{"t":"text","x":33.89,"y":46.7,"text":"0","size":3.4,"tone":"muted"},{"t":"line","x1":28.45,"y1":41.46,"x2":30.1,"y2":42.58,"tone":"main","width":0.28},{"t":"line","x1":29.51,"y1":39.99,"x2":31.09,"y2":41.22,"tone":"main","width":0.28},{"t":"line","x1":30.68,"y1":38.6,"x2":32.16,"y2":39.94,"tone":"main","width":0.28},{"t":"line","x1":31.94,"y1":37.3,"x2":33.33,"y2":38.74,"tone":"main","width":0.28},{"t":"line","x1":33.29,"y1":36.08,"x2":34.57,"y2":37.61,"tone":"main","width":0.28},{"t":"line","x1":34.72,"y1":34.97,"x2":35.89,"y2":36.58,"tone":"main","width":0.28},{"t":"line","x1":36.22,"y1":33.95,"x2":37.28,"y2":35.65,"tone":"main","width":0.28},{"t":"line","x1":37.79,"y1":33.04,"x2":38.73,"y2":34.81,"tone":"main","width":0.28},{"t":"line","x1":39.42,"y1":32.25,"x2":40.24,"y2":34.07,"tone":"main","width":0.28},{"t":"line","x1":41.11,"y1":31.57,"x2":42.41,"y2":35.14,"tone":"main","width":0.5},{"t":"text","x":43.64,"y":38.52,"text":"1","size":3.4,"tone":"muted"},{"t":"line","x1":42.83,"y1":31.01,"x2":43.38,"y2":32.93,"tone":"main","width":0.28},{"t":"line","x1":44.59,"y1":30.57,"x2":45.01,"y2":32.52,"tone":"main","width":0.28},{"t":"line","x1":46.38,"y1":30.25,"x2":46.66,"y2":32.23,"tone":"main","width":0.28},{"t":"line","x1":48.19,"y1":30.06,"x2":48.33,"y2":32.06,"tone":"main","width":0.28},{"t":"line","x1":50,"y1":30,"x2":50,"y2":32,"tone":"main","width":0.28},{"t":"line","x1":51.81,"y1":30.06,"x2":51.67,"y2":32.06,"tone":"main","width":0.28},{"t":"line","x1":53.62,"y1":30.25,"x2":53.34,"y2":32.23,"tone":"main","width":0.28},{"t":"line","x1":55.41,"y1":30.57,"x2":54.99,"y2":32.52,"tone":"main","width":0.28},{"t":"line","x1":57.17,"y1":31.01,"x2":56.62,"y2":32.93,"tone":"main","width":0.28},{"t":"line","x1":58.89,"y1":31.57,"x2":57.59,"y2":35.14,"tone":"main","width":0.5},{"t":"text","x":56.36,"y":38.52,"text":"2","size":3.4,"tone":"muted"},{"t":"line","x1":60.58,"y1":32.25,"x2":59.76,"y2":34.07,"tone":"main","width":0.28},{"t":"line","x1":62.21,"y1":33.04,"x2":61.27,"y2":34.81,"tone":"main","width":0.28},{"t":"line","x1":63.78,"y1":33.95,"x2":62.72,"y2":35.65,"tone":"main","width":0.28},{"t":"line","x1":65.28,"y1":34.97,"x2":64.11,"y2":36.58,"tone":"main","width":0.28},{"t":"line","x1":66.71,"y1":36.08,"x2":65.43,"y2":37.61,"tone":"main","width":0.28},{"t":"line","x1":68.06,"y1":37.3,"x2":66.67,"y2":38.74,"tone":"main","width":0.28},{"t":"line","x1":69.32,"y1":38.6,"x2":67.84,"y2":39.94,"tone":"main","width":0.28},{"t":"line","x1":70.49,"y1":39.99,"x2":68.91,"y2":41.22,"tone":"main","width":0.28},{"t":"line","x1":71.55,"y1":41.46,"x2":69.9,"y2":42.58,"tone":"main","width":0.28},{"t":"line","x1":72.52,"y1":43,"x2":69.23,"y2":44.9,"tone":"main","width":0.5},{"t":"text","x":66.11,"y":46.7,"text":"3","size":3.4,"tone":"muted"},{"t":"line","x1":47.86,"y1":58.94,"x2":63.4,"y2":37.55,"tone":"danger","width":0.7},{"t":"circle","cx":50,"cy":56,"r":1.5,"fill":true,"tone":"main"},{"t":"text","x":50,"y":92,"text":"量程 0～3 V，分度值 0.1 V","size":3.8,"tone":"muted"},{"t":"text","x":50,"y":97,"text":"指针指在 2.4 V 处","size":3.8,"tone":"muted"}]}},{"type":"note","title":"","text":"不管电流表还是电压表，接错量程的读数都会差 5 倍：「0～0.6 A／0～3 A」与「0～3 V／0～15 V」都是同一表盘的两排刻度。"},{"type":"h","text":"建立关系：串联分压，并联电压相等"},{"type":"p","text":"两只灯泡串联时，电源的电压被「分成」两部分：L1 两端一段、L2 两端一段，两段之和等于电源电压，即 U = U₁ + U₂，这就是串联分压。所以说「串联电路中电流处处相等、电压按需分配」。两只灯泡并联时，它们的两端分别接在同两点之间，因此各支路两端的电压完全相同，还都等于电源电压，即 U = U₁ = U₂。把电压表分别并联在 L1、L2 和电源两端测量，就能验证这两条规律。"},{"type":"figure","figure":{"id":"fig-elec-voltage-1","title":"串联电路中的电压关系","caption":"电压表并联在 L2 两端，U = U₁ + U₂","view":"wide","alt":"电源、开关与两只灯泡 L1、L2 串联，电压表并联在 L2 两端测量 L2 的电压","prims":[{"t":"line","x1":18,"y1":16,"x2":22,"y2":16},{"t":"line","x1":33,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":27.4,"y2":48},{"t":"line","x1":44.6,"y1":48,"x2":55.4,"y2":48},{"t":"line","x1":72.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":26,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"bulb","x":36,"y":48,"label":"L1"},{"t":"bulb","x":64,"y":48,"label":"L2"},{"t":"line","x1":55.4,"y1":48,"x2":55.4,"y2":32},{"t":"line","x1":72.6,"y1":48,"x2":72.6,"y2":32},{"t":"meter","x":64,"y":32,"kind":"V","label":"电压表"},{"t":"junction","x":55.4,"y":48},{"t":"junction","x":72.6,"y":48},{"t":"text","x":50,"y":58,"text":"U = U₁ + U₂","size":4.2,"tone":"accent"}]}},{"type":"note","title":"","text":"串联分压不是「平均分」：各元件分得的电压与它的电阻有关；并联时不存在「分压」，各支路电压一律相等。"},{"type":"h","text":"换个情境：电阻由什么决定"},{"type":"p","text":"把不同的导线接进同一个电路，电流表的示数会不一样，说明它们的电阻不同。研究发现，导体的电阻由四个因素决定：材料、长度、横截面积和温度。同种材料、横截面积相同时，导线越长电阻越大；同种材料、长度相同时，横截面积越小（越细）电阻越大；长度和横截面积相同时，材料不同电阻也不同，镍铬合金线的电阻比同样规格的铜线大得多；对金属导体来说，温度升高，电阻会变大。要注意：电阻是导体本身的性质，跟它两端有没有电压、有没有电流通过都没有关系。"},{"type":"figure","figure":{"id":"fig-elec-resistance-1","title":"决定电阻大小的因素","caption":"同样的使用条件下，越长越细的导线电阻越大","view":"wide","alt":"三根电阻丝的示意图，A 短而粗电阻小，B 长而细电阻大，C 表示温度升高时金属导体电阻变大","prims":[{"t":"resistor","x":26,"y":20,"w":24,"h":5,"label":"A"},{"t":"resistor","x":26,"y":36,"w":24,"h":5,"label":"B"},{"t":"resistor","x":26,"y":52,"w":24,"h":5,"label":"C"},{"t":"text","x":50,"y":20,"text":"短而粗：电阻小","anchor":"start","size":3.8},{"t":"text","x":50,"y":36,"text":"长而细：电阻大","anchor":"start","size":3.8},{"t":"text","x":50,"y":52,"text":"温度升高：电阻变大","anchor":"start","size":3.8}]}},{"type":"note","title":"","text":"控制变量是这里的分析套路：研究长度的影响，就必须让材料、横截面积都相同，只让长度不同。"},{"type":"h","text":"滑动变阻器：一上一下，滑片一动电阻就变"},{"type":"p","text":"滑动变阻器的电阻丝绕在瓷筒上，上面有一根金属棒，滑片可以左右滑动。接入电路时必须「一上一下」各用一个接线柱：电流从下面的接线柱流入电阻丝，经过滑片流到金属棒，再从上面的接线柱流出——接入电路的只是「滑片到所接下接线柱之间」的那一段电阻丝。所以滑片离所接的下接线柱越远，接入的电阻丝越长、电阻越大，电路中的电流就越小。如果把两个上接线柱或两个下接线柱接入电路，移动滑片时接入的电阻都不变，变阻器就失效了。"},{"type":"figure","figure":{"id":"fig-elec-rheostat-1","title":"滑动变阻器与灯泡串联，改变电流","caption":"滑片向右移动使接入电阻变大，灯泡变暗","view":"wide","alt":"电源、开关、滑动变阻器与灯泡串联成回路，滑动变阻器接的是左下的接线柱与金属棒上的接线柱","prims":[{"t":"line","x1":18,"y1":16,"x2":22,"y2":16},{"t":"line","x1":33,"y1":16,"x2":42,"y2":16},{"t":"line","x1":66,"y1":16,"x2":68,"y2":16},{"t":"line","x1":80,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":41.4,"y2":48},{"t":"line","x1":58.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":26,"y":16,"label":"电源"},{"t":"rheostat","x":54,"y":16,"label":"滑动变阻器"},{"t":"switch","x":74,"y":16,"closed":true,"label":"S"},{"t":"bulb","x":50,"y":48,"label":"L"},{"t":"text","x":50,"y":58,"text":"接入电阻变大 → 电流变小 → 灯变暗","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"变阻器在实验中的两个常见作用：一是保护电路（闭合开关前把电阻调到最大）；二是通过改变电阻来改变电路中的电流和被测元件两端的电压，实现多次测量。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["电压的单位换算","1 kV = 1000 V；1 V = 1000 mV","只在单位换算与估测中使用。要记住的常见值：一节新干电池 1.5 V，一节铅蓄电池 2 V，我国家庭电路 220 V，对人体安全的电压不高于 36 V。代入公式前先把所有电压换成同一单位（一般用 V），否则会算错倍数。"],["串联电路的电压规律","U = U₁ + U₂","U：总电压（电源电压）；U₁、U₂：各部分电压，单位都为伏特（V） · 只适用于串联电路，式中的 U₁、U₂ 必须是同一时刻测得的两部分电压（同时性）。用于由总电压与一部分电压求另一部分电压，也用于检验测量数据是否合理；不能用于并联电路，并联时各支路电压相等、不存在「相加」。"],["并联电路的电压规律","U = U₁ = U₂","U：电源电压；U₁、U₂：各支路两端的电压，单位都为伏特（V） · 只适用于并联电路（忽略导线上的电压损失）。它解释了为什么家用电器都并联接入 220 V 的家庭电路——各用电器两端电压都等于 220 V，都能在自己额定电压下工作。若把额定电压 220 V 的用电器串联，各电器分得的电压都小于 220 V，都不能正常工作。"],["电阻的决定因素","导体的电阻由材料、长度、横截面积和温度决定，与电压、电流无关","用于判断电阻大小的变化：同种材料、横截面积相同，长度越长电阻越大；同种材料、长度相同，横截面积越小电阻越大；对金属导体，温度升高电阻变大。判断时必须用控制变量的思路——只说「导线越长电阻越大」是不完整的，前提是材料与横截面积相同。"],["欧姆定律（用来判断变阻器的作用）","I = (U)/(R)","I：电流，安培（A）；U：电压，伏特（V）；R：电阻，欧姆（Ω） · 这是第 17 章的核心公式，这里先用它的定性结论：电源电压不变时，接入电阻变大，电流变小。使用时的两条纪律必须记住——同一性：式中的 U、I、R 必须是同一段导体（或同一个元件）的三个量；同时性：必须是同一时刻的值。滑动变阻器与灯泡串联时，变阻器的 R 变大，电流 I 变化，灯泡两端的电压 U 也随之改变，绝不能把变阻器的电阻与灯泡的电压混在一起算。"]]},{"type":"h","text":"应用 · 由串联分压求各部分电压"},{"type":"note","title":"情境","text":"某串联电路中电源电压为 6 V，闭合开关后测得 L1 两端的电压为 2.5 V。求 L2 两端的电压。"},{"type":"note","title":"模型与思路","text":"串联电路的总电压等于各部分电压之和：U = U₁ + U₂，变形得 U₂ = U − U₁。这里的 U 是电源两端的电压，U₁ 是同一时刻 L1 两端的电压。"},{"type":"list","title":"解答步骤","items":["判断电路结构：L1、L2 串联，电源电压由两只灯泡分担。","写出关系式 U = U₁ + U₂ 并变形。","代入：U₂ = 6 V − 2.5 V = 3.5 V。","检验：2.5 V + 3.5 V = 6 V，与电源电压一致。","答：L2 两端的电压为 3.5 V。"]},{"type":"figure","figure":{"id":"fig-elec-voltage-2","title":"串联电路：电源电压被两灯分担","caption":"U = U₁ + U₂，已知 U 与 U₁ 就能求 U₂","view":"wide","alt":"两只灯泡串联接在电源上，标注电源电压与两只灯泡两端的电压，总电压等于两部分电压之和","prims":[{"t":"line","x1":18,"y1":16,"x2":22,"y2":16},{"t":"line","x1":33,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":27.4,"y2":48},{"t":"line","x1":44.6,"y1":48,"x2":55.4,"y2":48},{"t":"line","x1":72.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":26,"y":16,"label":"电源 U = 6 V"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"bulb","x":36,"y":48,"label":"L1"},{"t":"bulb","x":64,"y":48,"label":"L2"},{"t":"text","x":36,"y":34,"text":"U₁ = 2.5 V","size":3.8,"tone":"accent"},{"t":"text","x":64,"y":34,"text":"U₂ = ?","size":3.8,"tone":"accent"}]}},{"type":"note","title":"结论","text":"U₂ = 3.5 V。"},{"type":"h","text":"应用 · 滑动变阻器怎样让灯泡变暗"},{"type":"note","title":"情境","text":"台灯上的旋钮能连续调节亮度。台灯内部是灯泡与滑动变阻器串联，转动旋钮就是移动滑片。"},{"type":"note","title":"模型与思路","text":"滑动变阻器接入电路的是滑片到所接下接线柱之间的那一段电阻丝。滑片移动使这段变长，接入电阻 R 变大，由 I = U/R 可知电流变小，灯泡的实际功率变小、亮度变暗。"},{"type":"list","title":"解答步骤","items":["确认变阻器的接法是一上一下，找到所接的下接线柱。","滑片远离该下接线柱时，接入的电阻丝变长，接入电阻变大。","电源电压不变，由 I = U/R 得电路中电流变小。","灯泡变暗，说明实际功率变小；滑片反向移动则变亮。"]},{"type":"note","title":"结论","text":"移动滑片改变了接入电路的电阻，从而连续改变电流，实现调光。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["电压表要串联在电路中，电流表要并联在被测元件两端","电压表并联在被测元件两端，电流表串联在被测电路中","电压表的电阻极大，串联进电路后整个电路的电流几乎为零，用电器都不能工作；而电压表并联在谁两端，测的就是谁的电压。电流表恰好相反，它的电阻极小，必须串联。"],["导体的电阻跟它两端的电压成正比，跟通过它的电流成反比","电阻是导体本身的性质，由材料、长度、横截面积和温度决定，与电压、电流无关","R = U/I 只是「用电压与电流的比值来计算电阻」的式子。对同一段导体，电压变大时电流按同样比例变大，比值不变，所以电阻不变；说「电阻与电压成正比」把因果关系搞反了。"],["滑动变阻器接上面两个接线柱或下面两个接线柱，同样能改变电阻","滑动变阻器必须「一上一下」接入，接成两上或两下时移动滑片电阻不变","接两个上接线柱时，电流只经过金属棒，电阻几乎为零且不随滑片移动改变；接两个下接线柱时，电流经过全部电阻丝，电阻最大且同样不变。只有一上一下，滑片才真正「取」出一段电阻丝接入电路。"],["串联电路中各用电器两端的电压一定相等","串联电路中电流处处相等、电压按电阻分配，不一定相等；并联时各支路电压才一定相等","两只不同规格的灯泡串联时，两端电压并不相同，U = U₁ + U₂ 只说「加起来等于总电压」。要判断「一定相等」，得看它们是不是并联。"]]},{"type":"table","title":"串联与并联的电压关系（同一个电源、同样两只灯泡的两种接法）","head":["比较项","串联","并联"],"rows":[["电压关系","总电压等于各部分电压之和：U = U₁ + U₂","各支路两端电压相等：U = U₁ = U₂"],["各元件电压","一般不相同，与各自电阻有关","一定相同，都等于电源电压"],["测量方法","电压表分别并联在各元件两端与电源两端","电压表并联在任一支路两端或电源两端，读数相同"],["生活对应","节日小彩灯常串联，坏一个全灭","家用电器并联，各用 220 V、互不影响"]]},{"type":"table","title":"滑动变阻器的正确与错误接法（接线柱的选择决定了滑片是否起作用）","head":["比较项","一上一下（正确）","两上或两下（错误）"],"rows":[["滑片的作用","接入电路的电阻丝长度随滑片移动而改变","接入的电阻丝长度不变，移动滑片电阻不变"],["电阻变化","滑片远离所接的下接线柱时电阻变大","电阻始终保持不变（两上约为零，两下为最大）"],["对电路的影响","可以连续改变电流与电压","不能调节，电路状态不随滑片变化"],["连接前的要求","闭合开关前把滑片调到接入电阻最大处","无法起到保护电路的作用"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["电压表的读数与接法判断","给出电路图与表盘，判断电压表测的是哪一部分的电压并读数。易错点：并联在电源两端时测的是电源电压；「0～3 V」与「0～15 V」两个量程读数混淆。"],["探究串联电路的电压规律","用电压表分别测量各元件两端与电源两端的电压，归纳 U = U₁ + U₂。评分点包括电压表并联接入、量程与「+」接线柱、换用不同规格灯泡多次实验。"],["影响电阻大小的因素","以「探究影响导体电阻大小的因素」为情境，考控制变量的选择（选哪两根导线）、转换法的使用（用电流表示数或灯泡亮度比较电阻），以及结论的正确表述。"],["滑动变阻器的作用与接法","判断滑片移动时接入电阻的变化、电流与电压的变化；也考「闭合开关前滑片应放在阻值最大处」的操作要求与变阻器在实验中的双重作用。"]]},{"type":"quote","text":"【材料】小明想探究影响导体电阻大小的因素。实验桌上备有四种导线：A 是长 1 m、横截面积 1 mm² 的镍铬合金线；B 是长 0.5 m、横截面积 1 mm² 的镍铬合金线；C 是长 1 m、横截面积 0.5 mm² 的镍铬合金线；D 是长 1 m、横截面积 1 mm² 的锰铜线。他把导线依次接入同一个电路（电源电压不变，电路中串联一只电流表），通过比较电流表的示数来比较电阻的大小。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】要探究电阻与导体长度的关系，应选择哪两根导线？请说明选择的依据。（3 分）","【设问】把导线 C 接入电路时，电流表的示数比接入 A 时更小。由此能得到什么结论？请说明理由。（3 分）","【设问】要探究电阻与导体材料的关系，应选择哪两根导线？本实验用电流表的示数来比较电阻的大小，这种研究方法叫什么？（4 分）"]}],"questions":[{"id":"phy-electric-4-q1","type":"choice","stem":"如图，灯泡 L1 与 L2 串联，电压表并联在 L1 两端。闭合开关后电压表的读数为 2 V。下列说法正确的是","answer":"A","explain":"电压表并联在谁的两端，测的就是谁的电压；图中电压表的两根导线分别接在 L1 的两端，所以读数是 L1 两端的电压，A 正确。B 错：要测 L2 的电压，应把电压表并联在 L2 两端。C 错：要测电源电压，应把电压表并联在电源两端。D 错：电压表必须并联使用，它的电阻极大，串联进电路会使电流几乎为零，用电器都不能工作。","options":["L1 两端的电压为 2 V","L2 两端的电压为 2 V","电源两端的电压为 2 V","电压表的接法错误，它应该串联在电路中"],"difficulty":1,"tags":["电压表接法"],"figure":{"id":"fig-elec-voltage-3","title":"判断电压表测哪一部分的电压","caption":"看电压表的两根导线接在谁的两端","view":"wide","alt":"两只灯泡串联，电压表的两根导线接在灯泡 L1 的两端，与 L1 并联","prims":[{"t":"line","x1":18,"y1":16,"x2":26,"y2":16},{"t":"line","x1":37,"y1":16,"x2":84,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":46},{"t":"line","x1":84,"y1":16,"x2":84,"y2":46},{"t":"line","x1":18,"y1":46,"x2":27.4,"y2":46},{"t":"line","x1":44.6,"y1":46,"x2":55.4,"y2":46},{"t":"line","x1":72.6,"y1":46,"x2":84,"y2":46},{"t":"battery","x":30,"y":16,"label":"电源"},{"t":"bulb","x":36,"y":46,"label":"L1"},{"t":"bulb","x":64,"y":46,"label":"L2"},{"t":"line","x1":27.4,"y1":46,"x2":27.4,"y2":32},{"t":"line","x1":44.6,"y1":46,"x2":44.6,"y2":32},{"t":"meter","x":36,"y":32,"kind":"V"},{"t":"junction","x":27.4,"y":46},{"t":"junction","x":44.6,"y":46}]}},{"id":"phy-electric-4-q2","type":"choice","stem":"关于导体的电阻，下列说法正确的是","answer":"D","explain":"电阻是导体本身的性质，由材料、长度、横截面积和温度共同决定，D 正确。A、B 错：电压与电流是外加条件，对同一段导体，电压改变时电流按比例改变，电阻不变。C 错：在材料、横截面积相同时，导体越长电阻越大，而不是越小；判断长度的影响必须先说明另外两个因素相同。","options":["导体两端的电压越大，它的电阻就越大","通过导体的电流越大，它的电阻就越小","导体越长，它的电阻一定越小","导体的电阻由材料、长度、横截面积和温度决定，与电压、电流无关"],"difficulty":1,"tags":["电阻影响因素"]},{"id":"phy-electric-4-q3","type":"choice","stem":"某滑动变阻器接入电路时，使用了一个上面的接线柱和一个下面的接线柱。若把滑片向远离所接的下接线柱的方向移动，则接入电路的电阻和电路中的电流分别","answer":"B","explain":"滑动变阻器接入电路的是「滑片到所接下接线柱之间」的那段电阻丝。滑片远离所接的下接线柱时，这段电阻丝变长，接入电阻变大；电源电压不变，由 I = U/R 可知电路中的电流变小，所以选 B。A、C 把电阻与电流的变化方向弄反了；D 是把滑片当成了不起作用（那是接成两上或两下的情形）。","options":["变大、变大","变大、变小","变小、变大","不变、不变"],"difficulty":2,"tags":["滑动变阻器"]},{"id":"phy-electric-4-q4","type":"choice","stem":"关于串、并联电路中的电压关系，下列说法正确的是","answer":"C","explain":"并联的各支路两端都接在同两点之间，所以各支路电压相等，并等于电源电压，C 正确。A 错：串联电路中电压按电阻分配，只有两只完全相同的用电器才恰好相等，不是「一定」。B 错：串联总电压等于各部分电压之和，不是取最大值。D 错：把串联的规律套用到并联上；并联中不存在把各支路电压相加的关系。","options":["串联电路中各用电器两端的电压一定相等","串联电路的总电压等于各用电器两端电压中的最大值","并联电路各支路两端的电压相等，且等于电源两端的电压","并联电路的总电压等于各支路电压之和"],"difficulty":2,"tags":["电压规律"]},{"id":"phy-electric-4-q5","type":"fill","stem":"实验室的电压表选用 0～3 V 量程测量电压时，表盘上每一小格表示的电压值是 ______ V。","answer":"0.1|0.1V|0.1 V","explain":"分度值 = 量程 ÷ 小格数 = 3 V ÷ 30 = 0.1 V。若改用 0～15 V 量程，分度值为 15 V ÷ 30 = 0.5 V。记这类空时要先确认量程：同一只表盘上两排刻度数字，读错量程就会把结果写成 0.5 V。","difficulty":1,"tags":["电压表读数"],"figure":{"id":"fig-elec-dial-v1","title":"0～3 V 量程的分度值","caption":"0～3 V 量程把满偏分成 30 小格，分度值 3 V ÷ 30 = 0.1 V；同一只表盘改用 0～15 V 量程时变成 0.5 V","view":"square","alt":"电压表表盘，量程 0 到 3 伏，刻度数字依次为 0、1、2、3，每两个数字之间有 10 个小格，指针从中心指向 1.5 伏刻度线","prims":[{"t":"circle","cx":50,"cy":56,"r":32,"dashed":true,"tone":"muted"},{"t":"text","x":50,"y":16,"text":"电压表","size":4.6,"tone":"main"},{"t":"curve","points":[[27.48,43],[28.07,42.03],[28.7,41.09],[29.37,40.17],[30.08,39.29],[30.83,38.43],[31.62,37.62],[32.43,36.83],[33.29,36.08],[34.17,35.37],[35.09,34.7],[36.03,34.07],[37,33.48],[37.99,32.94],[39.01,32.44],[40.05,31.98],[41.11,31.57],[42.18,31.2],[43.27,30.89],[44.37,30.62],[45.49,30.39],[46.61,30.22],[47.73,30.1],[48.87,30.02],[50,30],[51.13,30.02],[52.27,30.1],[53.39,30.22],[54.51,30.39],[55.63,30.62],[56.73,30.89],[57.82,31.2],[58.89,31.57],[59.95,31.98],[60.99,32.44],[62.01,32.94],[63,33.48],[63.97,34.07],[64.91,34.7],[65.83,35.37],[66.71,36.08],[67.57,36.83],[68.38,37.62],[69.17,38.43],[69.92,39.29],[70.63,40.17],[71.3,41.09],[71.93,42.03],[72.52,43]],"tone":"main","width":0.5},{"t":"line","x1":27.48,"y1":43,"x2":30.77,"y2":44.9,"tone":"main","width":0.5},{"t":"text","x":33.89,"y":46.7,"text":"0","size":3.4,"tone":"muted"},{"t":"line","x1":28.45,"y1":41.46,"x2":30.1,"y2":42.58,"tone":"main","width":0.28},{"t":"line","x1":29.51,"y1":39.99,"x2":31.09,"y2":41.22,"tone":"main","width":0.28},{"t":"line","x1":30.68,"y1":38.6,"x2":32.16,"y2":39.94,"tone":"main","width":0.28},{"t":"line","x1":31.94,"y1":37.3,"x2":33.33,"y2":38.74,"tone":"main","width":0.28},{"t":"line","x1":33.29,"y1":36.08,"x2":34.57,"y2":37.61,"tone":"main","width":0.28},{"t":"line","x1":34.72,"y1":34.97,"x2":35.89,"y2":36.58,"tone":"main","width":0.28},{"t":"line","x1":36.22,"y1":33.95,"x2":37.28,"y2":35.65,"tone":"main","width":0.28},{"t":"line","x1":37.79,"y1":33.04,"x2":38.73,"y2":34.81,"tone":"main","width":0.28},{"t":"line","x1":39.42,"y1":32.25,"x2":40.24,"y2":34.07,"tone":"main","width":0.28},{"t":"line","x1":41.11,"y1":31.57,"x2":42.41,"y2":35.14,"tone":"main","width":0.5},{"t":"text","x":43.64,"y":38.52,"text":"1","size":3.4,"tone":"muted"},{"t":"line","x1":42.83,"y1":31.01,"x2":43.38,"y2":32.93,"tone":"main","width":0.28},{"t":"line","x1":44.59,"y1":30.57,"x2":45.01,"y2":32.52,"tone":"main","width":0.28},{"t":"line","x1":46.38,"y1":30.25,"x2":46.66,"y2":32.23,"tone":"main","width":0.28},{"t":"line","x1":48.19,"y1":30.06,"x2":48.33,"y2":32.06,"tone":"main","width":0.28},{"t":"line","x1":50,"y1":30,"x2":50,"y2":32,"tone":"main","width":0.28},{"t":"line","x1":51.81,"y1":30.06,"x2":51.67,"y2":32.06,"tone":"main","width":0.28},{"t":"line","x1":53.62,"y1":30.25,"x2":53.34,"y2":32.23,"tone":"main","width":0.28},{"t":"line","x1":55.41,"y1":30.57,"x2":54.99,"y2":32.52,"tone":"main","width":0.28},{"t":"line","x1":57.17,"y1":31.01,"x2":56.62,"y2":32.93,"tone":"main","width":0.28},{"t":"line","x1":58.89,"y1":31.57,"x2":57.59,"y2":35.14,"tone":"main","width":0.5},{"t":"text","x":56.36,"y":38.52,"text":"2","size":3.4,"tone":"muted"},{"t":"line","x1":60.58,"y1":32.25,"x2":59.76,"y2":34.07,"tone":"main","width":0.28},{"t":"line","x1":62.21,"y1":33.04,"x2":61.27,"y2":34.81,"tone":"main","width":0.28},{"t":"line","x1":63.78,"y1":33.95,"x2":62.72,"y2":35.65,"tone":"main","width":0.28},{"t":"line","x1":65.28,"y1":34.97,"x2":64.11,"y2":36.58,"tone":"main","width":0.28},{"t":"line","x1":66.71,"y1":36.08,"x2":65.43,"y2":37.61,"tone":"main","width":0.28},{"t":"line","x1":68.06,"y1":37.3,"x2":66.67,"y2":38.74,"tone":"main","width":0.28},{"t":"line","x1":69.32,"y1":38.6,"x2":67.84,"y2":39.94,"tone":"main","width":0.28},{"t":"line","x1":70.49,"y1":39.99,"x2":68.91,"y2":41.22,"tone":"main","width":0.28},{"t":"line","x1":71.55,"y1":41.46,"x2":69.9,"y2":42.58,"tone":"main","width":0.28},{"t":"line","x1":72.52,"y1":43,"x2":69.23,"y2":44.9,"tone":"main","width":0.5},{"t":"text","x":66.11,"y":46.7,"text":"3","size":3.4,"tone":"muted"},{"t":"line","x1":50,"y1":59.64,"x2":50,"y2":33.2,"tone":"danger","width":0.7},{"t":"circle","cx":50,"cy":56,"r":1.5,"fill":true,"tone":"main"},{"t":"text","x":50,"y":92,"text":"满偏 30 小格：分度值 = 3 V ÷ 30 = 0.1 V","size":3.8,"tone":"muted"}]}},{"id":"phy-electric-4-q6","type":"short","stem":"在由灯泡 L1、L2 串联组成的电路中，电源电压为 6 V。闭合开关后测得 L1 两端的电压为 2.5 V。求：（1）L2 两端的电压；（2）若通过 L1 的电流为 0.25 A，通电 4 min 通过 L1 的电荷量。","answer":"（1）U₂ = U − U₁ = 6 V − 2.5 V = 3.5 V；（2）t = 4 min = 240 s，Q = It = 0.25 A × 240 s = 60 C。","explain":"为什么这么做：串联电路的电源电压等于各部分电压之和，所以 L2 的电压等于总电压减去 L1 的电压；电荷量要用电流与通电时间的乘积。两处常见错误：一是把 6 V 当成 L2 的电压（忽略了「分压」）；二是把 4 min 直接代入公式而忘记换成 240 s。算完可用 2.5 V + 3.5 V = 6 V 检验第（1）问。","difficulty":2,"tags":["串联电压规律","计算"],"rubric":["写出串联电压规律并变形（1 分）","第（1）问结果 3.5 V（1 分）","时间换算 240 s 正确（1 分）","第（2）问结果 60 C，单位正确（1 分）"],"steps":["（1）由串联电路电压规律 U = U₁ + U₂ 得 U₂ = U − U₁。","代入：U₂ = 6 V − 2.5 V = 3.5 V。","（2）时间换算：t = 4 min = 240 s。","由 I = Q/t 得 Q = It = 0.25 A × 240 s = 60 C。","答：L2 两端的电压为 3.5 V；4 min 内通过 L1 的电荷量为 60 C。"]},{"id":"phy-electric-4-q7","type":"short","stem":"请设计实验探究串联电路中总电压与各部分电压的关系。写出器材、实验步骤、需要记录的数据，以及为了得出普遍规律应采取的措施。","answer":"器材：电源、两只规格不同的小灯泡、开关、电压表、导线若干。步骤：(1) 按串联连接 L1、L2，把电压表并联在 L1 两端（注意量程与「+」接线柱），闭合开关读出 U₁，断开开关；(2) 把电压表改接到 L2 两端，读出 U₂；(3) 再把电压表并联在电源两端，读出总电压 U；(4) 比较 U 与 U₁ + U₂ 的关系。记录数据：U₁/V、U₂/V、U/V，并计算 U₁ + U₂。为得出普遍规律，应换用不同规格的灯泡（或改变电源电压）重复实验多次，避免只测一组数据出现偶然结果。结论：串联电路中总电压等于各部分电压之和，即 U = U₁ + U₂。","explain":"实验设计的关键：电压表必须并联在被测元件两端，改接前先断开开关；每次读数都要先确认量程与分度值。只测一组数据不能说明规律普遍成立，必须换用不同规格的灯泡多次测量——若两只灯泡规格相同，电压恰好相等，容易误以为「串联电压一定相等」。若测得 U 与 U₁ + U₂ 略有差异，那是读数误差造成的，属于正常现象，但不能把差异说成规律。","difficulty":3,"tags":["实验探究","电压规律"],"rubric":["器材完整：电源、两只规格不同的灯泡、开关、电压表、导线（1 分）","电压表分别并联在 L1、L2 和电源两端测量，改接前断开开关（1 分）","记录 U₁、U₂、U 并计算 U₁ + U₂ 进行比较（1 分）","换用不同规格灯泡多次实验，说明是为了得出普遍规律（1 分）"]},{"id":"phy-electric-4-q8","type":"short","stem":"请画出符合要求的电路图：灯泡 L 与滑动变阻器串联，电源和开关 S 接在电路中，用电压表测量滑动变阻器两端的电压。","answer":"见参考答案图：电源、开关、滑动变阻器与灯泡依次串联成回路（变阻器一上一下接入），电压表并联在滑动变阻器两端。","explain":"作图要点：要测变阻器两端的电压，电压表就必须并联在变阻器的两个接线端之间；变阻器本身按「一上一下」接入电路。常见错误：把电压表画成与灯泡并联（测的就成了灯泡的电压）；把电压表串联在电路中（电路几乎无电流）；把变阻器画成两上或两下的接法（滑片不起作用）。","difficulty":3,"tags":["电路作图","电压表接法"],"rubric":["电源、开关、滑动变阻器与灯泡依次串联成一条回路（1 分）","滑动变阻器按「一上一下」接入两个接线柱（1 分）","电压表并联在滑动变阻器两端，没有串联进电路（1 分）"],"answerFigure":{"id":"fig-elec-draw-4-ans","title":"参考答案：电压表并联在滑动变阻器两端","caption":"电压表并联在谁两端，就测谁的电压","view":"wide","alt":"电源、开关、滑动变阻器与灯泡串联成回路，电压表并联在滑动变阻器的两端","prims":[{"t":"line","x1":18,"y1":16,"x2":22,"y2":16},{"t":"line","x1":33,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":20,"y2":48},{"t":"line","x1":44,"y1":48,"x2":56.4,"y2":48},{"t":"line","x1":73.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":26,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"rheostat","x":32,"y":48,"label":"滑动变阻器"},{"t":"bulb","x":65,"y":48,"label":"L"},{"t":"line","x1":20,"y1":48,"x2":20,"y2":32},{"t":"line","x1":20,"y1":32,"x2":23.4,"y2":32},{"t":"line","x1":40.6,"y1":32,"x2":44,"y2":32},{"t":"line","x1":44,"y1":32,"x2":44,"y2":48},{"t":"meter","x":32,"y":32,"kind":"V","label":"测变阻器电压"},{"t":"junction","x":20,"y":48},{"t":"junction","x":44,"y":48}]}},{"id":"phy-electric-4-q9","type":"short","stem":"某小灯泡正常发光时两端的电压为 2.5 V，通过灯丝的电流为 0.2 A。（1）求此时灯丝的电阻；（2）若把它接到电压为 2 V 的电源上（设灯丝电阻不变），通过灯丝的电流是多少？","answer":"（1）R = U/I = 2.5 V ÷ 0.2 A = 12.5 Ω；（2）I′ = U′/R = 2 V ÷ 12.5 Ω = 0.16 A。","explain":"为什么这么做：由欧姆定律 I = U/R 变形得 R = U/I。这里必须遵守同一性与同时性：2.5 V 与 0.2 A 是同一时刻、同一段灯丝上的电压和电流，才能算出这段灯丝的电阻；第（2）问换用 2 V 的电压后，电流要用新的电压与同一个电阻重新计算，不能把 2.5 V 和 2 V 混用，也不能把原有电流直接照搬。判断电阻不变的前提是题目明确说明「设灯丝电阻不变」，实际灯丝的电阻会随温度变化。","difficulty":2,"tags":["欧姆定律","计算"],"rubric":["写出欧姆定律的变形式 R = U/I（1 分）","第（1）问结果 12.5 Ω（1 分）","第（2）问明确电阻不变、用新电压重新计算（1 分）","第（2）问结果 0.16 A，单位正确（1 分）"],"steps":["（1）写出欧姆定律的变形式 R = U/I。","代入同一时刻同一灯丝的数据：R = 2.5 V ÷ 0.2 A = 12.5 Ω。","（2）电阻不变，仍为 12.5 Ω。","由 I = U/R 得 I′ = 2 V ÷ 12.5 Ω = 0.16 A。","答：灯丝电阻为 12.5 Ω；接到 2 V 电源上时通过灯丝的电流为 0.16 A。"]},{"id":"phy-electric-4-m1-q1","type":"short","stem":"要探究电阻与导体长度的关系，应选择哪两根导线？请说明选择的依据。（3 分）","answer":"选择 A 和 B。探究长度的影响时必须控制其它因素相同：A、B 都是镍铬合金线，横截面积都是 1 mm²，只有长度不同（1 m 与 0.5 m），这样测得的电阻差异才能归因于长度。","explain":"","tags":["控制变量法","电阻影响因素"],"rubric":["选出 A 和 B（1 分）","指出两者材料相同、横截面积相同（1 分）","说明只改变长度、属于控制变量法（1 分）"]},{"id":"phy-electric-4-m1-q2","type":"short","stem":"把导线 C 接入电路时，电流表的示数比接入 A 时更小。由此能得到什么结论？请说明理由。（3 分）","answer":"在材料、长度相同时，横截面积越小电阻越大。理由：电源电压相同，电流表示数更小说明电路中的电流更小，由 I = U/R 可知接入电路的电阻更大；而 C 与 A 相比只是横截面积更小（0.5 mm² 比 1 mm² 小），所以电阻变大是由横截面积变小引起的。","explain":"","tags":["转换法","电阻影响因素"],"rubric":["结论：材料、长度相同时，横截面积越小电阻越大（2 分）","说明依据：电压相同时电流小则电阻大（1 分）"]},{"id":"phy-electric-4-m1-q3","type":"short","stem":"要探究电阻与导体材料的关系，应选择哪两根导线？本实验用电流表的示数来比较电阻的大小，这种研究方法叫什么？（4 分）","answer":"选择 A 和 D：两者长度（1 m）与横截面积（1 mm²）都相同，只有材料不同（镍铬合金与锰铜）。用电流表的示数（或灯泡的亮度）间接反映电阻的大小，这种研究方法叫转换法；在此基础上每次只改变一个因素，是控制变量法。","explain":"","tags":["转换法","科学方法"],"rubric":["选出 A 和 D（1 分）","说明两者长度、横截面积相同，材料不同（1 分）","答出转换法（1 分）","答出控制变量法（1 分）"]}]},{"id":"phy-electric-5","title":"欧姆定律：同一段导体上的电流、电压与电阻","subtitle":"人教版九年级 · 第 17 章 欧姆定律 · 9a","grade":"9a","tags":["人教版九年级 · 第 17 章 欧姆定律"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 17 章 欧姆定律 · 9a"},{"type":"note","title":"问题切入","text":"电流的大小究竟由什么决定？为什么说电压是「原因」、电阻是「阻碍」？同一个电阻接在不同电压下，电流怎样变化？为什么滑动变阻器的滑片一动，电压表的读数也跟着变？"},{"type":"note","title":"一句话抓住关键","text":"对同一段导体（同一时刻），通过它的电流跟它两端的电压成正比、跟它的电阻成反比，即 I = U/R。用这个式子时，U、I、R 必须属于同一段导体、同一时刻——这就是同一性与同时性；动态电路就靠它一步一步推。"},{"type":"h","text":"先看现象：电压越大，电流越大，图像是一条过原点的直线"},{"type":"p","text":"把一段定值电阻接在可调电源上，逐渐升高电压，同时读出电流：电压变为原来的 2 倍，电流也约变为 2 倍。以电流 I 为横轴、电压 U 为纵轴把数据画成图像，得到的是一条过原点的直线——这说明在电阻不变时，导体中的电流跟它两端的电压成正比。"},{"type":"figure","figure":{"id":"fig-elec-ohm-1","title":"电阻不变时，U 与 I 成正比的图像","caption":"横轴是电流、纵轴是电压，直线过原点说明 U 与 I 成正比","view":"square","alt":"以电流为横轴、电压为纵轴的坐标图，一条从原点出发的倾斜直线，表示电压与电流成正比","prims":[{"t":"axis","x":20,"y":80,"w":70,"h":60,"xLabel":"I/A","yLabel":"U/V","origin":true,"grid":true,"xTicks":[{"at":0.5,"label":"0.2"},{"at":1,"label":"0.4"}],"yTicks":[{"at":0.5,"label":"2"},{"at":1,"label":"4"}]},{"t":"curve","points":[[20,80],[55,50],[90,20]],"tone":"accent"},{"t":"text","x":62,"y":92,"text":"直线过原点：U 与 I 成正比","size":3.8,"tone":"muted"},{"t":"text","x":72,"y":36,"text":"R = 10 Ω","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"图像的斜率就是电阻：过原点的直线越陡，表示同一电流下需要的电压越大，电阻越大。"},{"type":"h","text":"控制变量：保持电压不变，看电流与电阻的关系"},{"type":"p","text":"研究电流跟电阻的关系时，必须让电阻两端的电压保持不变，只改变电阻。做法是：在电路中串联一个滑动变阻器，每换一次定值电阻，就调节滑片使电压表的读数回到原来的数值。实验结果是：电压不变时，电阻变为原来的 2 倍，电流约变为原来的一半，即电流跟电阻成反比。"},{"type":"figure","figure":{"id":"fig-elec-ohm-2","title":"探究电流与电阻关系的电路","caption":"电流表串联测电流，电压表并联在定值电阻两端，滑动变阻器保持电压不变","view":"wide","alt":"电源、开关、电流表、滑动变阻器与定值电阻串联成回路，电压表并联在定值电阻两端，滑动变阻器一上一下接入","prims":[{"t":"line","x1":15,"y1":14,"x2":20,"y2":14},{"t":"line","x1":31,"y1":14,"x2":38,"y2":14},{"t":"line","x1":50,"y1":14,"x2":59.4,"y2":14},{"t":"line","x1":76.6,"y1":14,"x2":84,"y2":14},{"t":"line","x1":15,"y1":14,"x2":15,"y2":48},{"t":"line","x1":84,"y1":14,"x2":84,"y2":48},{"t":"line","x1":37,"y1":48,"x2":50,"y2":48},{"t":"line","x1":74,"y1":48,"x2":84,"y2":48},{"t":"battery","x":24,"y":14,"label":"电源"},{"t":"switch","x":44,"y":14,"closed":true,"label":"S"},{"t":"meter","x":68,"y":14,"kind":"A","label":"电流表"},{"t":"resistor","x":26,"y":48,"label":"定值电阻 R"},{"t":"rheostat","x":62,"y":48,"label":"滑动变阻器"},{"t":"line","x1":15,"y1":48,"x2":15,"y2":30},{"t":"line","x1":15,"y1":30,"x2":17.4,"y2":30},{"t":"line","x1":34.6,"y1":30,"x2":37,"y2":30},{"t":"line","x1":37,"y1":30,"x2":37,"y2":48},{"t":"meter","x":26,"y":30,"kind":"V","label":"电压表"},{"t":"junction","x":15,"y":30},{"t":"junction","x":37,"y":48},{"t":"text","x":30,"y":58,"text":"换用不同电阻，调节滑片使电压表示数不变","anchor":"start","size":3.8,"tone":"muted"}]}},{"type":"note","title":"","text":"滑动变阻器在这里有两个作用：一是保护电路（闭合开关前调到阻值最大处）；二是改变自身电阻，从而改变电流、把定值电阻两端的电压调回设定值。"},{"type":"h","text":"建立关系：同一条式子里的三个量必须「配套」"},{"type":"p","text":"把两条实验结果合起来，就得到欧姆定律：导体中的电流，跟导体两端的电压成正比，跟导体的电阻成反比，写成 I = U/R。用它的纪律只有两条，但丢分几乎都出在这两条上：同一性——式中的 U、I、R 必须是同一段导体（或同一个元件）的三个量；同时性——必须是同一时刻的数值。所以在电路图上做题，第一步永远是标清「这个电压是加在谁两端的」、「这个电流是流经谁的」。"},{"type":"figure","figure":{"id":"fig-elec-ohm-3","title":"同一段导体的 U、I、R","caption":"电流表测通过 R 的电流，电压表测 R 两端的电压，两者与 R 配套","view":"wide","alt":"电源、开关、电流表与定值电阻串联，电压表并联在定值电阻两端，标注出同一段导体的电流、电压与电阻","prims":[{"t":"line","x1":18,"y1":16,"x2":26,"y2":16},{"t":"line","x1":37,"y1":16,"x2":40.4,"y2":16},{"t":"line","x1":57.6,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":39,"y2":48},{"t":"line","x1":61,"y1":48,"x2":82,"y2":48},{"t":"battery","x":30,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"meter","x":49,"y":16,"kind":"A","label":"测通过 R 的电流"},{"t":"resistor","x":50,"y":48,"label":"R"},{"t":"line","x1":39,"y1":48,"x2":39,"y2":32},{"t":"line","x1":39,"y1":32,"x2":41.4,"y2":32},{"t":"line","x1":58.6,"y1":32,"x2":61,"y2":32},{"t":"line","x1":61,"y1":32,"x2":61,"y2":48},{"t":"meter","x":50,"y":32,"kind":"V","label":"测 R 两端的电压"},{"t":"junction","x":39,"y":48},{"t":"junction","x":61,"y":48},{"t":"text","x":50,"y":58,"text":"对 R：I = U/R（同一段导体、同一时刻）","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"典型错法：把电源电压当成某个电阻两端的电压，或者用灯泡的电流去配滑动变阻器的电压，都属于破坏「同一性」。"},{"type":"h","text":"换个情境再想一遍：滑片一动，读数怎么变"},{"type":"p","text":"动态电路题只需四步：一看电路结构（谁是串联、谁是并联）；二看哪个量不变（通常是电源电压与定值电阻）；三看滑动变阻器的电阻怎么变；四用 I = U/R 与串联电压规律逐步推。例如定值电阻 R0 与变阻器串联，滑片使接入电阻变大：总电阻变大 → 总电流变小 → R0 两端电压 U0 = IR0 变小 → 变阻器两端电压 U变 = U − U0 变大。"},{"type":"figure","figure":{"id":"fig-elec-ohm-4","title":"动态电路：滑片移动引起读数变化","caption":"R0 与变阻器串联，电流表测总电流，电压表测变阻器两端电压","view":"wide","alt":"电源、开关、电流表、定值电阻 R0 与滑动变阻器串联成回路，电压表并联在滑动变阻器两端，用于分析滑片移动时的读数变化","prims":[{"t":"line","x1":15,"y1":14,"x2":22,"y2":14},{"t":"line","x1":33,"y1":14,"x2":42,"y2":14},{"t":"line","x1":54,"y1":14,"x2":59.4,"y2":14},{"t":"line","x1":76.6,"y1":14,"x2":84,"y2":14},{"t":"line","x1":15,"y1":14,"x2":15,"y2":48},{"t":"line","x1":84,"y1":14,"x2":84,"y2":48},{"t":"line","x1":37,"y1":48,"x2":50,"y2":48},{"t":"line","x1":74,"y1":48,"x2":84,"y2":48},{"t":"battery","x":26,"y":14,"label":"电源"},{"t":"switch","x":48,"y":14,"closed":true,"label":"S"},{"t":"meter","x":68,"y":14,"kind":"A","label":"电流表"},{"t":"resistor","x":26,"y":48,"label":"定值电阻 R0"},{"t":"rheostat","x":62,"y":48,"label":"滑动变阻器"},{"t":"line","x1":50,"y1":48,"x2":50,"y2":32},{"t":"line","x1":50,"y1":32,"x2":53.4,"y2":32},{"t":"line","x1":70.6,"y1":32,"x2":74,"y2":32},{"t":"line","x1":74,"y1":32,"x2":74,"y2":48},{"t":"meter","x":62,"y":32,"kind":"V","label":"测变阻器电压"},{"t":"junction","x":50,"y":48},{"t":"junction","x":74,"y":48}]}},{"type":"note","title":"","text":"推理要「一环扣一环」地写：电阻变→总电阻变→电流变→各元件电压变。只写结论不写链条，解答题会丢分。"},{"type":"h","text":"图像法再确认：谁更「陡」，谁电阻更大"},{"type":"p","text":"把两只电阻的 U-I 图像画在同一坐标系里：R₁ = 5 Ω、R₂ = 10 Ω。因为 U = IR，同一个电流下 R₂ 两端的电压是 R₁ 的两倍，所以 R₂ 的直线更陡。用图像比电阻大小时，要分清坐标轴——纵轴是电压 U、横轴是电流 I 时，直线的斜率就是电阻，越陡电阻越大；如果反过来把电流画在纵轴上，斜率是 1/R，越陡反而电阻越小。"},{"type":"figure","figure":{"id":"fig-elec-ohm-5","title":"两只电阻的 U-I 图像比较","caption":"纵轴为 U、横轴为 I，直线越陡表示电阻越大","view":"square","alt":"以电流为横轴、电压为纵轴的坐标系中有两条过原点的直线，R2 的直线比 R1 更陡，表示 R2 的电阻更大","prims":[{"t":"axis","x":20,"y":80,"w":70,"h":60,"xLabel":"I/A","yLabel":"U/V","origin":true,"grid":true,"xTicks":[{"at":0.5,"label":"0.3"},{"at":1,"label":"0.6"}],"yTicks":[{"at":0.5,"label":"3"},{"at":1,"label":"6"}]},{"t":"curve","points":[[20,80],[90,50]],"tone":"accent"},{"t":"curve","points":[[20,80],[90,20]],"tone":"danger"},{"t":"text","x":64,"y":72,"text":"R₁ = 5 Ω","size":3.8,"tone":"accent"},{"t":"text","x":58,"y":34,"text":"R₂ = 10 Ω","size":3.8,"tone":"danger"}]}},{"type":"note","title":"","text":"同一条直线上的任意一点，U/I 的比值都相同——这正是「电阻不变」在图像上的表现。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["欧姆定律","I = (U)/(R)","I：电流，安培（A）；U：电压，伏特（V）；R：电阻，欧姆（Ω） · 同一性：式中的 U、I、R 必须属于同一段导体或同一个元件——不能把电源电压配某个用电器的电流、也不能把滑动变阻器的电阻配灯泡的电压。同时性：三个量必须是同一时刻的值，滑片移动、开关状态改变后要重新判断，不能把变化前后的数据混用。适用条件是「同一段导体、温度一定」，初中范围内一般按电阻不变处理；已知 U、R 求 I 直接用本式。"],["欧姆定律的变形（求电压）","U = IR","U：电压，伏特（V）；I：电流，安培（A）；R：电阻，欧姆（Ω） · 已知同一段导体的电流与电阻求它两端的电压时使用，串联动向分析里用它判断「电流变小则定值电阻两端的电压变小」。变形只是数学上的移项，物理含义不变，同样必须满足同一性与同时性。"],["欧姆定律的变形（求电阻）","R = (U)/(I)","R：电阻，欧姆（Ω）；U：电压，伏特（V）；I：电流，安培（A） · 这是「伏安法」测电阻的计算式：用电压表和电流表测出同一段导体在同一时刻的 U 与 I，再求比值。要注意 R = U/I 是计算式而不是决定式——不能说「电阻与电压成正比、与电流成反比」，因为对同一段导体，U 与 I 的比值恒定，电阻由材料、长度、横截面积和温度决定。"],["串联电路的总电阻（定性判断）","R = R₁ + R₂","R、R₁、R₂：电阻，欧姆（Ω） · 用于串联电路的等效与定性分析：串联总电阻一定大于其中任何一个电阻，所以在电源电压不变时，滑片使变阻器接入电阻变大，电路总电阻变大、电流变小。本式只适用于串联；并联总电阻比任一支路电阻都小，不能直接用这个式子相加。"]]},{"type":"h","text":"应用 · 用欧姆定律求电流，再检验单位"},{"type":"note","title":"情境","text":"某定值电阻为 20 Ω，接在电压为 6 V 的电源上。求通过它的电流。"},{"type":"note","title":"模型与思路","text":"已知同一段导体的电压与电阻，用 I = U/R 求电流。U 用伏特（V）、R 用欧姆（Ω），算出的 I 单位就是安培（A）。"},{"type":"list","title":"解答步骤","items":["明确 U、R 属于同一段导体：U = 6 V，R = 20 Ω。","写出公式 I = U/R。","代入：I = 6 V ÷ 20 Ω = 0.3 A。","换算：0.3 A = 300 mA。","答：通过它的电流为 0.3 A。"]},{"type":"figure","figure":{"id":"fig-elec-ohm-6","title":"已知电压与电阻求电流","caption":"20 Ω 的电阻接在 6 V 电源上，电流表读数应为 0.3 A","view":"wide","alt":"电源、开关、电流表与 20 欧的定值电阻串联成回路，电流表串联在电路中测量电流","prims":[{"t":"line","x1":18,"y1":16,"x2":26,"y2":16},{"t":"line","x1":37,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":21.4,"y2":48},{"t":"line","x1":38.6,"y1":48,"x2":44,"y2":48},{"t":"line","x1":66,"y1":48,"x2":82,"y2":48},{"t":"battery","x":30,"y":16,"label":"电源 6 V"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"meter","x":30,"y":48,"kind":"A","label":"电流表"},{"t":"resistor","x":55,"y":48,"label":"R = 20 Ω"}]}},{"type":"note","title":"结论","text":"I = 0.3 A。"},{"type":"h","text":"应用 · 由电流与电压反求电阻"},{"type":"note","title":"情境","text":"某段导体两端的电压为 4.5 V 时，通过它的电流为 0.3 A。求这段导体的电阻，并说明把它接到 3 V 电源上时电流是多少。"},{"type":"note","title":"模型与思路","text":"由 I = U/R 变形得 R = U/I，用同一时刻的电压与电流求出电阻；电阻是导体本身的性质，不随电压改变，所以第二种情况下仍用同一个 R 求电流。"},{"type":"list","title":"解答步骤","items":["写变形公式 R = U/I。","代入同一段导体的数据：R = 4.5 V ÷ 0.3 A = 15 Ω。","R 不变，仍为 15 Ω。","由 I = U/R 得新的电流 I′ = 3 V ÷ 15 Ω = 0.2 A。","答：这段导体的电阻为 15 Ω；接在 3 V 电源上时电流为 0.2 A。"]},{"type":"note","title":"结论","text":"R = 15 Ω；接到 3 V 上时 I′ = 0.2 A。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["用 I = U/R 时，公式里的 U 可以用电源电压，I 用某个用电器的电流","I、U、R 必须属于同一段导体、同一时刻，不能跨元件搭配","欧姆定律描述的是「同一段导体」上三个量的关系。把电源电压配某个灯泡的电流，等于把两个不同对象的量塞进一个式子，结果一定是错的——串联电路中电源电压等于各部分电压之和，并不等于某个元件两端的电压。"],["导体的电阻与电压成正比、与电流成反比，所以电压越大电阻越大","电阻由导体本身（材料、长度、横截面积、温度）决定，R = U/I 只是它的计算式","对同一段导体，电压增大时电流按比例增大，U/I 的比值恒定不变，这说明电阻没有改变。把「计算式」当成「决定式」是这一章最典型的错误。"],["滑动变阻器的阻值变大，它两端的电压一定变小","在串联电路中，变阻器接入电阻变大时，它分得的电压反而变大","变阻器电阻变大使总电阻变大、电流变小，定值电阻两端电压 U₀ = IR₀ 变小；由串联分压 U变 = U − U₀ 可知，变阻器两端的电压变大。要按「电阻变→电流变→电压变」的顺序推，不能凭直觉猜。"],["灯泡两端的电压变大，它的电阻一定不变","灯丝电阻会随温度升高而变大，所以灯泡的 U 与 I 不成严格的正比","大多数金属导体的电阻随温度升高而增大，灯泡工作时灯丝温度极高，电阻明显变大，它的 U-I 图像会向电流轴微微弯曲。只有在题目说明「设灯丝电阻不变」或研究定值电阻时，才能按正比处理。"]]},{"type":"table","title":"两种常见图像：U-I 图与 I-U 图（同样是「直线」，斜率的意义不同）","head":["比较项","U-I 图（纵轴 U）","I-U 图（纵轴 I）"],"rows":[["直线斜率","斜率等于电阻 R","斜率等于 1/R"],["判断电阻大小","直线越陡，电阻越大","直线越陡，电阻越小"],["物理含义","同一电流下电压越大，说明导体对电流的阻碍越大","同一电压下电流越小，说明导体对电流的阻碍越大"],["读图要点","先看清纵轴标的是哪个量，再取点计算","先看清纵轴标的是哪个量，再取点计算"]]},{"type":"table","title":"欧姆定律的三种用法（同一个式子的三种变形，对应三类已知条件）","head":["比较项","I = U/R","U = IR 与 R = U/I"],"rows":[["已知条件","已知电压与电阻","已知电流与电阻，或已知电压与电流"],["典型场景","求电路中的电流、判断电流变化","求某元件两端电压、测未知电阻"],["常见错误","把电源电压与某元件的电阻搭配","用不同时刻或不同元件的 U、I 求 R"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["图像分析求电阻","给出 U-I（或 I-U）图像，取点计算电阻、比较两只电阻的大小。评分点在于是否看清坐标轴、是否用同一点对应的 U 与 I 求比值；若图像弯曲，还要说明电阻随温度变化。"],["动态电路定性分析","以滑动变阻器滑片移动为情境，判断电流表与电压表读数的变化。要求写出「电阻变→总电阻变→电流变→各元件电压变」的推理链，而不是只给结论。"],["串并联中的欧姆定律计算","综合电流规律、电压规律与欧姆定律求解串联分压、并联分流问题。失分点通常是同一段导体的 U、I、R 不配套，或把串联当并联处理。"],["探究电流与电压、电阻的关系","实验题问控制变量如何实现（用滑动变阻器保持电压不变）、滑片该往哪边调、数据表格如何设计，以及由数据得出「电压不变时电流与电阻成反比」的结论。"]]},{"type":"quote","text":"【材料】小明用电源、开关、电流表、电压表、滑动变阻器和一段电阻丝连接电路，探究通过电阻丝的电流与它两端电压的关系，记录的实验数据如下：\n电压 U/V 依次为 0.5、1.0、1.5、2.0、2.5；对应的电流 I/A 依次为 0.10、0.20、0.30、0.40、0.50。\n他根据这组数据画出了 U-I 图像，得到的是一条过原点的直线。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】根据数据求出这段电阻丝的电阻，并说明为什么它的 U-I 图像是一条过原点的直线。（3 分）","【设问】实验中为什么要在电路里串联一个滑动变阻器？（3 分）","【设问】若换用一段阻值更大的电阻丝重新实验（仍保持电源电压不变），请说明新的 U-I 直线与原来直线的位置关系，并写出判断依据。（4 分）"]}],"questions":[{"id":"phy-electric-5-q1","type":"choice","stem":"某段导体两端的电压 U 与通过它的电流 I 的关系如图所示。下列说法正确的是","answer":"B","explain":"图中纵轴是电压、横轴是电流，取直线上的点（I = 0.2 A，U = 4 V），由 R = U/I 得 R = 4 V ÷ 0.2 A = 20 Ω，B 正确。A 错：0.05 Ω 是把比值算反了（用 I/U 计算）。C 错：电阻由导体本身决定，与它两端有没有电压无关，电压为零时电阻仍为 20 Ω。D 错：图像是一条过原点的直线，恰恰说明在电阻不变时电流与电压成正比。","options":["该导体的电阻为 0.05 Ω","该导体的电阻为 20 Ω","当它两端的电压为 0 时，它的电阻也是 0","图线说明通过导体的电流与它两端的电压不成正比"],"difficulty":2,"tags":["欧姆定律","图像"],"figure":{"id":"fig-elec-ohm-7","title":"某导体的 U-I 图像","caption":"纵轴为电压、横轴为电流，直线经过 (0.2 A, 4 V)","view":"square","alt":"以电流为横轴、电压为纵轴的坐标图，一条过原点的直线经过电流 0.2 安、电压 4 伏处","prims":[{"t":"axis","x":20,"y":80,"w":70,"h":60,"xLabel":"I/A","yLabel":"U/V","origin":true,"grid":true,"xTicks":[{"at":0.5,"label":"0.2"},{"at":1,"label":"0.4"}],"yTicks":[{"at":0.5,"label":"4"},{"at":1,"label":"8"}]},{"t":"curve","points":[[20,80],[55,50],[90,20]],"tone":"accent"},{"t":"circle","cx":55,"cy":50,"r":1.6,"fill":true,"tone":"danger"}]}},{"id":"phy-electric-5-q2","type":"choice","stem":"关于欧姆定律 I = U/R 的使用，下列说法正确的是","answer":"C","explain":"欧姆定律的同一性与同时性是使用前提，C 正确。A 错：把电源电压与某个用电器的电流搭配，是两个不同对象的数据，代入后得到的既不是那段导体的电阻，也没有物理意义。B 错：R 由导体本身决定，U/I 只是计算电阻的方法。D 错：只有在同一段导体、同一时刻的前提下三个量才能互相推算，否则第二个量就不知道属于谁。","options":["式中的 U 可以用电源电压，I 用任意一个用电器的电流","式中的 R 与 U 成正比、与 I 成反比","式中的 U、I、R 必须是同一段导体在同一时刻的三个量","只要把任意两个量代入，就一定能求出第三个量"],"difficulty":2,"tags":["欧姆定律","同一性"]},{"id":"phy-electric-5-q3","type":"choice","stem":"定值电阻 R0 与滑动变阻器串联接在电压不变的电源上，电流表测电路中的电流，电压表并联在 R0 两端。当滑片向使变阻器接入电阻变大的方向移动时","answer":"D","explain":"推理链：变阻器接入电阻变大 → 串联总电阻变大 → 电源电压不变，由 I = U/R 得电流变小，所以电流表读数变小 → R0 两端的电压 U0 = IR0，R0 不变而 I 变小，所以电压表读数变小，选 D。A、B 把电流的变化方向弄反；C 是「电压表测变阻器两端电压」时的结果（此时变阻器电压变大），读数对象搞错就会选错。","options":["电流表的读数变大，电压表的读数变大","电流表的读数变大，电压表的读数变小","电流表的读数变小，电压表的读数变大","电流表的读数变小，电压表的读数变小"],"difficulty":3,"tags":["动态电路"],"figure":{"id":"fig-elec-ohm-slide","title":"滑片移动时电流表与电压表的读数变化","caption":"R0 与滑动变阻器串联：滑片使接入电阻变大，总电阻变大、电流变小；R0 两端电压 U0 = IR0 也随之变小","view":"wide","alt":"电源、开关、电流表、定值电阻 R0 与滑动变阻器串联成回路，电压表并联在定值电阻 R0 两端","prims":[{"t":"line","x1":15,"y1":14,"x2":20,"y2":14},{"t":"line","x1":31,"y1":14,"x2":38,"y2":14},{"t":"line","x1":50,"y1":14,"x2":59.4,"y2":14},{"t":"line","x1":76.6,"y1":14,"x2":84,"y2":14},{"t":"line","x1":15,"y1":14,"x2":15,"y2":48},{"t":"line","x1":84,"y1":14,"x2":84,"y2":48},{"t":"line","x1":37,"y1":48,"x2":50,"y2":48},{"t":"line","x1":74,"y1":48,"x2":84,"y2":48},{"t":"battery","x":24,"y":14,"label":"电源"},{"t":"switch","x":44,"y":14,"closed":true,"label":"S"},{"t":"meter","x":68,"y":14,"kind":"A","label":"电流表 A"},{"t":"resistor","x":26,"y":48,"label":"定值电阻 R0"},{"t":"rheostat","x":62,"y":48,"label":"滑动变阻器"},{"t":"line","x1":15,"y1":48,"x2":15,"y2":30},{"t":"line","x1":15,"y1":30,"x2":17.4,"y2":30},{"t":"line","x1":34.6,"y1":30,"x2":37,"y2":30},{"t":"line","x1":37,"y1":30,"x2":37,"y2":48},{"t":"meter","x":26,"y":30,"kind":"V","label":"电压表 V"},{"t":"junction","x":15,"y":30},{"t":"junction","x":37,"y":48},{"t":"text","x":50,"y":58,"text":"滑片使接入电阻变大 → 电流变小 → U0 = I R0 变小","size":3.6,"tone":"accent"}]}},{"id":"phy-electric-5-q4","type":"choice","stem":"电阻 R1 = 10 Ω 与 R2 = 20 Ω 串联后接在电压为 6 V 的电源上。下列说法正确的是","answer":"A","explain":"串联总电阻 R = 10 Ω + 20 Ω = 30 Ω，总电流 I = U/R = 6 V ÷ 30 Ω = 0.2 A；串联各处电流相等，所以通过 R1、R2 的电流都是 0.2 A，A 正确。B 错：串联是分压不是均分，U1 = IR1 = 0.2 A × 10 Ω = 2 V，U2 = IR2 = 0.2 A × 20 Ω = 4 V，并不相等。C 错：R2 两端电压是 4 V 而不是 2 V（电阻大的分得电压多）。D 错：串联电路电流处处相等。","options":["通过它们的电流相等，都是 0.2 A","它们两端的电压相等，都是 3 V","R2 两端的电压为 2 V","通过 R1 的电流大于通过 R2 的电流"],"difficulty":2,"tags":["串联","欧姆定律计算"]},{"id":"phy-electric-5-q5","type":"fill","stem":"某导体两端的电压为 3 V 时，通过它的电流为 0.3 A，该导体的电阻是 ______ Ω。","answer":"10|10Ω|10 Ω","explain":"由 R = U/I 得 R = 3 V ÷ 0.3 A = 10 Ω。两个易错点：一是把比值算反（写成 0.1 Ω），二是以为「电压变为 6 V 时电阻变成 20 Ω」——电阻是导体本身的性质，不会随电压改变，电压变为 6 V 时电流变为 0.6 A，电阻仍是 10 Ω。","difficulty":1,"tags":["欧姆定律计算"]},{"id":"phy-electric-5-q6","type":"short","stem":"电源电压保持 6 V 不变，定值电阻 R1 = 10 Ω 与一只最大阻值为 20 Ω 的滑动变阻器串联。求：（1）滑片调到使变阻器接入电阻最大时，电路中的电流；（2）当电流表的读数为 0.3 A 时，变阻器接入电路的电阻。","answer":"（1）R总 = 10 Ω + 20 Ω = 30 Ω，I = U/R总 = 6 V ÷ 30 Ω = 0.2 A；（2）R总′ = U/I′ = 6 V ÷ 0.3 A = 20 Ω，变阻器接入电阻 R变 = 20 Ω − 10 Ω = 10 Ω。","explain":"为什么这么做：串联电路的总电阻等于各电阻之和，用 I = U/R 求电流时，R 必须是「同一段电路」的总电阻——即电源电压对应的那段电路（R1 与变阻器的串联整体），这就是同一性。第（2）问先由 U 与 I′ 求出此时的总电阻，再减去定值电阻，得到变阻器接入的电阻；这里 0.3 A 是变化之后的电流，必须与同一个电源电压 6 V 配套使用，不能与滑片在最大阻值时的 0.2 A 混用（同时性）。","difficulty":3,"tags":["欧姆定律计算","滑动变阻器"],"rubric":["第（1）问先求总电阻再求电流（1 分）","第（1）问结果 0.2 A（1 分）","第（2）问由 R总′ = U/I′ 求出总电阻 20 Ω（1 分）","第（2）问结果 10 Ω 并写单位（1 分）"],"steps":["（1）串联总电阻 R总 = R1 + R变 = 10 Ω + 20 Ω = 30 Ω。","由 I = U/R 得 I = 6 V ÷ 30 Ω = 0.2 A。","（2）电流为 0.3 A 时，总电阻 R总′ = U/I′ = 6 V ÷ 0.3 A = 20 Ω。","变阻器接入电阻 R变 = R总′ − R1 = 20 Ω − 10 Ω = 10 Ω。","答：滑片在最大阻值处时电流为 0.2 A；电流为 0.3 A 时变阻器接入电阻为 10 Ω。"],"figure":{"id":"fig-elec-ohm-r1","title":"定值电阻与滑动变阻器串联","caption":"电源电压 6 V 加在「R1 与变阻器」这段串联电路两端，求电流时必须用总电阻","view":"wide","alt":"电源、开关、电流表、定值电阻 R1 与滑动变阻器依次串联成回路","prims":[{"t":"line","x1":15,"y1":16,"x2":20,"y2":16},{"t":"line","x1":31,"y1":16,"x2":38,"y2":16},{"t":"line","x1":50,"y1":16,"x2":59.4,"y2":16},{"t":"line","x1":76.6,"y1":16,"x2":84,"y2":16},{"t":"line","x1":15,"y1":16,"x2":15,"y2":48},{"t":"line","x1":84,"y1":16,"x2":84,"y2":48},{"t":"line","x1":37,"y1":48,"x2":50,"y2":48},{"t":"line","x1":74,"y1":48,"x2":84,"y2":48},{"t":"battery","x":24,"y":16,"label":"电源 6 V"},{"t":"switch","x":44,"y":16,"closed":true,"label":"S"},{"t":"meter","x":68,"y":16,"kind":"A","label":"电流表"},{"t":"resistor","x":26,"y":48,"label":"R1 = 10 Ω"},{"t":"rheostat","x":62,"y":48,"label":"滑动变阻器（最大 20 Ω）"},{"t":"text","x":50,"y":58,"text":"I = U /（R1 + R变）：R变 随滑片位置改变","size":3.6,"tone":"accent"}]}},{"id":"phy-electric-5-q7","type":"short","stem":"请设计实验探究「电阻一定时，通过导体的电流与它两端电压的关系」。写出器材、实验步骤、需要记录的数据，并说明如何用滑动变阻器实现多次测量。","answer":"器材：电源、开关、定值电阻、滑动变阻器、电流表、电压表、导线若干。步骤：(1) 按图连接电路：电流表串联在电路中，电压表并联在定值电阻两端，滑动变阻器一上一下接入并调到阻值最大处；(2) 闭合开关，调节滑片使电压表示数为某个值（如 1.0 V），读出电流表示数并记录；(3) 再次调节滑片，使电压表示数分别为 1.5 V、2.0 V、2.5 V 等，各读一次电流并记录；(4) 以电流 I 为横轴、电压 U 为纵轴描点作图，看图像是否是一条过原点的直线，从而得出结论。记录的数据：电压 U/V、电流 I/A（至少 4～5 组）。滑动变阻器的作用：通过改变接入电路的电阻来改变定值电阻两端的电压与电流，从而实现多次测量；同时起到保护电路的作用。结论：电阻一定时，通过导体的电流与它两端的电压成正比。","explain":"实验成败的关键有四点：一是电表的接法（电流表串联、电压表并联在被测电阻两端）与量程选择；二是必须保持电阻不变，只改变电压，属于控制变量；三是每次读数都要让电路稳定，不要把滑片调得太快使指针剧烈摆动；四是只测一组数据不能说明「成正比」，必须多测几组并作图。若图像不过原点，通常是因为电压表或电流表使用前没有调零、或读数时视线倾斜造成误差，而不是规律有问题。","difficulty":3,"tags":["实验探究","欧姆定律"],"rubric":["器材完整：电源、开关、定值电阻、滑动变阻器、电流表、电压表、导线（1 分）","电表接法正确：电流表串联、电压表并联在定值电阻两端（1 分）","用滑动变阻器改变电压，记录多组 U 与 I 的数据（1 分）","由图像或数据得出「电阻一定时电流与电压成正比」的结论（1 分）"],"figure":{"id":"fig-elec-ohm-plan","title":"探究电流与电压关系的电路设计","caption":"电流表串联测通过 R 的电流，电压表并联在 R 两端测它的电压，滑动变阻器用来改变 R 两端的电压并保护电路","view":"wide","alt":"电源、开关、电流表、被测电阻 R 与滑动变阻器串联成回路，电压表并联在被测电阻 R 两端","prims":[{"t":"line","x1":15,"y1":14,"x2":20,"y2":14},{"t":"line","x1":31,"y1":14,"x2":38,"y2":14},{"t":"line","x1":50,"y1":14,"x2":59.4,"y2":14},{"t":"line","x1":76.6,"y1":14,"x2":84,"y2":14},{"t":"line","x1":15,"y1":14,"x2":15,"y2":48},{"t":"line","x1":84,"y1":14,"x2":84,"y2":48},{"t":"line","x1":37,"y1":48,"x2":50,"y2":48},{"t":"line","x1":74,"y1":48,"x2":84,"y2":48},{"t":"battery","x":24,"y":14,"label":"电源"},{"t":"switch","x":44,"y":14,"closed":true,"label":"S"},{"t":"meter","x":68,"y":14,"kind":"A","label":"电流表"},{"t":"resistor","x":26,"y":48,"label":"被测电阻 R（不变）"},{"t":"rheostat","x":62,"y":48,"label":"滑动变阻器"},{"t":"line","x1":15,"y1":48,"x2":15,"y2":30},{"t":"line","x1":15,"y1":30,"x2":17.4,"y2":30},{"t":"line","x1":34.6,"y1":30,"x2":37,"y2":30},{"t":"line","x1":37,"y1":30,"x2":37,"y2":48},{"t":"meter","x":26,"y":30,"kind":"V","label":"电压表"},{"t":"junction","x":15,"y":30},{"t":"junction","x":37,"y":48},{"t":"text","x":50,"y":58,"text":"调节滑片取得多组 (U, I) 数据，再作 U-I 图像","size":3.6,"tone":"muted"}]}},{"id":"phy-electric-5-q8","type":"short","stem":"请画出符合要求的电路图：电源、开关、电流表、定值电阻 R、滑动变阻器串联，电压表并联在 R 两端，用于探究通过 R 的电流与它两端电压的关系。","answer":"见参考答案图：电流表串联在电路中，电压表并联在定值电阻 R 两端，滑动变阻器「一上一下」接入并与 R 串联。","explain":"作图要点：探究电流与电压的关系时，必须保持 R 不变，用变阻器改变 R 两端的电压，因此变阻器与 R 串联；电流表串联在电路中测通过 R 的电流；电压表并联在 R 两端测 R 的电压。常见错误：电压表并联在变阻器两端或电源两端（测的就不是 R 的电压）；电流表并在 R 两端（会把 R 短路）；变阻器接成两上或两下（移动滑片时电压无法调节）。","difficulty":3,"tags":["电路作图","实验电路"],"rubric":["定值电阻 R 与滑动变阻器串联，电源与开关接在电路中（1 分）","电流表串联在电路中，测通过 R 的电流（1 分）","电压表并联在 R 两端，滑动变阻器「一上一下」接入（1 分）"],"answerFigure":{"id":"fig-elec-draw-5-ans","title":"参考答案：探究电流与电压关系的电路","caption":"电流表串联、电压表并联在 R 两端，变阻器一上一下接入","view":"wide","alt":"电源、开关、电流表、定值电阻 R 与滑动变阻器串联成回路，电压表并联在定值电阻 R 两端","prims":[{"t":"line","x1":15,"y1":14,"x2":20,"y2":14},{"t":"line","x1":31,"y1":14,"x2":38,"y2":14},{"t":"line","x1":50,"y1":14,"x2":59.4,"y2":14},{"t":"line","x1":76.6,"y1":14,"x2":84,"y2":14},{"t":"line","x1":15,"y1":14,"x2":15,"y2":48},{"t":"line","x1":84,"y1":14,"x2":84,"y2":48},{"t":"line","x1":37,"y1":48,"x2":50,"y2":48},{"t":"line","x1":74,"y1":48,"x2":84,"y2":48},{"t":"battery","x":24,"y":14,"label":"电源"},{"t":"switch","x":44,"y":14,"closed":true,"label":"S"},{"t":"meter","x":68,"y":14,"kind":"A","label":"电流表"},{"t":"resistor","x":26,"y":48,"label":"R"},{"t":"rheostat","x":62,"y":48,"label":"滑动变阻器"},{"t":"line","x1":15,"y1":48,"x2":15,"y2":30},{"t":"line","x1":15,"y1":30,"x2":17.4,"y2":30},{"t":"line","x1":34.6,"y1":30,"x2":37,"y2":30},{"t":"line","x1":37,"y1":30,"x2":37,"y2":48},{"t":"meter","x":26,"y":30,"kind":"V","label":"电压表"},{"t":"junction","x":15,"y":30},{"t":"junction","x":37,"y":48}]}},{"id":"phy-electric-5-m1-q1","type":"short","stem":"根据数据求出这段电阻丝的电阻，并说明为什么它的 U-I 图像是一条过原点的直线。（3 分）","answer":"任取一组数据，例如 U = 1.0 V、I = 0.20 A，由 R = U/I 得 R = 1.0 V ÷ 0.20 A = 5 Ω；用其它各组数据计算，比值也都是 5 Ω，说明电阻不变。因为电阻不变时 U 与 I 成正比，所以图像是一条过原点的直线。","explain":"","tags":["欧姆定律","图像"],"rubric":["取同一组数据的 U 与 I 求比值（1 分）","算出 R = 5 Ω 并写单位（1 分）","说明电阻不变时 U 与 I 成正比，故图像过原点（1 分）"],"figure":{"id":"fig-elec-ui-line","title":"电阻一定时 U-I 图像是过原点的直线","caption":"R = U/I：直线上任意一点的电压与电流之比都相同，所以图线的斜率就是这段电阻丝的电阻","view":"square","alt":"以电流为横轴、电压为纵轴的坐标系中，一条直线从原点出发向右上方延伸，图线上标出一个数据点","prims":[{"t":"axis","x":24,"y":54,"w":58,"h":42,"xLabel":"I/A","yLabel":"U/V","origin":true,"grid":true,"xTicks":[{"at":0.25,"label":"0.1"},{"at":0.5,"label":"0.2"},{"at":0.75,"label":"0.3"}],"yTicks":[{"at":0.25,"label":"1"},{"at":0.5,"label":"2"},{"at":0.75,"label":"3"}]},{"t":"curve","points":[[24,54],[80,10]],"tone":"accent","width":1},{"t":"dot","x":38.5,"y":39,"tone":"danger"},{"t":"text","x":42,"y":36,"text":"U 与 I 之比 = R（不变）","size":3.6,"tone":"accent","anchor":"start"},{"t":"text","x":50,"y":66,"text":"图线过原点：U 与 I 成正比","size":3.8,"tone":"muted"}]}},{"id":"phy-electric-5-m1-q2","type":"short","stem":"实验中为什么要在电路里串联一个滑动变阻器？（3 分）","answer":"一是改变电阻丝两端的电压（同时改变通过的电流），从而获得多组数据，找出普遍规律；二是保护电路，闭合开关前把滑片调到接入电阻最大处，避免电流过大损坏电表或电阻丝。","explain":"","tags":["滑动变阻器","实验探究"],"rubric":["答出调节电阻丝两端的电压（或电流），以便多次测量（2 分）","答出保护电路的作用（1 分）"]},{"id":"phy-electric-5-m1-q3","type":"short","stem":"若换用一段阻值更大的电阻丝重新实验（仍保持电源电压不变），请说明新的 U-I 直线与原来直线的位置关系，并写出判断依据。（4 分）","answer":"新的直线比原来的更陡（在原直线的上方）：因为 U = IR，在相同的电流下，电阻越大所需的电压越大；也就是在同一电压下，电阻越大电流越小。判断依据：U-I 图中直线的斜率等于电阻，电阻变大则直线变陡。","explain":"","tags":["图像","欧姆定律"],"rubric":["答出新的直线更陡（或位于原直线上方）（2 分）","用 U = IR 说明相同电流下电压更大（1 分）","指出斜率等于电阻，故电阻大则直线陡（1 分）"]}]},{"id":"phy-electric-6","title":"伏安法测电阻：电路设计、数据处理与图像","subtitle":"人教版九年级 · 第 17 章 欧姆定律 · 9a","grade":"9a","tags":["人教版九年级 · 第 17 章 欧姆定律"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 17 章 欧姆定律 · 9a"},{"type":"note","title":"问题切入","text":"怎样才能测出一只未知电阻的阻值？为什么必须同时用电流表和电压表？滑动变阻器在实验里到底起什么作用？为什么测小灯泡时，几次算出的电阻值都不一样？"},{"type":"note","title":"一句话抓住关键","text":"伏安法：用电压表测出被测电阻两端的电压 U，用电流表测出通过它的电流 I，再由 R = U/I 算出电阻，这两个量必须属于同一段电阻、同一时刻。滑动变阻器用来改变电流和电压、获得多组数据，同时起保护电路的作用；定值电阻可以求平均值，小灯泡的电阻随温度变化，不能求平均值。"},{"type":"h","text":"先看现象：一只表测不出电阻，两只表配合才行"},{"type":"p","text":"电阻看不见，但可以由电压与电流算出来。所以要把待测电阻 Rx 接在电路中，串联一只电流表测通过它的电流，并联一只电压表测它两端的电压，再串联一个滑动变阻器用来改变电流与电压。连接时的三条纪律：开关必须断开；滑动变阻器的滑片先调到接入电阻最大处；两只表都要先选好量程（估计不出时用大量程试触）。"},{"type":"figure","figure":{"id":"fig-elec-vamethod-1","title":"伏安法测电阻的电路（开关断开、滑片在最大阻值处）","caption":"接线完成、检查无误后才能闭合开关","view":"wide","alt":"电源、开关、电流表、滑动变阻器与待测电阻串联成回路，电压表并联在待测电阻两端，此时开关处于断开状态","prims":[{"t":"line","x1":15,"y1":14,"x2":20,"y2":14},{"t":"line","x1":31,"y1":14,"x2":38,"y2":14},{"t":"line","x1":50,"y1":14,"x2":59.4,"y2":14},{"t":"line","x1":76.6,"y1":14,"x2":84,"y2":14},{"t":"line","x1":15,"y1":14,"x2":15,"y2":48},{"t":"line","x1":84,"y1":14,"x2":84,"y2":48},{"t":"line","x1":37,"y1":48,"x2":50,"y2":48},{"t":"line","x1":74,"y1":48,"x2":84,"y2":48},{"t":"battery","x":24,"y":14,"label":"电源"},{"t":"switch","x":44,"y":14,"closed":false,"label":"S"},{"t":"meter","x":68,"y":14,"kind":"A","label":"电流表"},{"t":"resistor","x":26,"y":48,"label":"待测电阻 Rx"},{"t":"rheostat","x":62,"y":48,"label":"滑动变阻器"},{"t":"line","x1":15,"y1":48,"x2":15,"y2":30},{"t":"line","x1":15,"y1":30,"x2":17.4,"y2":30},{"t":"line","x1":34.6,"y1":30,"x2":37,"y2":30},{"t":"line","x1":37,"y1":30,"x2":37,"y2":48},{"t":"meter","x":26,"y":30,"kind":"V","label":"电压表"},{"t":"junction","x":15,"y":30},{"t":"junction","x":37,"y":48},{"t":"text","x":30,"y":58,"text":"接线时开关断开，滑片先调到阻值最大处","anchor":"start","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"滑动变阻器接成「一上一下」；若接成两下，滑片就不能调节，闭合开关时电流还可能过大。"},{"type":"h","text":"抓住哪个量：两表的接法不能互换"},{"type":"p","text":"电流表必须串联在被测电阻所在的路径中，电压表必须并联在待测电阻两端。若把电流表并联在 Rx 两端，Rx 会被短路、电流几乎全部从电流表通过，指针打到满偏甚至烧坏表；若把电压表串联在电路中，由于它电阻极大，电路中的电流几乎为零，电流表没有示数、Rx 也不工作。所以判断接法时问自己一句：这只表是「串进去了」还是「并在两端」？"},{"type":"figure","figure":{"id":"fig-elec-vamethod-2","title":"错误接法：电流表并联在待测电阻两端","caption":"电流表电阻极小，并联后 Rx 被短路，指针会打到满偏","view":"wide","alt":"电源、开关与待测电阻串联，电流表却并联在待测电阻两端，虚线框标出这一错误接法","prims":[{"t":"line","x1":18,"y1":16,"x2":26,"y2":16},{"t":"line","x1":37,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":39,"y2":48},{"t":"line","x1":61,"y1":48,"x2":82,"y2":48},{"t":"battery","x":30,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"resistor","x":50,"y":48,"label":"Rx"},{"t":"line","x1":39,"y1":48,"x2":39,"y2":32},{"t":"line","x1":39,"y1":32,"x2":41.4,"y2":32},{"t":"line","x1":58.6,"y1":32,"x2":61,"y2":32},{"t":"line","x1":61,"y1":32,"x2":61,"y2":48},{"t":"meter","x":50,"y":32,"kind":"A","label":"电流表（接错）"},{"t":"junction","x":39,"y":48},{"t":"junction","x":61,"y":48},{"t":"rect","x":36,"y":23,"w":28,"h":17,"dashed":true,"tone":"danger"},{"t":"text","x":50,"y":58,"text":"错误：电流表并联在 Rx 两端","size":3.8,"tone":"danger"}]}},{"type":"note","title":"","text":"把电流表并联在用电器两端，等于给用电器并联了一根导线：用电器不工作，电流表还可能被烧坏。"},{"type":"h","text":"建立关系：多测几组数据，用图像求出电阻"},{"type":"p","text":"测出一组数据就能算出电阻，但一组数据不够可靠。做法是移动滑动变阻器的滑片，测出 3～5 组电压与电流，再分别用 R = U/I 计算，或把数据画成 U-I 图像：过原点的直线的斜率就是电阻，用图像求电阻可以减小个别读数误差的影响。定值电阻的阻值基本不变，还可以把几次算出的结果取平均值。"},{"type":"figure","figure":{"id":"fig-elec-vamethod-3","title":"由多组数据作 U-I 图像求电阻","caption":"三个数据点都落在同一条过原点的直线上，斜率为 5 Ω","view":"square","alt":"以电流为横轴、电压为纵轴的坐标图，三个测量点落在一条过原点的直线上，直线斜率表示电阻为 5 欧","prims":[{"t":"axis","x":20,"y":80,"w":70,"h":60,"xLabel":"I/A","yLabel":"U/V","origin":true,"grid":true,"xTicks":[{"at":0.5,"label":"0.3"},{"at":1,"label":"0.6"}],"yTicks":[{"at":0.5,"label":"1.5"},{"at":1,"label":"3"}]},{"t":"curve","points":[[20,80],[90,20]],"tone":"accent"},{"t":"circle","cx":55,"cy":50,"r":1.6,"fill":true,"tone":"danger"},{"t":"circle","cx":66.7,"cy":40,"r":1.6,"fill":true,"tone":"danger"},{"t":"circle","cx":78.3,"cy":30,"r":1.6,"fill":true,"tone":"danger"},{"t":"text","x":50,"y":92,"text":"各点都在同一条直线上：R = U/I = 5 Ω","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"图像法的好处：个别点偏离时能一眼看出来（那是读数误差），而斜率反映的是整体趋势。"},{"type":"h","text":"换个情境：小灯泡的电阻为什么每次不同"},{"type":"p","text":"把定值电阻换成小灯泡再做一次，就会发现算出的电阻一次比一次大。原因不在读数，而在灯丝：灯丝是金属导体，电压升高时灯丝温度升高，电阻随之变大，所以它的 U-I 图像不再是直线，而是向电压轴方向弯曲的曲线——电压越高，同样的电流增量需要的电压增量越大。这说明「同一段导体」还要加上一个条件：温度一定。"},{"type":"figure","figure":{"id":"fig-elec-vamethod-4","title":"小灯泡的 U-I 曲线与定值导体的直线对比","caption":"灯丝温度升高使电阻变大，曲线向电压轴弯曲","view":"square","alt":"以电流为横轴、电压为纵轴的坐标图，实线是小灯泡的曲线，向电压轴方向弯曲；虚线是电阻不变导体的直线","prims":[{"t":"axis","x":20,"y":80,"w":70,"h":60,"xLabel":"I/A","yLabel":"U/V","origin":true,"grid":true,"xTicks":[{"at":0.5,"label":"0.2"},{"at":1,"label":"0.4"}],"yTicks":[{"at":0.5,"label":"2"},{"at":1,"label":"4"}]},{"t":"curve","points":[[20,80],[90,20]],"tone":"muted","dashed":true},{"t":"curve","points":[[20,80],[37.5,72.5],[55,62],[72.5,48.5],[90,32]],"tone":"danger"},{"t":"text","x":50,"y":92,"text":"小灯泡：灯丝温度升高，电阻变大","size":3.6,"tone":"danger"},{"t":"text","x":50,"y":97,"text":"虚线：电阻不变的导体，图像是直线","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"所以小灯泡的 U-I 图像是曲线，而「电阻不变」的导体图像才是过原点的直线；题中说「设灯丝电阻不变」时才能按直线处理。"},{"type":"h","text":"再想一遍：定值电阻求平均值，小灯泡不能"},{"type":"p","text":"同一个实验方法，两种元件的处理方式不同。定值电阻的阻值几乎不随温度变化，多次测量结果接近，差异来自读数误差，取平均值可以减小误差；小灯泡的电阻随温度（也就是随电压、电流）变化，几次测得的值本来就不同，取平均值没有物理意义。更合适的做法是分别说明各电压下的电阻，或只关心它在额定电压下工作时的电阻。"},{"type":"figure","figure":{"id":"fig-elec-vamethod-5","title":"两类元件的测量数据处理","caption":"同样的方法，不同的数据处理方式","view":"wide","alt":"左框表示定值电阻，电阻几乎不随温度变化，可以多次测量取平均值；右框表示小灯泡，灯丝电阻随温度变化，不能求平均值","prims":[{"t":"rect","x":6,"y":14,"w":40,"h":14,"rx":2,"label":"定值电阻","tone":"main"},{"t":"rect","x":54,"y":14,"w":40,"h":14,"rx":2,"label":"小灯泡","tone":"danger"},{"t":"text","x":26,"y":36,"text":"阻值几乎不随温度变化","size":3.4,"tone":"muted"},{"t":"text","x":26,"y":44,"text":"多次测量取平均值减小误差","size":3.4,"tone":"muted"},{"t":"text","x":74,"y":36,"text":"灯丝电阻随温度升高而变大","size":3.4,"tone":"muted"},{"t":"text","x":74,"y":44,"text":"不能求平均值，要分别说明","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"同一个方法，两种数据处理方式","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"写实验结论时要区分对象：定值电阻「阻值基本不变，取平均减小误差」；小灯泡「电阻随温度变化，各次结果不同」。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["伏安法测电阻的计算式","R = (U)/(I)","R：电阻，欧姆（Ω）；U：电压，伏特（V）；I：电流，安培（A） · 用电压表和电流表测出同一段电阻在同一时刻的 U 与 I，再由比值求电阻。同一性：U 必须是这段电阻两端的电压、I 必须是流过这段电阻的电流，不能取电源电压或干路电流。同时性：改接电路、移动滑片后要重新读表，不能把不同时刻的数据搭配。对定值电阻可多测几组取平均值；对小灯泡，因其电阻随温度变化，不能求平均值。"],["欧姆定律","I = (U)/(R)","I：电流，安培（A）；U：电压，伏特（V）；R：电阻，欧姆（Ω） · 用于由已知电阻与电压求电流，或反向推求元件两端的电压。使用时同样要求同一性与同时性：U、I、R 属于同一段导体、同一时刻；测电阻时用它先估计电流大小，以便选择合适的电流表量程（例如电源 6 V、待测电阻约 5 Ω，电流约 1.2 A，就应选 0～3 A 量程）。"],["多次测量取平均值","R = (R₁ + R₂ + R₃)/(3)","R、R₁、R₂、R₃：电阻，欧姆（Ω） · 只适用于阻值基本不变（如定值电阻）的情况，目的是减小读数等偶然误差。对小灯泡绝对不能这样算：灯丝电阻随温度变化，各次结果不同是物理原因造成的，平均值没有意义；此时应分别说明各电压下的电阻，或关注额定电压下的阻值。"]]},{"type":"h","text":"应用 · 由三组数据算出电阻"},{"type":"note","title":"情境","text":"某同学用伏安法测一只定值电阻，得到三组数据：U₁ = 1.5 V、I₁ = 0.30 A；U₂ = 2.0 V、I₂ = 0.40 A；U₃ = 2.5 V、I₃ = 0.50 A。"},{"type":"note","title":"模型与思路","text":"每一组数据都来自同一段电阻，用 R = U/I 分别计算，再取平均值作为测量结果；三组结果应当接近，若某组差别很大，应先检查电表读数与量程。"},{"type":"list","title":"解答步骤","items":["R₁ = U₁/I₁ = 1.5 V ÷ 0.30 A = 5 Ω。","R₂ = 2.0 V ÷ 0.40 A = 5 Ω。","R₃ = 2.5 V ÷ 0.50 A = 5 Ω。","取平均值：R = (5 Ω + 5 Ω + 5 Ω) ÷ 3 = 5 Ω。","答：被测电阻的阻值约为 5 Ω。"]},{"type":"figure","figure":{"id":"fig-elec-vamethod-6","title":"伏安法测量电路（通电测量时）","caption":"电流表串联测电流，电压表并联在 Rx 两端测电压","view":"wide","alt":"电源、开关、电流表、定值电阻 Rx 与滑动变阻器串联成回路，电压表并联在 Rx 两端，开关闭合","prims":[{"t":"line","x1":15,"y1":14,"x2":20,"y2":14},{"t":"line","x1":31,"y1":14,"x2":38,"y2":14},{"t":"line","x1":50,"y1":14,"x2":59.4,"y2":14},{"t":"line","x1":76.6,"y1":14,"x2":84,"y2":14},{"t":"line","x1":15,"y1":14,"x2":15,"y2":48},{"t":"line","x1":84,"y1":14,"x2":84,"y2":48},{"t":"line","x1":37,"y1":48,"x2":50,"y2":48},{"t":"line","x1":74,"y1":48,"x2":84,"y2":48},{"t":"battery","x":24,"y":14,"label":"电源"},{"t":"switch","x":44,"y":14,"closed":true,"label":"S"},{"t":"meter","x":68,"y":14,"kind":"A","label":"电流表"},{"t":"resistor","x":26,"y":48,"label":"Rx"},{"t":"rheostat","x":62,"y":48,"label":"滑动变阻器"},{"t":"line","x1":15,"y1":48,"x2":15,"y2":30},{"t":"line","x1":15,"y1":30,"x2":17.4,"y2":30},{"t":"line","x1":34.6,"y1":30,"x2":37,"y2":30},{"t":"line","x1":37,"y1":30,"x2":37,"y2":48},{"t":"meter","x":26,"y":30,"kind":"V","label":"电压表"},{"t":"junction","x":15,"y":30},{"t":"junction","x":37,"y":48}]}},{"type":"note","title":"结论","text":"R ≈ 5 Ω。"},{"type":"h","text":"应用 · 滑动变阻器在测电阻实验中的两个作用"},{"type":"note","title":"情境","text":"做完实验，小明被问到：这套电路里能不能去掉滑动变阻器？"},{"type":"note","title":"模型与思路","text":"不能。一是保护电路：闭合开关前把它调到接入电阻最大，限制电流，避免电表超量程或元件过热；二是改变电路中的电流与待测电阻两端的电压，获得多组数据，用图像法或求平均值减小误差。"},{"type":"list","title":"解答步骤","items":["若去掉变阻器，闭合开关后电流只由电源电压和待测电阻决定，无法调节。","只能测得一组数据，无法判断数据的可靠性。","接上变阻器后，改变接入电阻就能改变电流，从而得到多组电压与电流。","闭合开关前调到阻值最大处，起到保护电表和元件的作用。"]},{"type":"figure","figure":{"id":"fig-elec-vam-app","title":"伏安法测电阻的电路：变阻器的两个作用","caption":"一是保护电路（闭合开关前把接入电阻调到最大）；二是改变电路中的电流，从而得到多组 (U, I) 数据","view":"wide","alt":"电源、开关、电流表、被测电阻 Rx 与滑动变阻器串联成回路，电压表并联在被测电阻 Rx 两端","prims":[{"t":"line","x1":15,"y1":14,"x2":20,"y2":14},{"t":"line","x1":31,"y1":14,"x2":38,"y2":14},{"t":"line","x1":50,"y1":14,"x2":59.4,"y2":14},{"t":"line","x1":76.6,"y1":14,"x2":84,"y2":14},{"t":"line","x1":15,"y1":14,"x2":15,"y2":48},{"t":"line","x1":84,"y1":14,"x2":84,"y2":48},{"t":"line","x1":37,"y1":48,"x2":50,"y2":48},{"t":"line","x1":74,"y1":48,"x2":84,"y2":48},{"t":"battery","x":24,"y":14,"label":"电源"},{"t":"switch","x":44,"y":14,"closed":true,"label":"S"},{"t":"meter","x":68,"y":14,"kind":"A","label":"电流表"},{"t":"resistor","x":26,"y":48,"label":"被测电阻 Rx"},{"t":"rheostat","x":62,"y":48,"label":"滑动变阻器"},{"t":"line","x1":15,"y1":48,"x2":15,"y2":30},{"t":"line","x1":15,"y1":30,"x2":17.4,"y2":30},{"t":"line","x1":34.6,"y1":30,"x2":37,"y2":30},{"t":"line","x1":37,"y1":30,"x2":37,"y2":48},{"t":"meter","x":26,"y":30,"kind":"V","label":"电压表"},{"t":"junction","x":15,"y":30},{"t":"junction","x":37,"y":48},{"t":"text","x":50,"y":58,"text":"闭合开关前滑片调到阻值最大处","size":3.6,"tone":"muted"}]}},{"type":"note","title":"结论","text":"滑动变阻器既保护电路，又用来获得多组数据。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["测电阻时，把电压表并联在滑动变阻器两端也一样能算出待测电阻","电压表必须并联在待测电阻两端，测的必须是待测电阻的电压","串联电路中待测电阻与变阻器的电压并不相等，把变阻器的电压当作待测电阻的电压去算 R = U/I，破坏的是「同一性」，结果一定是错的。只有待测电阻是电路中唯一用电器时，电源电压才恰好等于它的电压。"],["小灯泡测了三次，也应该像定值电阻那样求平均值","小灯泡的灯丝电阻随温度变化，三次结果本来就不同，求平均值没有物理意义","定值电阻各次结果接近，差异是读数误差；小灯泡各次结果依次变大，是灯丝温度升高导致电阻增大的物理规律，不能当作误差平均掉。"],["连接电路时开关闭合也无所谓，反正有滑动变阻器保护","连接电路时必须断开开关，并把滑片调到接入电阻最大处，检查无误后再闭合","接线的过程中若开关闭合，手一碰到导线就可能造成局部短路或电流过大；保护电路的前提正是「先断开、先调到最大，再检查、后闭合」这个顺序。"],["测量时电流表指针偏转很小，说明电阻很大，不必换量程","指针偏转太小应换用较小的量程重新测量，这样读数更准确","量程越大分度值越大，指针偏转又小，相对误差就大。正确顺序是：先用大量程试触，再根据指针偏转情况换用合适的小量程，且必须在断开开关后再换接线柱。"]]},{"type":"table","title":"定值电阻与小灯泡的测量处理（同一个伏安法电路，两种元件的数据处理方式）","head":["比较项","定值电阻","小灯泡"],"rows":[["U-I 图像","过原点的直线","向电压轴方向弯曲的曲线"],["电阻变化","阻值基本不变","随电压（温度）升高而变大"],["数据处理","多次测量取平均值减小误差","不能求平均值，应分别说明各次结果"],["原因","差异来自读数误差","差异来自灯丝温度变化这一物理规律"]]},{"type":"table","title":"滑动变阻器在两类实验中的作用（同样都要「移动滑片」，目的不完全相同）","head":["比较项","测电阻（伏安法）","探究电流与电压的关系"],"rows":[["主要作用","改变电流与电压，获得多组数据并保护电路","改变定值电阻两端的电压，实现多次测量"],["要控制的不变量","无需控制电压，只要数据可靠","必须保持定值电阻的阻值不变"],["实验前的操作","滑片调到接入电阻最大处","滑片调到接入电阻最大处"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["实验电路的连接与故障判断","给出伏安法电路图或实物图，指出接法错误（电流表并联、电压表串联、变阻器接成两上或两下）；或由「灯泡不亮、两表均无示数」「电流表有示数而电压表无示数」等现象判断故障位置。"],["数据与图像的处理","给出一组 U、I 数据，要求算电阻、取平均值，或在坐标系中描点作出 U-I 图像并由斜率求电阻。评分点在于是否用同一组数据、是否写出单位、图像是否过原点。"],["小灯泡电阻的特殊性","解释小灯泡的 U-I 图像为什么是曲线、几次测得的电阻为什么不同，并要求说明「不能取平均值」的理由，属于实验评估类的常考问法。"],["实验方案的评价与改进","问滑动变阻器的作用、多次测量的必要性、能否用其它方法测电阻；也考「闭合开关前滑片位置」「换量程前先断开开关」等操作规范的判断。"]]},{"type":"quote","text":"【材料】小华用伏安法测量一只标有「2.5 V」字样的小灯泡的电阻。他把电源、开关、电流表、滑动变阻器和小灯泡串联，把电压表并联在小灯泡两端。闭合开关后，他移动滑片，记录了三组数据：\n第一组 U = 1.0 V、I = 0.20 A；第二组 U = 2.0 V、I = 0.32 A；第三组 U = 2.5 V、I = 0.36 A。\n用 R = U/I 计算，得到的三组电阻分别为 5.0 Ω、6.25 Ω、6.94 Ω，并不相等。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】小灯泡三次算出的电阻为什么不同？请说明理由。（3 分）","【设问】能否把这三组结果求平均值作为这只小灯泡的电阻？为什么？（3 分）","【设问】若闭合开关后小灯泡不亮、电流表无示数、电压表有示数且接近电源电压，故障可能出在哪里？写出判断依据。（4 分）"]}],"questions":[{"id":"phy-electric-6-q1","type":"choice","stem":"如图是某同学用伏安法测电阻的电路。关于它，下列说法正确的是","answer":"C","explain":"C 正确：图中电压表并联在 Rx 两端、电流表串联在电路中，由 R = U/I 即可求出 Rx。A 错：电压表接在 Rx 两端而不是变阻器两端，测的是 Rx 的电压。B 错：电流表是串联在电路中的，并没有并联。D 错：闭合开关前应把滑片调到接入电阻最大的位置，这样才能限制电流、保护电表和元件。","options":["电压表测的是滑动变阻器两端的电压","电流表并联在电路中，会把待测电阻短路","电压表并联在待测电阻两端，电流表串联在电路中，两表读数之比就是待测电阻的阻值","闭合开关前，滑动变阻器的滑片应放在接入电阻最小的位置"],"difficulty":2,"tags":["伏安法","电路识别"],"figure":{"id":"fig-elec-vamethod-7","title":"伏安法测电阻的电路","caption":"看两只表分别接在哪里","view":"wide","alt":"电源、开关、电流表、待测电阻 Rx 与滑动变阻器串联成回路，电压表并联在 Rx 两端","prims":[{"t":"line","x1":15,"y1":14,"x2":20,"y2":14},{"t":"line","x1":31,"y1":14,"x2":38,"y2":14},{"t":"line","x1":50,"y1":14,"x2":59.4,"y2":14},{"t":"line","x1":76.6,"y1":14,"x2":84,"y2":14},{"t":"line","x1":15,"y1":14,"x2":15,"y2":48},{"t":"line","x1":84,"y1":14,"x2":84,"y2":48},{"t":"line","x1":37,"y1":48,"x2":50,"y2":48},{"t":"line","x1":74,"y1":48,"x2":84,"y2":48},{"t":"battery","x":24,"y":14,"label":"电源"},{"t":"switch","x":44,"y":14,"closed":true,"label":"S"},{"t":"meter","x":68,"y":14,"kind":"A","label":"电流表"},{"t":"resistor","x":26,"y":48,"label":"Rx"},{"t":"rheostat","x":62,"y":48,"label":"滑动变阻器"},{"t":"line","x1":15,"y1":48,"x2":15,"y2":30},{"t":"line","x1":15,"y1":30,"x2":17.4,"y2":30},{"t":"line","x1":34.6,"y1":30,"x2":37,"y2":30},{"t":"line","x1":37,"y1":30,"x2":37,"y2":48},{"t":"meter","x":26,"y":30,"kind":"V","label":"电压表"},{"t":"junction","x":15,"y":30},{"t":"junction","x":37,"y":48}]}},{"id":"phy-electric-6-q2","type":"choice","stem":"用伏安法测小灯泡的电阻时，多次测量算出的电阻值一次比一次大，其原因是","answer":"A","explain":"A 正确：电压越高，灯丝中电流越大、温度越高，金属导体的电阻随温度升高而变大，所以后测得的电阻更大。B 错：这三次结果不同是物理原因造成的，不是偶然误差，取平均值没有意义。C 错：实验中电源电压由电源本身决定，不是电阻变化的原因；即使电压变化，也不会使同一温度下的电阻改变。D 错：题目没有说灯丝长度发生变化，电阻变大是温度引起的。","options":["灯丝的电阻随温度升高而变大","只是读数误差，取平均值就能消除","电源的电压在实验中变大了","灯泡的灯丝被拉长了"],"difficulty":2,"tags":["小灯泡电阻"]},{"id":"phy-electric-6-q3","type":"choice","stem":"在伏安法测电阻的实验中，下列操作正确的是","answer":"D","explain":"D 是规范操作：先断开开关接线、滑片置于阻值最大处，闭合开关后移动滑片测多组数据。A 错：接线时开关必须断开，否则手碰到导线就可能造成短路或电流过大。B 错：两表接法正好相反——电压表并联、电流表串联，接错会测不出数据甚至损坏电表。C 错：滑片不动只能得到一组数据，无法检查结果的可靠性。","options":["连接电路时开关应保持闭合，以便随时观察现象","电压表应串联在电路中，电流表应并联在待测电阻两端","为了减小误差，应把滑动变阻器的滑片固定在某一位置不动","闭合开关前把滑片调到接入电阻最大处，闭合后通过移动滑片获得多组数据"],"difficulty":1,"tags":["实验操作"]},{"id":"phy-electric-6-q4","type":"choice","stem":"某同学用伏安法测一只定值电阻，得到三组数据：(1.0 V, 0.20 A)、(2.0 V, 0.40 A)、(3.0 V, 0.60 A)。下列说法正确的是","answer":"B","explain":"三组数据中 U/I 都等于 5 Ω，说明这段导体的电阻为 5 Ω，取平均值仍是 5 Ω，B 正确。A 错：比值不变恰恰说明电阻不随电压改变，「电阻与电压成正比」是把计算式当成了决定式。C 错：三组算出的电阻相同，不存在「电压越大电阻越大」；若真出现这种情况，应检查读数或考虑元件温度变化。D 错：比值稳定正是求电阻的依据，三组数据均可使用。","options":["三次算出的电阻分别是 5 Ω、5 Ω、5 Ω，说明导体的电阻与电压成正比","三次算出的电阻都是 5 Ω，取平均值仍为 5 Ω，该电阻的阻值约为 5 Ω","电压越大算出的电阻越大，所以只能取第一次的结果","三次电流不同说明电阻不同，无法求出这个电阻"],"difficulty":2,"tags":["数据处理","伏安法"]},{"id":"phy-electric-6-q5","type":"fill","stem":"某次伏安法测电阻中，电压表的读数为 2.4 V，电流表的读数为 0.30 A，则被测电阻的阻值为 ______ Ω。","answer":"8|8 Ω|8Ω|8.0","explain":"由 R = U/I 得 R = 2.4 V ÷ 0.30 A = 8 Ω。两个易错点：一是把比值算反写成 0.125 Ω；二是把电流表的读数按 0～3 A 量程去读（若分度值看错，数据就整体差 5 倍），读数前必须先确认量程。","difficulty":1,"tags":["伏安法计算"],"figure":{"id":"fig-elec-vam-read","title":"伏安法测电阻：两个表的读数配套","caption":"电压表并联在 Rx 两端读 2.4 V，电流表串联在电路中读 0.30 A，两者必须取自同一时刻、同一段电阻","view":"wide","alt":"电源、开关、电流表、被测电阻 Rx 与滑动变阻器串联成回路，电压表并联在 Rx 两端，图上标出电压与电流的读数","prims":[{"t":"line","x1":15,"y1":14,"x2":20,"y2":14},{"t":"line","x1":31,"y1":14,"x2":38,"y2":14},{"t":"line","x1":50,"y1":14,"x2":59.4,"y2":14},{"t":"line","x1":76.6,"y1":14,"x2":84,"y2":14},{"t":"line","x1":15,"y1":14,"x2":15,"y2":48},{"t":"line","x1":84,"y1":14,"x2":84,"y2":48},{"t":"line","x1":37,"y1":48,"x2":50,"y2":48},{"t":"line","x1":74,"y1":48,"x2":84,"y2":48},{"t":"battery","x":24,"y":14,"label":"电源"},{"t":"switch","x":44,"y":14,"closed":true,"label":"S"},{"t":"meter","x":68,"y":14,"kind":"A","label":"0.30 A"},{"t":"resistor","x":26,"y":48,"label":"被测电阻 Rx"},{"t":"rheostat","x":62,"y":48,"label":"滑动变阻器"},{"t":"line","x1":15,"y1":48,"x2":15,"y2":30},{"t":"line","x1":15,"y1":30,"x2":17.4,"y2":30},{"t":"line","x1":34.6,"y1":30,"x2":37,"y2":30},{"t":"line","x1":37,"y1":30,"x2":37,"y2":48},{"t":"meter","x":26,"y":30,"kind":"V","label":"2.4 V"},{"t":"junction","x":15,"y":30},{"t":"junction","x":37,"y":48},{"t":"text","x":50,"y":58,"text":"R = U / I = 2.4 V ÷ 0.30 A","size":3.6,"tone":"accent"}]}},{"id":"phy-electric-6-q6","type":"short","stem":"用伏安法测一只定值电阻，测得三组数据：U₁ = 1.5 V、I₁ = 0.30 A；U₂ = 2.0 V、I₂ = 0.40 A；U₃ = 2.5 V、I₃ = 0.50 A。求：（1）三次测得的电阻各是多少；（2）这只电阻的测量值；（3）若把它接在电压为 4 V 的电源上，通过它的电流约为多少？","answer":"（1）R₁ = 1.5 V ÷ 0.30 A = 5 Ω，R₂ = 2.0 V ÷ 0.40 A = 5 Ω，R₃ = 2.5 V ÷ 0.50 A = 5 Ω；（2）R = (5 + 5 + 5) ÷ 3 Ω = 5 Ω；（3）I = U/R = 4 V ÷ 5 Ω = 0.8 A。","explain":"为什么这么做：每一组数据中的 U 与 I 都取自同一段电阻、同一时刻，所以 R = U/I 都有意义；三次结果相同说明数据可靠，取平均值即为测量值，这一步是减小误差而不是「取一个好看的数」。第（3）问用的是同一个电阻：电阻不随电压改变，用新的电压与同一个 R 求电流，这就是「同一性」；若把 4 V 与 0.50 A 搭配就错了。","difficulty":2,"tags":["伏安法计算","平均值"],"rubric":["三组电阻均算出 5 Ω（1 分）","写明取平均值并得出 5 Ω（1 分）","第（3）问保持电阻不变、用 4 V 与 5 Ω 配套计算（1 分）","第（3）问结果 0.8 A，单位正确（1 分）"],"steps":["（1）分别计算：R₁ = 1.5 V ÷ 0.30 A = 5 Ω；R₂ = 2.0 V ÷ 0.40 A = 5 Ω；R₃ = 2.5 V ÷ 0.50 A = 5 Ω。","（2）取平均值：R = (R₁ + R₂ + R₃)/3 = (5 Ω + 5 Ω + 5 Ω)/3 = 5 Ω。","（3）电阻不变，由 I = U/R 得 I = 4 V ÷ 5 Ω = 0.8 A。","答：三次测得的电阻都是 5 Ω；测量值为 5 Ω；接在 4 V 电源上时电流约为 0.8 A。"]},{"id":"phy-electric-6-q7","type":"short","stem":"请设计实验测量一只未知电阻 Rx 的阻值。写出实验原理、器材、实验步骤（含数据处理），并说明实验中必须注意的两条操作要求。","answer":"实验原理：R = U/I，用电压表测 Rx 两端的电压，用电流表测通过它的电流，由比值求电阻。器材：电源、开关、电流表、电压表、滑动变阻器、待测电阻 Rx、导线若干。步骤：(1) 按图连接电路，电流表串联在电路中，电压表并联在 Rx 两端，滑动变阻器一上一下接入并把滑片调到阻值最大处，连接时开关断开；(2) 检查电路无误后闭合开关，调节滑片，读取电压表与电流表的示数并记录；(3) 移动滑片再测两组数据；(4) 用 R = U/I 分别计算三次结果，取平均值作为 Rx 的阻值。注意事项：一是接线时开关断开、滑片置于接入电阻最大处，闭合开关前必须检查电路，避免短路或超量程；二是每次改接电路或更换量程都要先断开开关，读数前确认量程与分度值。","explain":"设计题的四个采分层次：原理、器材、步骤、注意点。原理要写出 R = U/I；步骤要体现「电表接法 + 变阻器保护 + 多次测量」三件事；数据处理要说清是「分别计算再取平均值」，而不是把三组电压相加、电流相加再相除（那样得到的是同一个比值，但表述不规范、一旦数据有偏就会出错）。注意点要落在安全与规范上，这恰恰是实验题的给分点。","difficulty":3,"tags":["实验探究","伏安法"],"rubric":["写出实验原理 R = U/I（1 分）","器材齐全并说明电流表串联、电压表并联在 Rx 两端（1 分）","步骤含滑片调节、多次测量与记录数据（1 分）","数据处理：分别计算 R 并取平均值（1 分）","注意点：开关断开、滑片在阻值最大处（任答一条得 1 分）"]},{"id":"phy-electric-6-q8","type":"short","stem":"请画出符合要求的电路图：电源、开关、电流表、滑动变阻器与待测电阻 Rx 串联，电压表并联在 Rx 两端。","answer":"见参考答案图：电流表串联在电路中，滑动变阻器「一上一下」接入，电压表并联在待测电阻 Rx 两端。","explain":"作图要点：判断每只表「串」还是「并」是得分关键——电流表串联在通过 Rx 的那条路径上，电压表的两端接在 Rx 的两端。常见错误：把电压表并联在滑动变阻器或电源两端（测的不是 Rx 的电压）；把电流表并联在 Rx 两端（会把 Rx 短路）；滑动变阻器画成两上或两下（滑片失去作用）。","difficulty":3,"tags":["电路作图","伏安法"],"rubric":["电源、开关、电流表、滑动变阻器与 Rx 串联成一条回路（1 分）","电流表串联接入，滑动变阻器按「一上一下」接入（1 分）","电压表并联在 Rx 两端，元件符号与导线画法规范（1 分）"],"answerFigure":{"id":"fig-elec-draw-6-ans","title":"参考答案：伏安法测电阻的电路","caption":"电流表串联、电压表并联在 Rx 两端，变阻器一上一下接入","view":"wide","alt":"电源、开关、电流表、滑动变阻器与待测电阻 Rx 串联成回路，电压表并联在 Rx 两端","prims":[{"t":"line","x1":15,"y1":14,"x2":20,"y2":14},{"t":"line","x1":31,"y1":14,"x2":41.4,"y2":14},{"t":"line","x1":58.6,"y1":14,"x2":66,"y2":14},{"t":"line","x1":78,"y1":14,"x2":85,"y2":14},{"t":"line","x1":15,"y1":14,"x2":15,"y2":48},{"t":"line","x1":85,"y1":14,"x2":85,"y2":48},{"t":"line","x1":15,"y1":48,"x2":20,"y2":48},{"t":"line","x1":44,"y1":48,"x2":53,"y2":48},{"t":"line","x1":75,"y1":48,"x2":85,"y2":48},{"t":"battery","x":24,"y":14,"label":"电源"},{"t":"meter","x":50,"y":14,"kind":"A","label":"电流表"},{"t":"switch","x":72,"y":14,"closed":true,"label":"S"},{"t":"rheostat","x":32,"y":48,"label":"滑动变阻器"},{"t":"resistor","x":64,"y":48,"label":"Rx"},{"t":"line","x1":53,"y1":48,"x2":53,"y2":32},{"t":"line","x1":53,"y1":32,"x2":55.4,"y2":32},{"t":"line","x1":72.6,"y1":32,"x2":75,"y2":32},{"t":"line","x1":75,"y1":32,"x2":75,"y2":48},{"t":"meter","x":64,"y":32,"kind":"V","label":"电压表"},{"t":"junction","x":53,"y":48},{"t":"junction","x":75,"y":48}]}},{"id":"phy-electric-6-m1-q1","type":"short","stem":"小灯泡三次算出的电阻为什么不同？请说明理由。（3 分）","answer":"灯丝是金属导体，它的电阻随温度升高而变大。电压越高，灯丝中电流越大、温度越高，电阻就越大，所以三次算出的电阻依次变大。这是物理规律造成的，不是读数误差。","explain":"","tags":["小灯泡电阻","温度影响"],"rubric":["指出灯丝电阻随温度升高而变大（2 分）","把温度升高与电压（电流）变大对应起来（1 分）"]},{"id":"phy-electric-6-m1-q2","type":"short","stem":"能否把这三组结果求平均值作为这只小灯泡的电阻？为什么？（3 分）","answer":"不能。取平均值的前提是各次测量的是同一个不变的电阻，差异只来自误差；而小灯泡在三个不同温度下电阻本来就不同，三组数据不是对同一个阻值的重复测量，平均值没有物理意义。更好的做法是分别说明各电压下的电阻，或关注它在额定电压 2.5 V 时约为 6.94 Ω。","explain":"","tags":["数据处理","实验评估"],"rubric":["答出不能求平均值（1 分）","说明原因是电阻随温度变化、不是误差（1 分）","给出更合理的处理方式（分电压说明或关注额定电压下的值）（1 分）"]},{"id":"phy-electric-6-m1-q3","type":"short","stem":"若闭合开关后小灯泡不亮、电流表无示数、电压表有示数且接近电源电压，故障可能出在哪里？写出判断依据。（4 分）","answer":"故障是小灯泡（或它所在的支路）断路。依据：电流表无示数说明电路中没有电流，即电路某处断开；电压表有示数且接近电源电压，说明电压表的两端通过导线与电源两极连通，断点就在电压表并联的那一段（小灯泡处），此时电压表相当于测电源电压。可断电后检查灯泡与灯座的接触是否良好、灯丝是否烧断。","explain":"","tags":["故障判断","电压表"],"rubric":["判断为小灯泡处（电压表并联的那段）断路（2 分）","说明电流表无示数表示电路断开（1 分）","说明电压表有示数接近电源电压说明断点在其并联段内（1 分）"]}]},{"id":"phy-electric-7","title":"电功与电功率：W = UIt、P = UI 与额定功率","subtitle":"人教版九年级 · 第 18 章 电功率 · 9a","grade":"9a","tags":["人教版九年级 · 第 18 章 电功率"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 18 章 电功率 · 9a"},{"type":"note","title":"问题切入","text":"同样接在 220 V 的电源上，为什么有的灯亮有的暗？电流通过用电器时究竟做了多少功？电费单上的「度」到底是什么？灯泡上标着「220 V 100 W」，实际使用时它的功率一定是 100 W 吗？"},{"type":"note","title":"一句话抓住关键","text":"电流做的功叫电功，W = UIt，单位是焦耳（J），生活用电以千瓦时（kW·h）计量，1 kW·h = 3.6×10⁶ J；电功率 P = W/t = UI，表示电流做功的快慢。铭牌上标的是额定电压与额定功率，实际功率随实际电压改变，灯泡的亮度由实际功率决定。"},{"type":"h","text":"先看现象：电能表的转盘在「报数」"},{"type":"p","text":"家里的电能表串在进户线上，用电器工作时转盘就会转动，示数一点点增加。转盘转得快，说明同样时间内消耗的电能多，也就是电流做功快——这正是电功率。电能表的示数以千瓦时为单位，两次示数之差就是这段时间里电流做的功。某一用电器单独工作时，还可以用「表盘转过的圈数 ÷ 每千瓦时的转数」算出它消耗的电能。"},{"type":"figure","figure":{"id":"fig-elec-power-1","title":"电能表接在进户线上","caption":"示数单位是千瓦时，转盘转速反映用电的快慢","view":"wide","alt":"电能表串联在家庭电路的火线与零线上，表盘标有千瓦时与每千瓦时的转数，转盘转动表示用电器正在消耗电能","prims":[{"t":"line","x1":6,"y1":18,"x2":28,"y2":18},{"t":"line","x1":72,"y1":18,"x2":94,"y2":18},{"t":"line","x1":6,"y1":30,"x2":28,"y2":30},{"t":"line","x1":72,"y1":30,"x2":94,"y2":30},{"t":"rect","x":28,"y":10,"w":44,"h":28,"rx":2,"tone":"main"},{"t":"text","x":50,"y":17,"text":"电能表","size":4.2},{"t":"text","x":50,"y":25,"text":"kW·h","size":4.6,"tone":"accent"},{"t":"text","x":50,"y":32,"text":"3000 r/(kW·h)","size":3.4,"tone":"muted"},{"t":"text","x":5,"y":18,"text":"L","anchor":"end","size":3.4,"tone":"muted"},{"t":"text","x":5,"y":30,"text":"N","anchor":"end","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":48,"text":"电流做的功越多，示数增加得越多","size":3.8,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"转盘转得越快，电流做功越快","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"电能表的示数单位是 kW·h（度），1 kW·h = 3.6×10⁶ J；算电费时用「本月用电量 × 电价」，单位必须是 kW·h。"},{"type":"h","text":"抓住哪个量：电功 W 与电功率 P 分别表示什么"},{"type":"p","text":"电流通过用电器时所做的功叫电功，用 W 表示，它取决于电压 U、电流 I 和通电时间 t：W = UIt，单位是焦耳（J）。而电功率 P 表示电流做功的快慢，P = W/t，把 W = UIt 代入就得到 P = UI，单位是瓦特（W）。用电器上标的电压、电流与时间都是同一段电路的量：W 与 P 都是针对某个用电器（或某段电路）来说的。"},{"type":"figure","figure":{"id":"fig-elec-power-2","title":"电流做功的三个量与两条公式","caption":"U、I、t 都属于同一个用电器，W = UIt，P = W/t = UI","view":"wide","alt":"电源、开关与灯泡串联成回路，标注用电器两端的电压、通过它的电流和通电时间，得到电功与电功率的公式","prims":[{"t":"line","x1":18,"y1":16,"x2":26,"y2":16},{"t":"line","x1":37,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":41.4,"y2":48},{"t":"line","x1":58.6,"y1":48,"x2":82,"y2":48},{"t":"battery","x":30,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"bulb","x":50,"y":48,"label":"用电器"},{"t":"text","x":50,"y":32,"text":"U、I、t 属于同一个用电器","size":3.6,"tone":"muted"},{"t":"text","x":30,"y":58,"text":"W = UIt","size":4.2,"tone":"accent"},{"t":"text","x":72,"y":58,"text":"P = W/t = UI","size":4.2,"tone":"accent"}]}},{"type":"note","title":"","text":"容易混淆的两件事：电功 W 是「做了多少」，电功率 P 是「做得有多快」；功率大不等于做功多，还要看时间。"},{"type":"h","text":"建立关系：额定功率与实际功率"},{"type":"p","text":"用电器铭牌上标的「220 V 100 W」，前者是额定电压、后者是额定功率，意思是这只灯泡在 220 V 电压下工作时，它的功率是 100 W（此时叫正常发光）。实际电压一旦不等于额定电压，实际功率就变了：电压低于额定电压，灯变暗、实际功率小于额定功率；电压略高于额定电压，灯更亮，但长期使用会缩短寿命。所以判断亮暗，永远看实际功率。"},{"type":"figure","figure":{"id":"fig-elec-power-3","title":"两只灯泡的铭牌与亮度","caption":"都正常发光时，额定功率大的更亮；实际电压改变时，亮度跟着实际功率变","view":"wide","alt":"两只白炽灯的铭牌分别是 220 伏 40 瓦与 220 伏 100 瓦，下面标注它们在正常发光时的电流以及实际功率与亮度的关系","prims":[{"t":"rect","x":6,"y":12,"w":40,"h":16,"rx":2,"tone":"main"},{"t":"rect","x":54,"y":12,"w":40,"h":16,"rx":2,"tone":"accent"},{"t":"text","x":26,"y":20,"text":"220 V 40 W","size":4.4},{"t":"text","x":74,"y":20,"text":"220 V 100 W","size":4.4,"tone":"accent"},{"t":"text","x":26,"y":36,"text":"正常发光电流约 0.18 A","size":3.2,"tone":"muted"},{"t":"text","x":74,"y":36,"text":"正常发光电流约 0.45 A","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":46,"text":"都在 220 V 下工作：100 W 的灯更亮","size":3.6},{"t":"text","x":50,"y":54,"text":"实际电压低于额定电压时，功率变小、灯变暗","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"亮度由实际功率决定","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"正确说法：「220 V 100 W」表示灯的额定电压与额定功率；接入 110 V 时它的实际功率约为 25 W，而不是 50 W。"},{"type":"h","text":"换个情境再想一遍：从电能表算出用电量与电费"},{"type":"p","text":"电能表两次读数之差就是这段时间内消耗的电能。例如月初读数 2134.5 kW·h、月末读数 2194.5 kW·h，本月用电 60 kW·h，折合 60 × 3.6×10⁶ J = 2.16×10⁸ J。若电价是 0.6 元/(kW·h)，本月电费就是 60 × 0.6 元 = 36 元。计算时注意单位：W = Pt 中若功率用 kW、时间用 h，结果就是 kW·h，可直接乘电价；若功率用 W、时间用 s，结果就是 J，要先除以 3.6×10⁶ 才是度。"},{"type":"figure","figure":{"id":"fig-elec-power-4","title":"由电能表的两次读数求用电量","caption":"本月用电量 = 月末读数 − 月初读数","view":"wide","alt":"两个电能表示数框，月初读数为 2134.5 千瓦时，月末读数为 2194.5 千瓦时，下方给出用电量与焦耳的换算","prims":[{"t":"rect","x":6,"y":12,"w":40,"h":22,"rx":2,"tone":"main"},{"t":"rect","x":54,"y":12,"w":40,"h":22,"rx":2,"tone":"main"},{"t":"text","x":26,"y":19,"text":"月初读数","size":3.4,"tone":"muted"},{"t":"text","x":26,"y":27,"text":"2134.5 kW·h","size":4.2},{"t":"text","x":74,"y":19,"text":"月末读数","size":3.4,"tone":"muted"},{"t":"text","x":74,"y":27,"text":"2194.5 kW·h","size":4.2},{"t":"text","x":50,"y":44,"text":"W = 2194.5 − 2134.5 = 60 kW·h","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":52,"text":"折合 60 × 3.6×10⁶ J = 2.16×10⁸ J","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"电能表的示数最后一位通常是小数（0.1 kW·h），读数时不要漏掉；两次读数必须用同一个单位。"},{"type":"h","text":"换个电压再看一次：为什么电压减半，功率变成四分之一"},{"type":"p","text":"把同一只灯泡接在不同电压下，功率怎么变？由 P = UI 与 I = U/R 联立，得到 P = U²/R（把灯丝电阻看成不变）。电压降到原来的一半，功率就降到原来的四分之一；电压升高到额定电压以上，功率比额定功率还大，灯更亮但容易烧坏。用 P-U 图像看：这是一条从原点出发向上弯曲的曲线，电压越大，功率增长得越快。"},{"type":"figure","figure":{"id":"fig-elec-power-5","title":"同一只灯泡的实际功率与电压的关系","caption":"P 与 U² 成正比，曲线向上弯曲；电压减半时功率约为原来的四分之一","view":"square","alt":"以电压为横轴、功率为纵轴的坐标图，一条从原点出发向上弯曲的曲线，电压 220 伏时功率为 100 瓦，电压降到一半时功率约为四分之一","prims":[{"t":"axis","x":20,"y":80,"w":70,"h":60,"xLabel":"U/V","yLabel":"P/W","origin":true,"grid":true,"xTicks":[{"at":0.5,"label":"110"},{"at":1,"label":"220"}],"yTicks":[{"at":0.5,"label":"50"},{"at":1,"label":"100"}]},{"t":"curve","points":[[20,80],[55,65],[72.5,46.25],[90,20]],"tone":"accent"},{"t":"curve","points":[[90,20],[90,80]],"dashed":true,"tone":"muted"},{"t":"circle","cx":55,"cy":65,"r":1.6,"fill":true,"tone":"danger"},{"t":"text","x":50,"y":10,"text":"同一只灯泡：P = U²/R","size":3.8,"tone":"accent"},{"t":"text","x":50,"y":92,"text":"电压降到一半，实际功率约降为四分之一","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"P = U²/R 与 P = I²R 由 P = UI 与欧姆定律联立得到，只适用于把电能全部转化为内能的用电器（灯泡、电热丝）；灯丝电阻实际上随温度变化，所以算出的实际功率是近似值。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["电功的公式","W = UIt","W：电功，焦耳（J）；U：电压，伏特（V）；I：电流，安培（A）；t：时间，秒（s） · 已知某用电器（或某段电路）两端的电压、通过它的电流和通电时间时使用，三个量必须属于同一个用电器、同一段时间（同一性与同时性）。变形 U = W/(It)、I = W/(Ut)、t = W/(UI) 可用于反求其它量；串联电路中电流相同，可用 W = I²Rt 比较各元件做功多少。"],["电功率的公式","P = (W)/(t) = UI","P：电功率，瓦特（W）；W：电功，焦耳（J）；t：时间，秒（s）；U：伏特（V）；I：安培（A） · P = W/t 是电功率的定义式，任何用电器都适用（只要 W 与 t 对应同一过程）；P = UI 是它的常用形式，用于由电压与电流求功率。铭牌上的额定功率由额定电压决定：当实际电压等于额定电压时 P实际 = P额。计算时注意 1 kW = 1000 W、1 h = 3600 s 的换算。"],["电功单位的换算","1 kW·h（度）= 3.6×10⁶ J；1 kW = 1000 W","生活用电与电费计算一律用 kW·h：W = Pt 中若 P 用 kW、t 用 h，得到的直接是 kW·h。物理计算中若得到的是焦耳而题目要求用度表示，要除以 3.6×10⁶。例如 1210 W 的用电器工作 5 min，W = 3.63×10⁵ J ≈ 0.1 kW·h。"],["电功率的推导式","P = I²R = (U²)/(R)","P：电功率，瓦特（W）；I：电流，安培（A）；R：电阻，欧姆（Ω）；U：电压，伏特（V） · 由 P = UI 与欧姆定律联立得到。P = U²/R 适用于已知电压与电阻求功率（如判断「电压减半则功率变为四分之一」）；P = I²R 适用于串联电路比较各元件功率（电流相同，电阻大的功率大）。两个式子都只适用于把电能全部转化为内能的用电器（灯泡、电阻丝、电热器），电动机等把电能部分转化为机械能的用电器不能用它们算功率。"]]},{"type":"h","text":"应用 · 由铭牌求电流、电阻与电能"},{"type":"note","title":"情境","text":"一只电热水壶标有「220 V 1210 W」。求它正常工作时的电流和电阻，以及正常工作 5 min 消耗的电能。"},{"type":"note","title":"模型与思路","text":"正常工作时实际电压等于额定电压、实际功率等于额定功率，所以可由 P = UI 求电流，再由 R = U/I（或用 P = U²/R 变形）求电阻；电能由 W = Pt 计算，注意时间换成秒得到焦耳。"},{"type":"list","title":"解答步骤","items":["求电流：由 P = UI 得 I = P/U = 1210 W ÷ 220 V = 5.5 A。","求电阻：R = U/I = 220 V ÷ 5.5 A = 40 Ω。","时间换算：t = 5 min = 300 s。","求电能：W = Pt = 1210 W × 300 s = 3.63×10⁵ J。","答：正常工作电流为 5.5 A，电阻为 40 Ω，5 min 消耗电能 3.63×10⁵ J（约 0.1 kW·h）。"]},{"type":"figure","figure":{"id":"fig-elec-power-6","title":"电热水壶的测量电路","caption":"电流表测通过热水壶的电流，电压表并联在它两端","view":"wide","alt":"电源、开关、电流表与电热水壶的电阻串联成回路，电压表并联在电阻两端","prims":[{"t":"line","x1":18,"y1":16,"x2":26,"y2":16},{"t":"line","x1":37,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":21.4,"y2":48},{"t":"line","x1":38.6,"y1":48,"x2":44,"y2":48},{"t":"line","x1":66,"y1":48,"x2":82,"y2":48},{"t":"battery","x":30,"y":16,"label":"电源 220 V"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"meter","x":30,"y":48,"kind":"A","label":"电流表"},{"t":"resistor","x":55,"y":48,"label":"电热水壶"},{"t":"line","x1":44,"y1":48,"x2":44,"y2":30},{"t":"line","x1":44,"y1":30,"x2":46.4,"y2":30},{"t":"line","x1":63.6,"y1":30,"x2":66,"y2":30},{"t":"line","x1":66,"y1":30,"x2":66,"y2":48},{"t":"meter","x":55,"y":30,"kind":"V","label":"电压表"},{"t":"junction","x":44,"y":48},{"t":"junction","x":66,"y":48}]}},{"type":"note","title":"结论","text":"I = 5.5 A，R = 40 Ω，W = 3.63×10⁵ J ≈ 0.1 kW·h。"},{"type":"h","text":"应用 · 由电能表算电费"},{"type":"note","title":"情境","text":"某家庭月初电能表示数为 2134.5 kW·h，月末为 2194.5 kW·h，当地电价为 0.6 元/(kW·h)。求本月用电量与电费。"},{"type":"note","title":"模型与思路","text":"两次示数之差就是电流做的功；电费 = 用电量 × 电价。用 kW·h 作单位可以直接与电价相乘，不必先换成焦耳。"},{"type":"list","title":"解答步骤","items":["本月用电量 W = 2194.5 kW·h − 2134.5 kW·h = 60 kW·h。","换算：60 kW·h = 60 × 3.6×10⁶ J = 2.16×10⁸ J。","电费 = 60 kW·h × 0.6 元/(kW·h) = 36 元。","答：本月用电 60 kW·h（合 2.16×10⁸ J），电费 36 元。"]},{"type":"note","title":"结论","text":"用电 60 kW·h，电费 36 元。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["额定功率大的灯泡一定比额定功率小的灯泡亮","灯泡的亮度由实际功率决定；只有都在额定电压下工作时，额定功率大的才更亮","把「220 V 40 W」与「220 V 100 W」两只灯串联在 220 V 电源上，电流相同，电阻大的 40 W 灯实际功率反而更大、更亮。判断亮度必须先看清是串联、并联，再看实际功率。"],["用电器的实际功率一定等于铭牌上的额定功率","只有实际电压等于额定电压时，实际功率才等于额定功率","额定功率是铭牌在额定电压下标定的值。实际电压偏低，实际功率小于额定功率（灯变暗）；实际电压偏高，实际功率大于额定功率（灯更亮，但容易被烧坏）。"],["1 度电就是 1 J，电能表上的数字单位是焦耳","1 kW·h = 3.6×10⁶ J，电能表的示数单位是千瓦时（度）","焦耳这个单位很小，生活用电量很大，所以电能表用 kW·h。计算电费时要用 kW·h 与电价相乘；若算出的电功是焦耳，必须除以 3.6×10⁶ 才能换算成度。"],["电功率大的用电器电流做的功一定多","做功的多少还要看通电时间：W = Pt","电功率表示做功的快慢。2000 W 的电热水壶工作 1 min 做功 W = 2000 W × 60 s = 1.2×10⁵ J，而 100 W 的电视工作 30 min 做功 W = 100 W × 1800 s = 1.8×10⁵ J，反而更多。"]]},{"type":"table","title":"电功与电功率（一个讲「多少」，一个讲「多快」）","head":["比较项","电功 W","电功率 P"],"rows":[["物理意义","电流做了多少功，即消耗了多少电能","电流做功的快慢"],["公式","W = UIt = Pt","P = W/t = UI"],["单位","焦耳（J）、千瓦时（kW·h）","瓦特（W）、千瓦（kW）"],["联系","W = Pt：功率越大、时间越长，做功越多","P = W/t：同一时间内做功越多，功率越大"]]},{"type":"table","title":"额定功率与实际功率（铭牌值与实际工作状态的区别）","head":["比较项","额定功率","实际功率"],"rows":[["含义","用电器在额定电压下工作时的功率，铭牌标定","用电器在实际电压下工作时的功率"],["是否变化","由用电器本身决定，不随电压改变","随实际电压改变，可能小于或大于额定功率"],["与亮度关系","只说明灯的规格，不能直接判断此刻的亮暗","实际功率越大，灯越亮"],["相等条件","实际电压等于额定电压时两者相等","实际电压等于额定电压时两者相等"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["铭牌与电功率计算","给出「220 V 1210 W」这类铭牌，求正常工作时的电流、电阻、一段时间消耗的电能。关键是先判断「正常工作时实际功率等于额定功率」，再选 P = UI、R = U/I、W = Pt 逐步求解。"],["电能表与电费计算","由两次示数之差求用电量并计算电费，或由「表盘转数 ÷ 每千瓦时转数」求某用电器单独工作时的电能与功率。易错点是把 kW·h 与 J 混用、漏掉示数的小数位。"],["额定功率与实际功率的辨析","以灯泡串联、并联为情境比较亮度，或问「接在 110 V 时实际功率是多少」，考查 P = U²/R 的应用与「亮度由实际功率决定」的口径。"],["测量小灯泡的电功率","实验题要求画出电路、说明如何判断灯泡处于额定电压状态、读数与计算 P = UI，以及滑动变阻器调节电压的作用；也考「电压表示数为额定电压时灯才正常发光」这一操作要点。"]]},{"type":"quote","text":"【材料】某电饭煲的铭牌上标有「220 V 1100 W」字样，容量 3 L。它内部有一根电阻一定且把电能全部转化为内能的电热丝。使用说明提示：煮饭时需要连续工作 30 min，煮好进入保温状态后功率只有 44 W。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】求电饭煲正常煮饭时通过电热丝的电流和电热丝的电阻。（3 分）","【设问】煮一次饭（连续工作 30 min）消耗多少电能？请用焦耳和千瓦时两种单位表示。（4 分）","【设问】若把该电饭煲接在电压为 200 V 的电源上（设电热丝电阻不变），它的实际功率约为多少？与额定功率相比有什么变化？（4 分）"]}],"questions":[{"id":"phy-electric-7-q1","type":"choice","stem":"一只小灯泡上标有「220 V 100 W」字样。把它接在 220 V 的电源上，下列说法正确的是","answer":"A","explain":"实际电压等于额定电压 220 V，所以灯泡正常发光、实际功率等于额定功率 100 W；由 P = UI 得 I = P/U = 100 W ÷ 220 V ≈ 0.45 A，A 正确。B 错：220 V 正好是额定电压，实际功率就等于 100 W。C 错：由 P = U²/R 可知电压减半时功率变为原来的四分之一，约 25 W，不是 50 W。D 错：额定功率是铭牌标定的规格，不随实际电压改变，改变的是实际功率。","options":["它正常发光，实际功率是 100 W，通过灯丝的电流约为 0.45 A","它正常发光，但实际功率小于 100 W","它两端的电压若降到 110 V，实际功率变为 50 W","它的额定功率会随实际电压的改变而改变"],"difficulty":2,"tags":["额定功率","铭牌"],"figure":{"id":"fig-elec-power-7","title":"小灯泡的铭牌","caption":"铭牌上标出额定电压与额定功率","view":"wide","alt":"一只小灯泡的铭牌，上面标有 220 伏 100 瓦字样，并注明额定电压与额定功率","prims":[{"t":"rect","x":18,"y":14,"w":64,"h":30,"rx":3,"tone":"main"},{"t":"text","x":50,"y":23,"text":"小灯泡","size":4.2},{"t":"text","x":50,"y":33,"text":"220 V 100 W","size":5,"tone":"accent"},{"t":"text","x":50,"y":40,"text":"额定电压 220 V，额定功率 100 W","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":54,"text":"接入电路后实际功率要看实际电压","size":3.8,"tone":"muted"}]}},{"id":"phy-electric-7-q2","type":"choice","stem":"关于电功和电功率，下列说法正确的是","answer":"C","explain":"C 正确：电功率描述的是做功的快慢，与做功多少不是一回事。A、B 错：做功多少由 W = Pt 决定，还要看时间——功率小的用电器通电时间足够长，做的功也可以很多。D 错：单位正好说反了，电功的单位是焦耳（或千瓦时），电功率的单位是瓦特。","options":["电功率越大，电流做的功一定越多","电流做的功越多，电功率一定越大","电功率是表示电流做功快慢的物理量，电功率越大，电流做功越快","电功的单位是瓦特，电功率的单位是焦耳"],"difficulty":1,"tags":["电功与电功率"]},{"id":"phy-electric-7-q3","type":"choice","stem":"某用电器的电功率为 500 W，它正常工作 2 h 消耗的电能为","answer":"B","explain":"W = Pt = 0.5 kW × 2 h = 1 kW·h，再换算成焦耳：1 kW·h = 3.6×10⁶ J，B 正确。A 错：0.5 kW 与 2 h 相乘得到的是 1 kW·h，不是 1000 J，把功率数值直接当成结果、又漏掉单位换算是常见错误。C 错：0.25 kW·h 是用功率除以时间得到的，不是做功。D 错：数量级不对，1 kW·h 是 3.6×10⁶ J 而不是 3.6×10³ J。","options":["1000 J","1 kW·h，合 3.6×10⁶ J","0.25 kW·h","3.6×10³ J"],"difficulty":2,"tags":["电功计算","单位换算"]},{"id":"phy-electric-7-q4","type":"choice","stem":"两只白炽灯 L1 标有「220 V 40 W」、L2 标有「220 V 100 W」，灯丝电阻分别约为 1210 Ω 和 484 Ω。下列说法正确的是","answer":"D","explain":"串联时通过两灯的电流相同，由 P = I²R 可知电阻大的实际功率大；L1 的电阻 1210 Ω 大于 L2 的 484 Ω，所以 L1 更亮，D 正确。A 错：并联时两灯电压都是 220 V，实际功率分别等于各自的额定功率，100 W 的 L2 更亮。B 错：串联时是电阻大的 L1 更亮，把并联的结论搬到串联上就会选错。C 错：亮度由实际功率决定，接入方式改变实际功率，亮度就跟着变。","options":["把它们并联接在 220 V 的电源上，L1 比 L2 亮","把它们串联接在 220 V 的电源上，L2 比 L1 亮","灯泡的亮度由额定功率决定，与接入方式无关","把它们串联接在 220 V 的电源上，L1 比 L2 亮，因为串联时电阻大的灯泡实际功率大"],"difficulty":3,"tags":["实际功率","串并联"]},{"id":"phy-electric-7-q5","type":"fill","stem":"某电热水壶的铭牌上标有「220 V 1100 W」，它正常工作时的电流是 ______ A。","answer":"5|5A|5 A","explain":"正常工作时实际功率等于额定功率，由 P = UI 得 I = P/U = 1100 W ÷ 220 V = 5 A。常见的错误是拿功率与电压相加或相减；也可以用 R = U²/P = 220² ÷ 1100 = 44 Ω，再算 I = U/R = 220 V ÷ 44 Ω = 5 A 来检验。","difficulty":1,"tags":["电功率计算"]},{"id":"phy-electric-7-q6","type":"short","stem":"一只电热水壶标有「220 V 1210 W」。求：（1）它正常工作时的电流和电阻；（2）正常工作 5 min 消耗的电能（用 J 表示）；（3）若把它接在 200 V 的电源上（设电阻不变），它的实际功率约为多少？","answer":"（1）I = P/U = 1210 W ÷ 220 V = 5.5 A；R = U/I = 220 V ÷ 5.5 A = 40 Ω；（2）t = 300 s，W = Pt = 1210 W × 300 s = 3.63×10⁵ J；（3）P实 = U′²/R = (200 V)² ÷ 40 Ω = 1000 W。","explain":"为什么这么做：正常工作时实际功率等于额定功率，这是第（1）问的前提；求电阻可以用 R = U/I，也可以用 P = U²/R 变形。第（2）问的时间必须换成秒才能与瓦特配套得到焦耳，若题目要求用度，则要再除以 3.6×10⁶（3.63×10⁵ J ≈ 0.1 kW·h）。第（3）问电压变了，但电阻是电热丝本身的性质而保持不变，所以要用新的电压配同一个电阻求功率——这正是同一性的应用；把 200 V 与 5.5 A 搭配求功率就错了。","difficulty":3,"tags":["电功率计算","实际功率"],"rubric":["第（1）问电流 5.5 A（1 分）","第（1）问电阻 40 Ω（1 分）","第（2）问时间换算正确并算出 3.63×10⁵ J（1 分）","第（3）问保持电阻不变、用 200 V 求功率得约 1000 W（1 分）"],"steps":["（1）由 P = UI 得 I = P/U = 1210 W ÷ 220 V = 5.5 A。","由 R = U/I 得 R = 220 V ÷ 5.5 A = 40 Ω。","（2）时间换算：t = 5 min = 300 s。","W = Pt = 1210 W × 300 s = 3.63×10⁵ J。","（3）电阻不变，由 P = U²/R 得 P实 = (200 V)² ÷ 40 Ω = 1000 W。","答：正常工作电流 5.5 A，电阻 40 Ω；5 min 消耗电能 3.63×10⁵ J；接在 200 V 时实际功率约 1000 W。"]},{"id":"phy-electric-7-q7","type":"short","stem":"请设计实验测量一只标有「2.5 V」字样的小灯泡的额定功率。写出器材、实验步骤、需要记录的数据，并说明如何判断灯泡处于额定电压状态、滑动变阻器起什么作用。","answer":"器材：电源、开关、电流表、电压表、滑动变阻器、小灯泡、导线若干。步骤：(1) 按图连接电路，电流表串联在电路中，电压表并联在小灯泡两端，滑动变阻器一上一下接入并把滑片调到阻值最大处，连接时开关断开；(2) 检查无误后闭合开关，移动滑片，同时观察电压表的示数；(3) 当电压表的示数恰好为 2.5 V 时，读出电流表的示数 I，记录这组数据；(4) 由 P = UI 算出小灯泡的额定功率。需要记录的数据：额定电压 2.5 V 与对应的电流 I。判断方法：电压表的示数等于灯泡的额定电压 2.5 V 时，灯泡正常发光，此时的功率就是额定功率。滑动变阻器的作用：一是通过改变接入电阻来调节灯泡两端的电压，使它达到额定电压；二是保护电路（闭合开关前调到阻值最大处）。","explain":"测量额定功率的关键不是「随便测一组算 P = UI」，而是必须把灯泡调到额定电压状态：电压表示数为 2.5 V 时读取的电流才是额定电流，算出的才是额定功率。滑动变阻器与灯泡串联，滑片移动改变接入电阻，从而改变灯泡两端的电压；若不接变阻器，灯泡的电压就固定在某个值上，往往调不到额定电压。为了看清额定状态下的亮度，还可以同时观察灯泡的发光情况。","difficulty":3,"tags":["实验探究","额定功率"],"rubric":["器材完整：电源、开关、电流表、电压表、滑动变阻器、小灯泡、导线（1 分）","电表接法正确：电流表串联、电压表并联在灯泡两端（1 分）","说明调节滑片使电压表示数恰为 2.5 V，再读电流表示数（1 分）","由 P = UI 计算额定功率（1 分）","说明滑动变阻器调节电压与保护电路的作用（1 分）"]},{"id":"phy-electric-7-q8","type":"short","stem":"请画出符合要求的电路图：电源、开关、电流表、滑动变阻器与小灯泡 L 串联，电压表并联在 L 两端，用于测量小灯泡的电功率。","answer":"见参考答案图：电流表串联在电路中，滑动变阻器「一上一下」接入，电压表并联在灯泡两端。","explain":"作图要点：测电功率要用 P = UI，所以电流表要串联测通过灯泡的电流，电压表要并联测灯泡两端的电压；为了让灯泡达到额定电压，必须串联滑动变阻器。常见错误：把电压表并联在滑动变阻器或电源两端（测的不是灯泡的电压）；把电流表并联在灯泡两端（灯泡被短路）；变阻器接成两上或两下（无法调节电压）。","difficulty":3,"tags":["电路作图","电功率"],"rubric":["小灯泡与电流表、滑动变阻器、开关、电源串联成回路（1 分）","电压表并联在小灯泡两端（1 分）","滑动变阻器「一上一下」接入，能把灯泡电压调到额定值（1 分）"],"answerFigure":{"id":"fig-elec-draw-7-ans","title":"参考答案：测量小灯泡电功率的电路","caption":"电流表串联、电压表并联在灯泡两端，变阻器一上一下接入","view":"wide","alt":"电源、开关、电流表、滑动变阻器与小灯泡串联成回路，电压表并联在小灯泡两端","prims":[{"t":"line","x1":15,"y1":14,"x2":20,"y2":14},{"t":"line","x1":31,"y1":14,"x2":38,"y2":14},{"t":"line","x1":50,"y1":14,"x2":59.4,"y2":14},{"t":"line","x1":76.6,"y1":14,"x2":84,"y2":14},{"t":"line","x1":15,"y1":14,"x2":15,"y2":48},{"t":"line","x1":84,"y1":14,"x2":84,"y2":48},{"t":"line","x1":15,"y1":48,"x2":24,"y2":48},{"t":"line","x1":48,"y1":48,"x2":53.4,"y2":48},{"t":"line","x1":70.6,"y1":48,"x2":84,"y2":48},{"t":"battery","x":24,"y":14,"label":"电源"},{"t":"switch","x":44,"y":14,"closed":true,"label":"S"},{"t":"meter","x":68,"y":14,"kind":"A","label":"电流表"},{"t":"rheostat","x":36,"y":48,"label":"滑动变阻器"},{"t":"bulb","x":62,"y":48,"label":"L"},{"t":"line","x1":53.4,"y1":48,"x2":53.4,"y2":30},{"t":"line","x1":70.6,"y1":48,"x2":70.6,"y2":30},{"t":"meter","x":62,"y":30,"kind":"V","label":"电压表"},{"t":"junction","x":70.6,"y":48},{"t":"junction","x":53.4,"y":48}]}},{"id":"phy-electric-7-m1-q1","type":"short","stem":"求电饭煲正常煮饭时通过电热丝的电流和电热丝的电阻。（3 分）","answer":"煮饭时正常工作的功率等于额定功率 1100 W，电压为 220 V。由 P = UI 得 I = P/U = 1100 W ÷ 220 V = 5 A；由 R = U/I 得 R = 220 V ÷ 5 A = 44 Ω。","explain":"","tags":["电功率计算","铭牌"],"rubric":["判断出正常工作时 P = 1100 W、U = 220 V（1 分）","算出 I = 5 A（1 分）","算出 R = 44 Ω 并写单位（1 分）"]},{"id":"phy-electric-7-m1-q2","type":"short","stem":"煮一次饭（连续工作 30 min）消耗多少电能？请用焦耳和千瓦时两种单位表示。（4 分）","answer":"t = 30 min = 1800 s，W = Pt = 1100 W × 1800 s = 1.98×10⁶ J；换算成千瓦时：W = 1.1 kW × 0.5 h = 0.55 kW·h（也可由 1.98×10⁶ J ÷ 3.6×10⁶ J/(kW·h) = 0.55 kW·h 得到）。","explain":"","tags":["电功计算","单位换算"],"rubric":["时间换算 1800 s 或 0.5 h 正确（1 分）","用 W = Pt 算出 1.98×10⁶ J（1 分）","换算得 0.55 kW·h（1 分）","两种单位都写出并注明（1 分）"]},{"id":"phy-electric-7-m1-q3","type":"short","stem":"若把该电饭煲接在电压为 200 V 的电源上（设电热丝电阻不变），它的实际功率约为多少？与额定功率相比有什么变化？（4 分）","answer":"电热丝电阻 R = 44 Ω 不变，由 P = U²/R 得 P实 = (200 V)² ÷ 44 Ω ≈ 909 W。实际功率小于额定功率 1100 W，说明实际电压低于额定电压时，用电器不能达到额定功率，加热会变慢。","explain":"","tags":["实际功率","计算"],"rubric":["写出 P = U²/R 或先算 I = U/R 再算 P = UI（1 分）","代入 200 V 与 44 Ω 正确（1 分）","结果约 909 W（允许 900～910 W）（1 分）","说明实际功率小于额定功率，用电器不能正常工作（1 分）"]}]},{"id":"phy-electric-8","title":"焦耳定律、家庭电路与安全用电","subtitle":"人教版九年级 · 第 18—19 章 焦耳定律与生活用电 · 9a","grade":"9a","tags":["人教版九年级 · 第 18—19 章 焦耳定律与生活用电"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 18—19 章 焦耳定律与生活用电 · 9a"},{"type":"note","title":"问题切入","text":"电流通过导体时为什么会发热？为什么电炉丝烧得通红，而跟它串联的导线却不怎么热？家里的电灯、插座是怎么接在火线和零线上的？为什么不能用湿手去碰开关，开关又为什么必须接在火线上？"},{"type":"note","title":"一句话抓住关键","text":"电流通过导体产生的热量由焦耳定律决定：Q = I²Rt，电流相同时电阻越大、通电时间越长，产生的热量越多。家庭电路由进户线（火线与零线）、电能表、总开关、保险装置、用电器与插座组成，各用电器并联；开关要接在火线与用电器之间，三孔插座「左零右火上接地」；安全用电的核心是不接触低压带电体、不靠近高压带电体。"},{"type":"h","text":"先看现象：电炉丝通红，导线却不热"},{"type":"p","text":"电炉工作时，电炉丝烧得通红，而与它串联的导线却几乎不发热。它们串联，通过它们的电流相同、通电时间也相同，唯一的差别是电阻：电炉丝的电阻比导线大得多。由 Q = I²Rt 可知，电流相同时电阻越大，产生的热量越多——这就是焦耳定律告诉我们的第一件事。"},{"type":"figure","figure":{"id":"fig-elec-joule-1","title":"串联的导线与电炉丝，发热多少不同","caption":"电流相同、时间相同，电阻大的电炉丝发热多","view":"wide","alt":"电源、开关、一段导线与一根电炉丝串联成回路，电炉丝的电阻远大于导线，由焦耳定律可知它产生的热量更多","prims":[{"t":"line","x1":18,"y1":16,"x2":26,"y2":16},{"t":"line","x1":37,"y1":16,"x2":62,"y2":16},{"t":"line","x1":74,"y1":16,"x2":82,"y2":16},{"t":"line","x1":18,"y1":16,"x2":18,"y2":48},{"t":"line","x1":82,"y1":16,"x2":82,"y2":48},{"t":"line","x1":18,"y1":48,"x2":21,"y2":48},{"t":"line","x1":43,"y1":48,"x2":55,"y2":48},{"t":"line","x1":77,"y1":48,"x2":82,"y2":48},{"t":"battery","x":30,"y":16,"label":"电源"},{"t":"switch","x":68,"y":16,"closed":true,"label":"S"},{"t":"resistor","x":32,"y":48,"label":"导线（R 小）"},{"t":"resistor","x":66,"y":48,"label":"电炉丝（R 大）"},{"t":"text","x":50,"y":32,"text":"串联：电流相同、时间相同","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":58,"text":"Q = I²Rt：电阻大的发热多","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"比较发热多少时，先看电流是否相同：串联时用 Q = I²Rt 比较（电阻大的发热多），并联（电压相同）时用 Q = U²t/R 比较（电阻小的发热多）。"},{"type":"h","text":"抓住哪个量：焦耳定律与它的实验"},{"type":"p","text":"焦耳定律说：电流通过导体产生的热量跟电流的二次方成正比，跟导体的电阻成正比，跟通电时间成正比，写成 Q = I²Rt。用实验验证时，把两根阻值不同的电阻丝串联在同一电路中（保证电流相同），分别给密闭容器中的空气或液体加热，用温度计示数升高的多少来比较产生热量的多少：示数升高多的那根，产生的热量多。这种把「热量多少」转换成「温度变化」的做法叫转换法。"},{"type":"figure","figure":{"id":"fig-elec-joule-2","title":"探究电热与电阻关系的装置","caption":"R₁ = 5 Ω 与 R₂ = 10 Ω 串联，电流相同，温度计示数升高多的发热多","view":"wide","alt":"两个密闭容器中各有一根电阻丝，阻值分别为 5 欧与 10 欧，两根电阻丝串联在同一电路中，容器上方各插一支温度计，10 欧那一侧的液柱更高","prims":[{"t":"rect","x":10,"y":20,"w":28,"h":18,"tone":"main"},{"t":"rect","x":62,"y":20,"w":28,"h":18,"tone":"main"},{"t":"resistor","x":24,"y":29,"w":14,"h":4},{"t":"resistor","x":76,"y":29,"w":14,"h":4},{"t":"text","x":24,"y":24,"text":"R₁ = 5 Ω","size":3},{"t":"text","x":76,"y":24,"text":"R₂ = 10 Ω","size":3},{"t":"line","x1":35,"y1":29,"x2":65,"y2":29},{"t":"line","x1":13,"y1":29,"x2":13,"y2":52},{"t":"line","x1":87,"y1":29,"x2":87,"y2":52},{"t":"line","x1":13,"y1":52,"x2":31,"y2":52},{"t":"line","x1":42,"y1":52,"x2":54,"y2":52},{"t":"line","x1":66,"y1":52,"x2":87,"y2":52},{"t":"battery","x":35,"y":52,"label":"电源"},{"t":"switch","x":60,"y":52,"closed":true,"label":"S"},{"t":"thermometer","x":24,"y":4,"h":14,"value":0.45,"label":"温度计"},{"t":"thermometer","x":76,"y":4,"h":14,"value":0.8,"label":"温度计"},{"t":"text","x":50,"y":60,"text":"电流相同，电阻越大，产生的热量越多","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"实验用「转换法」：热量看不见，就通过温度计示数（或液面高度）的变化来比较；研究电流的影响时，则让电阻相同、电流不同。"},{"type":"h","text":"建立关系：电热的利用与防止"},{"type":"p","text":"电热并不总是坏事。电饭锅、电热水壶、电热毯、电熨斗都是利用电流的热效应工作的，它们的电热丝用电阻较大、熔点较高的合金制成，能把电能几乎全部转化为内能。另一方面，电热也会带来麻烦：电视机、电脑要留散热孔，电动机要装风扇散热，而导线如果过细、接头如果松动，电阻变大、发热增多，严重时会烧坏绝缘层引起火灾。所以选择导线要按用电器的总功率来选。"},{"type":"figure","figure":{"id":"fig-elec-joule-3","title":"电热的利用与防止","caption":"同样一条规律，一边是拿来用，一边是要防","view":"wide","alt":"左侧是电热器的利用方式，用电阻大、熔点高的电热丝工作；右侧是需要散热与防止导线过热的情形","prims":[{"t":"rect","x":6,"y":12,"w":40,"h":16,"rx":2,"label":"利用电热","tone":"main"},{"t":"rect","x":54,"y":12,"w":40,"h":16,"rx":2,"label":"防止过热","tone":"danger"},{"t":"text","x":26,"y":36,"text":"电饭锅、电热水壶、电熨斗","size":3.2,"tone":"muted"},{"t":"text","x":26,"y":43,"text":"电热丝电阻大、熔点高","size":3.2,"tone":"muted"},{"t":"text","x":74,"y":36,"text":"电器留散热孔、电动机装风扇","size":3.2,"tone":"muted"},{"t":"text","x":74,"y":43,"text":"导线过细会发热甚至引起火灾","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":55,"text":"同样的 Q = I²Rt：电阻越大、时间越长，发热越多","size":3.4,"tone":"accent"}]}},{"type":"note","title":"","text":"插头插座接触不良时接触处电阻变大，由 Q = I²Rt 可知该处发热明显增多，所以插头会发烫、甚至烧焦。"},{"type":"h","text":"换个情境：家里的电路是怎样接的"},{"type":"p","text":"家庭电路的进户线有两根：火线和零线，它们之间有 220 V 的电压。电流从火线经过电能表、总开关、保险装置，再到各用电器，最后回到零线。各用电器之间是并联的，所以能各自工作、互不影响。控制电灯的开关必须接在火线与灯之间——这样断开开关时，灯泡和灯座都不与火线相连，换灯泡时才不会触电。"},{"type":"figure","figure":{"id":"fig-elec-home-1","title":"家庭电路的组成","caption":"火线、零线、总开关与一条电灯支路","view":"wide","alt":"家庭电路示意图：火线上串接总开关，电灯支路从火线经开关接灯泡再回到零线，各用电器并联在火线与零线之间","prims":[{"t":"line","x1":10,"y1":10,"x2":12,"y2":10},{"t":"line","x1":24,"y1":10,"x2":90,"y2":10},{"t":"line","x1":32,"y1":22,"x2":90,"y2":22},{"t":"switch","x":18,"y":10,"closed":true,"label":"总开关"},{"t":"line","x1":28,"y1":10,"x2":28,"y2":32},{"t":"switch","x":28,"y":38,"vertical":true,"closed":true,"label":"S"},{"t":"line","x1":28,"y1":44,"x2":28,"y2":48},{"t":"line","x1":28,"y1":48,"x2":39.4,"y2":48},{"t":"bulb","x":48,"y":48,"label":"L"},{"t":"line","x1":56.6,"y1":48,"x2":62,"y2":48},{"t":"line","x1":62,"y1":48,"x2":62,"y2":22},{"t":"junction","x":28,"y":10},{"t":"junction","x":62,"y":22},{"t":"text","x":10,"y":5,"text":"火线 L","anchor":"start","size":3.4},{"t":"text","x":34,"y":27,"text":"零线 N","anchor":"start","size":3.4},{"t":"text","x":50,"y":56,"text":"各用电器并联在火线与零线之间","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"顺序不能颠倒：电能表、总开关、保险装置依次接在火线上；若把开关接在零线上，虽然灯也能亮灭，但断开后灯座仍带电，十分危险。"},{"type":"h","text":"再想一遍：触电是怎么发生的，怎么防"},{"type":"p","text":"人体是导体，当人体成为电流路径的一部分时就会触电。最常见的单线触电：人站在地上，一只手接触到火线，电流就由火线经人体流入大地，非常危险。安全用电的原则是：不接触低压带电体，不靠近高压带电体；不用湿手扳开关、插拔插头；发现有人触电，要先切断电源或用干燥的木棒等绝缘物挑开电线，再救人；有金属外壳的用电器要用三孔插座并把外壳接地。"},{"type":"figure","figure":{"id":"fig-elec-home-2","title":"单线触电：电流经人体流入大地","caption":"人站在地上接触火线，人体就成了电流路径的一部分","view":"wide","alt":"一根火线横在上方，人站在地面上举起一只手接触火线，箭头表示电流由火线经人体流向大地","prims":[{"t":"line","x1":10,"y1":10,"x2":90,"y2":10},{"t":"line","x1":10,"y1":20,"x2":52,"y2":20},{"t":"text","x":10,"y":5,"text":"火线 L","anchor":"start","size":3.4},{"t":"text","x":10,"y":25,"text":"零线 N","anchor":"start","size":3.4},{"t":"circle","cx":60,"cy":32,"r":4.5,"tone":"main"},{"t":"line","x1":60,"y1":36.5,"x2":60,"y2":48},{"t":"line","x1":64,"y1":38,"x2":72,"y2":10},{"t":"line","x1":60,"y1":48,"x2":56,"y2":56},{"t":"line","x1":60,"y1":48,"x2":64,"y2":56},{"t":"hatch","x":50,"y":56,"w":22,"h":4},{"t":"arrow","x1":70,"y1":16,"x2":66,"y2":30,"tone":"danger","label":"I"},{"t":"arrow","x1":58,"y1":50,"x2":56,"y2":55,"tone":"danger"},{"t":"text","x":88,"y":26,"text":"电流经人体入地","anchor":"end","size":3.4,"tone":"danger"},{"t":"text","x":50,"y":61,"text":"单线触电：站在地上接触火线","size":3.6,"tone":"danger"}]}},{"type":"note","title":"","text":"两种情况都不要做：一是人体直接接触火线；二是用手去拉触电的人——那会让施救者也成为电流路径的一部分。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["焦耳定律","Q = I²Rt","Q：热量，焦耳（J）；I：电流，安培（A）；R：电阻，欧姆（Ω）；t：通电时间，秒（s） · 适用于电流通过任何导体（或任何用电器）时产生热量的计算，与导体是不是纯电阻无关。三个量必须属于同一段导体、同一段时间（同一性与同时性）。比较发热多少时要看清前提：串联时电流相同，电阻大的发热多；并联（电压相同）时电阻小的发热多，此时宜用 Q = U²t/R。"],["纯电阻用电器的电热","Q = W = UIt = Pt","Q：热量，焦耳（J）；W：电功，焦耳（J）；U：伏特（V）；I：安培（A）；t：秒（s）；P：瓦特（W） · 只适用于把电能全部转化为内能的用电器（电热水壶、电饭锅、电热毯、白炽灯）：这时电流做的功全部变成热量，Q = W。对电动机这类把电能部分转化为机械能的用电器，Q 小于 W，只能用 Q = I²Rt 计算发热。"],["电热功率","P_(热) = I²R","P热：发热功率，瓦特（W）；I：电流，安培（A）；R：电阻，欧姆（Ω） · 用于比较各元件的发热快慢（如串联电路中电阻大的元件发热功率大），或由发热功率反求电阻、电流。注意区分「用电器消耗的总功率 P = UI」与「发热功率 P热 = I²R」：纯电阻用电器两者相等；电动机的总功率大于发热功率。"]]},{"type":"h","text":"应用 · 用电器的电热计算"},{"type":"note","title":"情境","text":"一个电热水壶的电阻丝阻值为 40 Ω，接在 220 V 的电源上。求正常工作时的电流、5 min 内电阻丝产生的热量。"},{"type":"note","title":"模型与思路","text":"电热水壶把电能全部转化为内能，属于纯电阻用电器，所以可以用 I = U/R 求电流，再用 Q = I²Rt（或直接用 W = UIt）求热量。"},{"type":"list","title":"解答步骤","items":["求电流：I = U/R = 220 V ÷ 40 Ω = 5.5 A。","时间换算：t = 5 min = 300 s。","求热量：Q = I²Rt = (5.5 A)² × 40 Ω × 300 s = 3.63×10⁵ J。","检验：W = UIt = 220 V × 5.5 A × 300 s = 3.63×10⁵ J，与 Q 相同，说明电能全部转化为内能。","答：电流为 5.5 A，5 min 内产生热量 3.63×10⁵ J。"]},{"type":"figure","figure":{"id":"fig-elec-joule-4","title":"电热水壶的电热计算","caption":"纯电阻用电器：Q = W = UIt = I²Rt","view":"wide","alt":"一张计算信息图，给出电阻丝电阻 40 欧、电压 220 伏、时间 5 分钟，下面写出电流与热量的计算过程和结果","prims":[{"t":"rect","x":6,"y":10,"w":88,"h":24,"rx":3,"tone":"main"},{"t":"text","x":50,"y":17,"text":"电热水壶的电阻丝","size":4},{"t":"text","x":50,"y":24,"text":"R = 40 Ω，U = 220 V，t = 5 min","size":4,"tone":"accent"},{"t":"text","x":50,"y":30,"text":"求：电流 I 与 5 min 内产生的热量 Q","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":42,"text":"I = U/R = 220 V ÷ 40 Ω = 5.5 A","size":4,"tone":"accent"},{"t":"text","x":50,"y":49,"text":"Q = I²Rt = (5.5 A)² × 40 Ω × 300 s","size":3.4},{"t":"text","x":50,"y":56,"text":"= 3.63×10⁵ J（也可用 W = UIt 检验）","size":3.4,"tone":"muted"}]}},{"type":"note","title":"结论","text":"I = 5.5 A，Q = 3.63×10⁵ J。"},{"type":"h","text":"应用 · 为什么换大功率电器时要换粗导线"},{"type":"note","title":"情境","text":"家里同时使用电热水壶（1210 W）和电饭煲（1100 W）时，插排的导线摸起来发烫。"},{"type":"note","title":"模型与思路","text":"两个用电器并联，干路电流是两者电流之和，约为 5.5 A + 5 A = 10.5 A。导线的电阻虽小，但由 Q = I²Rt 可知，电流增大时发热量按电流的二次方增长；导线越细电阻越大，发热越多。所以大功率电器要用较粗的导线，且不要把它们都插在同一个插排上。"},{"type":"list","title":"解答步骤","items":["并联支路电流相加：I ≈ 5.5 A + 5 A = 10.5 A。","由 Q = I²Rt：电流变为原来的约 2 倍，导线的发热量约变为原来的 4 倍。","导线越细电阻越大，同样的电流下发热更多、温度更高。","结论：大功率用电器应使用足够粗的导线，并避免共用一个插排超负荷使用。"]},{"type":"note","title":"结论","text":"电流增大到约 2 倍时，导线发热约为原来的 4 倍，细导线会明显发烫。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["电阻越大，电流通过它产生的热量一定越多","必须先看电流是否相同：串联时电阻大的发热多，并联（电压相同）时电阻小的发热多","Q = I²Rt 中的 I 也会随 R 变化。并联时各支路电压相同，R 越小电流越大，由 Q = U²t/R 可知发热反而更多。判断前先确定是串联还是并联，再选合适的公式。"],["家庭电路里的开关接在火线上还是零线上都一样，反正都能控制灯","开关必须接在火线与用电器之间","接在零线上时，开关断开后灯泡与灯座仍与火线相连、仍然带电，换灯泡或擦拭时人体一接触就可能触电；接在火线上时，断开开关后灯座不带电，才安全。"],["保险丝烧断了，可以用铜丝或铁丝代替","保险丝要用电阻较大、熔点较低的铅锑合金，不能用铜丝代替","保险丝的作用是电流过大时先熔断、切断电路。铜丝、铁丝的熔点高、电阻小，电流过大时不会熔断，起不到保护作用，反而可能把导线和设备烧坏。"],["发现有人触电，应该马上用手把他拉开","应先切断电源，或用干燥的木棒等绝缘物挑开电线，再进行抢救","触电者身上可能仍与带电体接触，直接用手去拉会使施救者成为电流路径的一部分，两人都触电。断电或挑开电线是最关键的一步。"]]},{"type":"table","title":"火线与零线（家庭电路中两根进户线的区别）","head":["比较项","火线（L）","零线（N）"],"rows":[["与大地之间的电压","220 V（与大地之间有电压）","约为 0 V（在电源处与大地相连）"],["是否带电","带电，接触有触电危险","正常情况下与大地同电位，一般不触电"],["连接要求","开关、保险装置接在火线上","不能把开关接在零线上"],["用电笔辨别","测电笔氖管发光","测电笔氖管不发光"]]},{"type":"table","title":"电热的利用与防止（同一条 Q = I²Rt，两种用法）","head":["比较项","利用电热","防止电热"],"rows":[["典型例子","电饭锅、电热水壶、电熨斗、电热毯","电视机散热孔、电动机风扇、粗导线"],["做法","用电阻较大、熔点高的电热丝把电能变成内能","减小导线电阻、增大散热面积、避免超负荷"],["失守的后果","电热丝熔点低会烧断，用电器不能工作","导线过热、绝缘层烧坏，可能引起火灾"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["焦耳定律的计算与比较","给出电阻、电流与通电时间求热量，或比较串联、并联电路中哪个元件发热多。失分点是公式与前提不匹配：串联要用 Q = I²Rt，并联宜用 Q = U²t/R。"],["家庭电路的组成与故障判断","判断开关、插座、保险装置的接法是否正确；由「某灯不亮而其它用电器正常」「保险丝熔断」等现象推断故障位置（该支路断路或某处短路）。"],["安全用电常识","以湿手扳开关、用铜丝代替保险丝、电器着火用水浇、拉触电者等情境判断做法是否安全，并要求说明正确做法与理由。"],["电热的利用与防止","以电热器、插头插座发烫、导线过细、电动机散热为情境，用 Q = I²Rt 解释现象并提出改进措施。"]]},{"type":"quote","text":"【材料】小刚家的家庭电路出现了问题：客厅的电灯不亮，但同一回路上的电视、冰箱仍能正常工作。检查时他发现了三个情况：一是控制这盏灯的开关被接在零线上；二是灯座里有一根导线松脱；三是电饭煲（铭牌「220 V 1100 W」）与这盏灯接在同一个插座回路上，而该插座是三孔插座。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】客厅电灯不亮而其它用电器正常工作，故障可能出在哪里？请说明理由。（3 分）","【设问】把控制电灯的开关接在零线上有什么安全隐患？应怎样改正？（3 分）","【设问】计算：电饭煲正常工作时通过它的电流是多少？若它连续工作 20 min，产生的热量约为多少焦？（4 分）"]}],"questions":[{"id":"phy-electric-8-q1","type":"choice","stem":"如图是某同学连接的家庭电路的一部分。关于它的连接，下列说法正确的是","answer":"B","explain":"图中开关接在灯泡与零线之间，虽然能控制灯泡的亮灭，但断开开关后灯泡和灯座仍与火线相连、仍然带电，换灯泡或擦拭时可能触电，所以 B 正确。A 错：能控制灯不代表接法安全，家庭电路的安全要求是开关接在火线上。C 错：开关与灯泡并联会短路灯泡，灯泡反而不亮。D 错：用电器应接在火线与零线之间，接在零线与大地之间没有电压，灯泡不会发光。","options":["连接正确，闭合开关时灯泡正常发光，断开开关灯泡就不亮","错误：开关应接在火线与灯泡之间，否则断开开关后灯座仍与火线相连，换灯泡时有触电危险","错误：开关应与灯泡并联，这样才能控制灯泡","错误：灯泡应接在零线与大地之间才对"],"difficulty":2,"tags":["家庭电路","开关位置"],"figure":{"id":"fig-elec-home-3","title":"待判断的家庭电路连接","caption":"注意开关接在哪一根线上","view":"wide","alt":"家庭电路中火线与零线已画出，灯泡一端接在火线上，另一端通过开关接到零线上","prims":[{"t":"line","x1":10,"y1":10,"x2":90,"y2":10},{"t":"line","x1":32,"y1":22,"x2":90,"y2":22},{"t":"line","x1":20,"y1":10,"x2":20,"y2":40},{"t":"line","x1":20,"y1":40,"x2":57.4,"y2":40},{"t":"bulb","x":66,"y":40,"label":"L"},{"t":"line","x1":74.6,"y1":40,"x2":76,"y2":40},{"t":"switch","x":82,"y":40,"closed":true,"label":"S"},{"t":"line","x1":88,"y1":40,"x2":88,"y2":22},{"t":"junction","x":20,"y":10},{"t":"junction","x":88,"y":22},{"t":"text","x":10,"y":5,"text":"火线 L","anchor":"start","size":3.4},{"t":"text","x":34,"y":28,"text":"零线 N","anchor":"start","size":3.4}]}},{"id":"phy-electric-8-q2","type":"choice","stem":"两根电阻丝 R1 = 2 Ω、R2 = 6 Ω 串联后接入电路，通电时间相同。下列说法正确的是","answer":"D","explain":"串联电路中各处电流相等，通电时间也相同，由 Q = I²Rt 可知热量与电阻成正比，所以电阻大的 R2 放热多，D 正确。A 错：电阻小并不能使热量变多，反而更少。B、C 错：串联时通过两段电阻丝的电流完全相同，不存在「谁电流大」的问题——这是本题最容易被误导的地方。","options":["R1 放出的热量多，因为它的电阻小","R1 放出的热量多，因为通过它的电流大","R2 放出的热量多，因为通过它的电流大","R2 放出的热量多，因为串联时电流相同，由 Q = I²Rt 知电阻大的放热多"],"difficulty":2,"tags":["焦耳定律","串联"]},{"id":"phy-electric-8-q3","type":"choice","stem":"下列做法符合安全用电原则的是","answer":"A","explain":"A 正确：切断电源或挑开电线使触电者脱离带电体，是救护的第一步，也保护了施救者。B 错：水是导体，湿手操作电器容易触电。C 错：铜丝熔点高、电阻小，电流过大时不会熔断，起不到保护作用，容易烧坏导线与设备。D 错：带电情况下用水灭火会导电，可能造成触电，应先切断电源再用干粉灭火器灭火。","options":["发现有人触电时，先切断电源或用干燥的木棒等绝缘物把电线挑开，再进行抢救","用湿手去扳开关或插拔插头，因为这样动作更快","保险丝烧断了，用铜丝代替，因为铜丝更耐用","家用电器着火时，立即用水浇灭"],"difficulty":1,"tags":["安全用电"]},{"id":"phy-electric-8-q4","type":"choice","stem":"关于家庭电路，下列说法正确的是","answer":"C","explain":"C 正确：三孔插座按「左零右火上接地」接线，金属外壳接地后，一旦外壳带电电流会经地线流入大地，人接触外壳时就不会触电。A 错：电能表接在总开关之前（进户线处），而且它测的是消耗的电能（kW·h），不是电功率。B 错：家庭电路中各用电器并联，互不影响，一个坏了其它照常工作。D 错：保险丝要用电阻较大、熔点较低的材料，电流过大时先熔断以保护电路。","options":["电能表接在总开关之后，用来测量用电器的总电功率","家庭电路中各用电器是串联的，所以一个用电器坏了其它都不工作","三孔插座的接线是「左零右火上接地」，把金属外壳接地可以防止漏电触电","保险丝应该用熔点高、电阻小的材料制成"],"difficulty":2,"tags":["家庭电路组成","三孔插座"]},{"id":"phy-electric-8-q5","type":"fill","stem":"某电阻丝的阻值为 10 Ω，通过的电流为 2 A，通电 30 s 产生的热量是 ______ J。","answer":"1200|1200J|1200 J","explain":"由焦耳定律 Q = I²Rt 得 Q = (2 A)² × 10 Ω × 30 s = 1200 J。常见错误是把电流只乘一次（写成 Q = IRt = 600 J）——焦耳定律中电流是二次方；另外要确认电流、电阻、时间属于同一段电阻丝、同一段通电时间。","difficulty":1,"tags":["焦耳定律计算"]},{"id":"phy-electric-8-q6","type":"short","stem":"一个电热水壶的电阻丝阻值为 40 Ω，接在电压为 220 V 的电源上。求：（1）通过电阻丝的电流；（2）通电 5 min 电阻丝产生的热量；（3）若换用阻值为 20 Ω 的电阻丝（仍接在 220 V 电源上），在相同时间内产生的热量是原来的几倍？","answer":"（1）I = U/R = 220 V ÷ 40 Ω = 5.5 A；（2）t = 300 s，Q = I²Rt = (5.5 A)² × 40 Ω × 300 s = 3.63×10⁵ J；（3）电阻减半后电流变为 11 A，Q′ = (11 A)² × 20 Ω × 300 s = 7.26×10⁵ J，是原来的 2 倍。","explain":"为什么这么做：电热水壶是纯电阻用电器，用 I = U/R 求电流后用 Q = I²Rt 求热量，也可以用 Q = W = UIt 检验（220 V × 5.5 A × 300 s = 3.63×10⁵ J，结果一致）。第（3）问的关键是认清前提：电压不变（并联式接入电源），所以电阻减半时电流加倍，由 Q = I²Rt 可见电流平方变为 4 倍、电阻变为一半，总热量变为 2 倍；也可以直接用 Q = U²t/R 判断——电压不变时热量与电阻成反比，电阻减半则热量加倍。如果误以为「电阻越大发热越多」，就会答成 0.5 倍。","difficulty":3,"tags":["焦耳定律计算","纯电阻"],"rubric":["第（1）问电流 5.5 A（1 分）","第（2）问时间换算并算出 3.63×10⁵ J（1 分）","第（3）问先求出新的电流 11 A（1 分）","第（3）问结果 2 倍，并说明电压不变时热量与电阻成反比（1 分）"],"steps":["（1）由 I = U/R 得 I = 220 V ÷ 40 Ω = 5.5 A。","（2）时间换算：t = 5 min = 300 s。","Q = I²Rt = (5.5 A)² × 40 Ω × 300 s = 3.63×10⁵ J（也可用 Q = W = UIt 检验）。","（3）电压不变，电阻变为 20 Ω 时 I′ = 220 V ÷ 20 Ω = 11 A。","Q′ = I′²R′t = (11 A)² × 20 Ω × 300 s = 7.26×10⁵ J，Q′/Q = 2，即为原来的 2 倍。","答：电流为 5.5 A；5 min 产生热量 3.63×10⁵ J；换用 20 Ω 电阻丝后热量是原来的 2 倍。"]},{"id":"phy-electric-8-q7","type":"short","stem":"请设计实验探究「电流通过导体产生的热量与电阻的关系」。写出器材、实验步骤、比较热量的方法，以及为使结论可靠应采取的措施。","answer":"器材：电源、开关、两根阻值不同的电阻丝（如 5 Ω 与 10 Ω）、两个相同的密闭容器（内装等量空气或煤油并各插一支温度计）、导线若干。步骤：(1) 把两根电阻丝串联接入电路，保证通过它们的电流相同、通电时间相同；(2) 闭合开关，同时开始计时；(3) 通电一段时间后，比较两支温度计示数升高的多少。比较热量的方法：热量看不见，用温度计示数升高（或玻璃管中液面上升的高度）来反映，这种方法叫转换法。为使结论可靠：两容器与两支温度计应规格相同、容器内装的空气（或煤油）质量相同；除电阻外其它条件都要相同（控制变量）；可以换用不同阻值的电阻丝多做几次。结论：在电流和通电时间相同时，电阻越大，产生的热量越多。","explain":"实验设计的两个关键词是控制变量与转换法：研究热量与电阻的关系，就必须让电流和通电时间相同，所以两根电阻丝串联；热量无法直接测量，就用温度计示数的变化（或液面高度变化）间接比较。若两根电阻丝并联，通过它们的电流不同，无法单独研究电阻的影响。还应注意容器与温度计的规格要相同，否则示数差异不能反映热量的差异。","difficulty":3,"tags":["实验探究","焦耳定律"],"rubric":["器材完整：电源、开关、两根阻值不同的电阻丝、密闭容器、温度计（1 分）","把两根电阻丝串联，保证电流相同、通电时间相同（1 分）","用温度计示数升高（或液面变化）比较热量，指明是转换法（1 分）","说明控制变量：容器、温度计规格与液体质量相同，只改变电阻（1 分）"]},{"id":"phy-electric-8-q8","type":"short","stem":"请把开关 S 与灯泡 L 正确接入家庭电路的火线与零线之间，画出电路图（要求开关能控制灯泡，并符合安全用电要求）。","answer":"见参考答案图：灯泡一端接零线，另一端经开关接到火线；开关接在火线与灯泡之间。","explain":"作图要点：用电器要接在火线与零线之间才能工作；开关必须串接在火线一侧，使断开开关后灯泡与灯座脱离火线、不带电。常见错误：把开关画在零线一侧（断开后灯座仍带电，换灯泡有危险）；把灯泡直接接在火线与零线之间而不接开关（灯不能控制）；把灯泡接在火线与地线之间（不能正常工作，也没有安全保护作用）。","difficulty":3,"tags":["电路作图","家庭电路"],"rubric":["用电器（灯泡）接在火线与零线之间，形成工作回路（1 分）","开关串接在火线与灯泡之间，没有接在零线一侧（1 分）","火线、零线标注清楚，灯泡与开关符号正确、导线不留缺口（1 分）"],"answerFigure":{"id":"fig-elec-draw-8-ans","title":"参考答案：开关接在火线与灯泡之间","caption":"开关在火线一侧，断开后灯座不带电","view":"wide","alt":"家庭电路中火线与零线已画出，火线经开关接到灯泡的一端，灯泡的另一端接到零线","prims":[{"t":"line","x1":10,"y1":10,"x2":90,"y2":10},{"t":"line","x1":32,"y1":22,"x2":90,"y2":22},{"t":"line","x1":20,"y1":10,"x2":20,"y2":40},{"t":"line","x1":20,"y1":40,"x2":44,"y2":40},{"t":"switch","x":50,"y":40,"closed":true,"label":"S"},{"t":"line","x1":56,"y1":40,"x2":57.4,"y2":40},{"t":"bulb","x":66,"y":40,"label":"L"},{"t":"line","x1":74.6,"y1":40,"x2":80,"y2":40},{"t":"line","x1":80,"y1":40,"x2":80,"y2":22},{"t":"junction","x":20,"y":10},{"t":"junction","x":80,"y":22},{"t":"text","x":10,"y":5,"text":"火线 L","anchor":"start","size":3.4},{"t":"text","x":34,"y":28,"text":"零线 N","anchor":"start","size":3.4},{"t":"text","x":50,"y":54,"text":"开关接在火线与灯泡之间","size":3.8,"tone":"accent"}]}},{"id":"phy-electric-8-m1-q1","type":"short","stem":"客厅电灯不亮而其它用电器正常工作，故障可能出在哪里？请说明理由。（3 分）","answer":"故障出在电灯所在的这条支路上，可能是灯座里的导线松脱造成断路。理由：家庭电路中各用电器是并联的，一条支路断开不影响其它支路，所以电视、冰箱仍能工作；如果是进户线、电能表或总开关处断路，所有用电器都会停止工作。","explain":"","tags":["家庭电路故障","并联"],"rubric":["判断为电灯所在支路的断路（1 分）","说明各用电器并联、互不影响（1 分）","排除进户线或总开关故障（1 分）"]},{"id":"phy-electric-8-m1-q2","type":"short","stem":"把控制电灯的开关接在零线上有什么安全隐患？应怎样改正？（3 分）","answer":"开关接在零线上时，断开开关只是切断了灯泡与零线的连接，灯泡和灯座仍然与火线相连、仍然带电；换灯泡或擦拭灯泡时人体接触灯座就可能触电。改正方法：把开关改接在火线与灯泡之间，这样断开开关后灯座不带电，操作才安全。","explain":"","tags":["安全用电","开关位置"],"rubric":["指出断开开关后灯座仍与火线相连、带电（1 分）","说明由此带来的触电危险（1 分）","给出正确接法：开关接在火线与灯之间（1 分）"]},{"id":"phy-electric-8-m1-q3","type":"short","stem":"计算：电饭煲正常工作时通过它的电流是多少？若它连续工作 20 min，产生的热量约为多少焦？（4 分）","answer":"正常工作时的功率等于额定功率 1100 W，由 P = UI 得 I = P/U = 1100 W ÷ 220 V = 5 A。电饭煲把电能全部转化为内能，属于纯电阻用电器，所以 Q = W = Pt = 1100 W × 1200 s = 1.32×10⁶ J。","explain":"","tags":["焦耳定律计算","纯电阻"],"rubric":["算出电流 I = 5 A（1 分）","时间换算 20 min = 1200 s（1 分）","判断 Q = W 并用 W = Pt 计算（1 分）","结果 1.32×10⁶ J 并写单位（1 分）"]}]}];
